{
  "name": "MotionCraft AI",
  "description": "Transform static images into stunning videos using Gemini Veo. Upload an image, choose a motion style, and bring your visuals to life."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AspectRatio {
  PORTRAIT = '9:16',
  LANDSCAPE = '16:9',
}

export enum Resolution {
  HD_720P = '720p',
  FHD_1080P = '1080p',
}

export interface MotionPreset {
  id: string;
  name: string;
  description: string;
  promptSuffix: string;
  icon: string;
}

export interface GeneratedVideo {
  uri: string;
  mimeType: string;
}

export interface GenerationConfig {
  motionId: string;
  customPrompt: string;
  aspectRatio: AspectRatio;
  resolution: Resolution;
}

import { MotionPreset } from './types';

