  {
    id: 'cinematic-zoom',
    name: 'Cinematic Zoom',
    description: 'Slow, dramatic zoom into the subject',
    promptSuffix: 'Slow cinematic camera zoom in towards the main subject, high quality, smooth motion.',
    icon: 'ZoomIn'
  },
  {
    id: 'orbit',
    name: 'Orbit',
    description: 'Smooth rotation around the center',
    promptSuffix: 'Smooth camera orbit rotation around the central subject, keeping it in focus.',
    icon: 'RotateCw'
  },
  {
    id: 'pan-vertical',
    name: 'Vertical Pan',
    description: 'Elegant vertical camera movement',
    promptSuffix: 'Slow vertical camera pan from bottom to top, revealing the scene.',
    icon: 'ArrowUp'
  },
  {
    id: 'pan-lateral',
    name: 'Lateral Slide',
    description: 'Side-to-side tracking shot',
