export const VEO_MODEL = 'veo-3.1-fast-generate-preview';

import { GoogleGenAI } from "@google/genai";
import { AspectRatio, Resolution } from "../types";
import { VEO_MODEL } from "../constants";

// Helper to remove data URL prefix
const stripBase64Prefix = (base64: string) => {
  return base64.replace(/^data:image\/[a-z]+;base64,/, "");
};

export const generateVideo = async (
  apiKey: string,
  imageBase64: string,
  prompt: string,
  aspectRatio: AspectRatio,
  resolution: Resolution
): Promise<string> => {
  // Always create a new instance to ensure fresh API key usage
  const ai = new GoogleGenAI({ apiKey });

  try {
    const cleanBase64 = stripBase64Prefix(imageBase64);

    console.log("Starting video generation with prompt:", prompt);

    let operation = await ai.models.generateVideos({
      model: VEO_MODEL,
      prompt: prompt,
      image: {
        imageBytes: cleanBase64,
        mimeType: 'image/png', // We'll convert/assume PNG or JPEG in the UI handler, Veo is flexible with standard image types
      },
      config: {
        numberOfVideos: 1,
        resolution: resolution,
        aspectRatio: aspectRatio,
      }
    });

    console.log("Operation started, polling for completion...");

    // Poll until done
    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 5000)); // Poll every 5 seconds
      operation = await ai.operations.getVideosOperation({ operation: operation });
      console.log("Polling status...", operation.metadata);
    }

    if (operation.error) {
        throw new Error(operation.error.message || "Unknown error during video generation");
    }

    const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;

    if (!videoUri) {
      throw new Error("No video URI returned from the API.");
    }

    // The URI needs the API key appended to be downloadable/playable
    return `${videoUri}&key=${apiKey}`;

  } catch (error) {
    console.error("Video generation failed:", error);
    throw error;
  }
};

import React from 'react';
import { Loader2 } from 'lucide-react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading = false, 
  icon,
  className = '',
  disabled,
  ...props 
}) => {
  const baseStyles = "flex items-center justify-center px-4 py-2.5 rounded-lg font-medium transition-all duration-200 text-sm focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[#0f0f11] disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-indigo-600 hover:bg-indigo-500 text-white focus:ring-indigo-500 shadow-lg shadow-indigo-900/20",
    secondary: "bg-[#27272a] hover:bg-[#3f3f46] text-gray-200 focus:ring-gray-500 border border-[#3f3f46]",
    danger: "bg-red-500/10 hover:bg-red-500/20 text-red-500 focus:ring-red-500 border border-red-500/20",
    ghost: "bg-transparent hover:bg-white/5 text-gray-400 hover:text-white"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
      ) : icon ? (
        <span className="mr-2">{icon}</span>
      ) : null}
      {children}
    </button>
  );
};

import React from 'react';
import { MotionPreset } from '../types';
import * as Icons from 'lucide-react';

interface MotionCardProps {
  preset: MotionPreset;
  isSelected: boolean;
  onClick: () => void;
}

export const MotionCard: React.FC<MotionCardProps> = ({ preset, isSelected, onClick }) => {
