import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Download, Play, Video, Settings2, Image as ImageIcon, X, Wand2, Info } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { AspectRatio, Resolution, GenerationConfig } from './types';
import { generateVideo } from './services/geminiService';

// Declare global type for aistudio
declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const App: React.FC = () => {
  // State
  const [apiKeyReady, setApiKeyReady] = useState<boolean>(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generationTime, setGenerationTime] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Configuration State
  const [config, setConfig] = useState<GenerationConfig>({
    motionId: MOTION_PRESETS[0].id,
    customPrompt: '',
    aspectRatio: AspectRatio.PORTRAIT,
    resolution: Resolution.HD_720P, // Use 720p for speed/consistency in preview
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | null>(null);

  // Check API Key on Mount
  useEffect(() => {
    const checkApiKey = async () => {
      if (window.aistudio && window.aistudio.hasSelectedApiKey) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeyReady(hasKey);
      } else {
        // Fallback for dev environment without aistudio wrapper if needed, 
        // but strictly we wait for user selection per requirements.
        setApiKeyReady(false);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      try {
        await window.aistudio.openSelectKey();
        // Assume success after dialog closes
        setApiKeyReady(true);
      } catch (e) {
        console.error("Failed to select key", e);
        setError("Failed to select API key. Please try again.");
      }
    }
  };

  // Image Upload Handler
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const result = e.target?.result as string;
        setSelectedImage(result);
        setGeneratedVideoUrl(null); // Reset video when new image loaded
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setGeneratedVideoUrl(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Generation Handler
  const handleGenerate = async () => {
    if (!selectedImage) return;
    if (!process.env.API_KEY) {
      setError("API Key not found in environment. Please select a key.");
      setApiKeyReady(false);
      return;
    }

    setIsGenerating(true);
    setError(null);
    setGenerationTime(0);

    // Start Timer
    timerRef.current = window.setInterval(() => {
      setGenerationTime(prev => prev + 1);
    }, 1000);

    try {
      const selectedPreset = MOTION_PRESETS.find(p => p.id === config.motionId);
      const prompt = selectedPreset 
        ? `${selectedPreset.promptSuffix} ${config.customPrompt}` 
        : config.customPrompt || "Cinematic motion.";

      const videoUrl = await generateVideo(
        process.env.API_KEY,
        selectedImage,
        prompt,
        config.aspectRatio,
        config.resolution
      );

      setGeneratedVideoUrl(videoUrl);
    } catch (err: any) {
      let msg = "Failed to generate video.";
      if (err.message?.includes("Requested entity was not found")) {
        msg = "API Key invalid or project not found. Please re-select your key.";
        setApiKeyReady(false);
      } else {
        msg = err.message || msg;
      }
      setError(msg);
    } finally {
      setIsGenerating(false);
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }
  };

  const handleDownload = async () => {
    if (!generatedVideoUrl) return;

    try {
      // Fetch the blob to force a proper download filename
      const response = await fetch(generatedVideoUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `motioncraft-${Date.now()}.mp4`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (e) {
      console.error("Download failed", e);
      // Fallback
      window.open(generatedVideoUrl, '_blank');
    }
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100">

      {/* 1. Left Sidebar: Header & Image & History (Mock) */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
              <Video className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Powered by Gemini Veo</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          {!apiKeyReady ? (
            <div className="bg-red-900/10 border border-red-900/30 rounded-xl p-4 mb-6">
              <h3 className="text-red-400 font-medium text-sm mb-2">API Key Required</h3>
              <p className="text-xs text-gray-500 mb-3">You need a paid API key to use the Veo model for video generation.</p>
              <Button onClick={handleSelectKey} variant="primary" className="w-full text-xs">
                Select API Key
              </Button>
              <div className="mt-2 text-[10px] text-gray-500 text-center">
                <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer" className="underline hover:text-gray-300">
                  Billing Information
                </a>
              </div>
            </div>
          ) : (
            <div className="flex items-center gap-2 mb-6 px-3 py-2 bg-[#18181b] rounded-lg border border-[#27272a]">
               <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>
               <span className="text-xs text-gray-400">API Key Active</span>
            </div>
          )}

          <div className="space-y-4">
             <label className="block">
               <span className="text-sm font-medium text-gray-300 mb-2 block">Input Image</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">PNG, JPG up to 10MB</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a]">
                    <img src={selectedImage} alt="Input" className="w-full h-auto object-cover" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             {selectedImage && (
               <div className="mt-8">
                 <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Generation Specs</h3>
                 <div className="grid grid-cols-2 gap-3">
                    <div className="bg-[#18181b] p-3 rounded-lg border border-[#27272a]">
                        <span className="text-xs text-gray-500 block mb-1">Ratio</span>
                        <span className="text-sm font-medium text-gray-200">{config.aspectRatio}</span>
                    </div>
                    <div className="bg-[#18181b] p-3 rounded-lg border border-[#27272a]">
                        <span className="text-xs text-gray-500 block mb-1">Quality</span>
                        <span className="text-sm font-medium text-gray-200">{config.resolution}</span>
                    </div>
                 </div>
               </div>
             )}
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        <div className="flex-1 flex items-center justify-center p-8 overflow-hidden">
          {isGenerating ? (
            <div className="flex flex-col items-center justify-center animate-pulse">
               <div className="relative w-24 h-24 mb-6">
                 <div className="absolute inset-0 border-4 border-indigo-500/20 rounded-full"></div>
                 <div className="absolute inset-0 border-t-4 border-indigo-500 rounded-full animate-spin"></div>
                 <Wand2 className="absolute inset-0 m-auto text-indigo-400 w-8 h-8 animate-pulse" />
               </div>
               <h2 className="text-2xl font-light text-white mb-2">Generating Video...</h2>
               <p className="text-gray-500 text-sm">Elapsed: {generationTime}s (This may take 1-2 minutes)</p>
               <p className="text-indigo-400/60 text-xs mt-4 max-w-xs text-center">Gemini Veo is analyzing your image and dreaming up movement.</p>
            </div>
          ) : generatedVideoUrl ? (
             <div className="relative w-full h-full flex items-center justify-center">
                <video 
                  src={generatedVideoUrl} 
                  controls 
                  autoPlay 
                  loop 
                  className="max-w-full max-h-full rounded-lg shadow-2xl border border-[#27272a]"
                />
             </div>
          ) : selectedImage ? (
             <div className="relative w-full h-full flex items-center justify-center opacity-50 grayscale-[0.3]">
                <img 
                  src={selectedImage} 
                  alt="Preview" 
                  className="max-w-full max-h-full object-contain rounded-lg"
                />
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="bg-black/50 backdrop-blur-sm px-6 py-3 rounded-full border border-white/10 flex items-center gap-3">
                    <Play size={18} className="text-white" />
                    <span className="text-sm font-medium text-white">Preview Mode</span>
                  </div>
                </div>
             </div>
          ) : (
            <div className="text-center">
              <div className="w-20 h-20 bg-[#18181b] rounded-3xl flex items-center justify-center mx-auto mb-6 rotate-12 border border-[#27272a]">
                <ImageIcon className="text-gray-600 w-10 h-10 -rotate-12" />
              </div>
              <h2 className="text-xl font-medium text-gray-300 mb-2">Ready to Create?</h2>
              <p className="text-gray-500 max-w-md mx-auto">Upload an image from the sidebar to start applying cinematic motions.</p>
            </div>
          )}
        </div>

        {/* Error Toast */}
        {error && (
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-red-500/10 border border-red-500/20 text-red-400 px-6 py-3 rounded-full backdrop-blur-xl flex items-center gap-3 shadow-xl z-50">
            <Info size={18} />
            <span className="text-sm font-medium">{error}</span>
            <button onClick={() => setError(null)} className="ml-2 hover:text-white"><X size={14}/></button>
          </div>
        )}
      </main>

      {/* 3. Right Sidebar: Controls */}
      <aside className="w-96 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a] flex items-center justify-between">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            Parameters
          </h2>
          {generatedVideoUrl && (
             <Button variant="ghost" className="h-8 w-8 p-0 rounded-full" onClick={() => setGeneratedVideoUrl(null)}>
                <Settings2 size={14} />
             </Button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {/* Motion Presets */}
          <section>
            <div className="flex items-center justify-between mb-4">
               <h3 className="text-sm font-medium text-gray-400">Motion Style</h3>
            </div>
            <div className="grid grid-cols-1 gap-3">
              {MOTION_PRESETS.map((preset) => (
                <MotionCard 
                  key={preset.id}
                  preset={preset}
                  isSelected={config.motionId === preset.id}
                  onClick={() => setConfig(prev => ({ ...prev, motionId: preset.id }))}
                />
              ))}
            </div>
          </section>

          {/* Prompt Override */}
          <section>
             <h3 className="text-sm font-medium text-gray-400 mb-3">Creative Prompt (Optional)</h3>
             <textarea 
               value={config.customPrompt}
               onChange={(e) => setConfig(prev => ({ ...prev, customPrompt: e.target.value }))}
               placeholder="e.g. Make the lighting more dramatic, add floating dust particles..."
               className="w-full bg-[#18181b] border border-[#27272a] rounded-xl p-3 text-sm text-gray-200 placeholder-gray-600 focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500 outline-none resize-none h-24 transition-all"
             />
          </section>

          {/* Aspect Ratio */}
          <section>
            <h3 className="text-sm font-medium text-gray-400 mb-3">Aspect Ratio</h3>
            <div className="grid grid-cols-2 gap-3">
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.PORTRAIT }))}
                 className={`flex items-center justify-center gap-2 py-3 rounded-lg border text-sm font-medium transition-all ${config.aspectRatio === AspectRatio.PORTRAIT ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-3 h-5 border-2 border-current rounded-sm"></div>
                 9:16 (Story)
               </button>
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.LANDSCAPE }))}
                 className={`flex items-center justify-center gap-2 py-3 rounded-lg border text-sm font-medium transition-all ${config.aspectRatio === AspectRatio.LANDSCAPE ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-5 h-3 border-2 border-current rounded-sm"></div>
                 16:9 (Cinema)
               </button>
            </div>
          </section>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
          {generatedVideoUrl ? (
             <Button 
                variant="primary" 
                className="w-full py-4 text-base bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 border-0" 
                onClick={handleDownload}
                icon={<Download size={20} />}
             >
                Export Video
             </Button>
          ) : (
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 border-0 disabled:opacity-50"
              onClick={handleGenerate}
              isLoading={isGenerating}
              disabled={!selectedImage || !apiKeyReady}
              icon={<Wand2 size={20} />}
            >
              {isGenerating ? 'Generating...' : 'Generate Motion'}
            </Button>
          )}
        </div>
      </aside>

    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Download, Play, Video, Settings2, Image as ImageIcon, X, Wand2, Info } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { AspectRatio, Resolution, GenerationConfig } from './types';
import { generateVideo } from './services/geminiService';

// Declare global type for aistudio by augmenting the interface expected by the environment
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const App: React.FC = () => {
  // State
  const [apiKeyReady, setApiKeyReady] = useState<boolean>(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generationTime, setGenerationTime] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Configuration State
  const [config, setConfig] = useState<GenerationConfig>({
    motionId: MOTION_PRESETS[0].id,
    customPrompt: '',
    aspectRatio: AspectRatio.PORTRAIT,
    resolution: Resolution.HD_720P, // Use 720p for speed/consistency in preview
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const timerRef = useRef<number | null>(null);

  // Check API Key on Mount
  useEffect(() => {
    const checkApiKey = async () => {
      // Access window.aistudio safely
      if (window.aistudio && window.aistudio.hasSelectedApiKey) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeyReady(hasKey);
      } else {
        // Fallback for dev environment without aistudio wrapper if needed, 
        // but strictly we wait for user selection per requirements.
        setApiKeyReady(false);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      try {
        await window.aistudio.openSelectKey();
        // Assume success after dialog closes
        setApiKeyReady(true);
      } catch (e) {
        console.error("Failed to select key", e);
        setError("Failed to select API key. Please try again.");
      }
    }
  };

  // Image Upload Handler
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const result = e.target?.result as string;
        setSelectedImage(result);
        setGeneratedVideoUrl(null); // Reset video when new image loaded
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setGeneratedVideoUrl(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Generation Handler
  const handleGenerate = async () => {
    if (!selectedImage) return;
    if (!process.env.API_KEY) {
      setError("API Key not found in environment. Please select a key.");
      setApiKeyReady(false);
      return;
    }

    setIsGenerating(true);
    setError(null);
    setGenerationTime(0);

    // Start Timer
    timerRef.current = window.setInterval(() => {
      setGenerationTime(prev => prev + 1);
    }, 1000);

    try {
      const selectedPreset = MOTION_PRESETS.find(p => p.id === config.motionId);
      const prompt = selectedPreset 
        ? `${selectedPreset.promptSuffix} ${config.customPrompt}` 
        : config.customPrompt || "Cinematic motion.";

      const videoUrl = await generateVideo(
        process.env.API_KEY,
        selectedImage,
        prompt,
        config.aspectRatio,
        config.resolution
      );

      setGeneratedVideoUrl(videoUrl);
    } catch (err: any) {
      let msg = "Failed to generate video.";
      if (err.message?.includes("Requested entity was not found")) {
        msg = "API Key invalid or project not found. Please re-select your key.";
        setApiKeyReady(false);
      } else {
        msg = err.message || msg;
      }
      setError(msg);
    } finally {
      setIsGenerating(false);
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }
  };

  const handleDownload = async () => {
    if (!generatedVideoUrl) return;

    try {
      // Fetch the blob to force a proper download filename
      const response = await fetch(generatedVideoUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `motioncraft-${Date.now()}.mp4`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (e) {
      console.error("Download failed", e);
      // Fallback
      window.open(generatedVideoUrl, '_blank');
    }
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100">

      {/* 1. Left Sidebar: Header & Image & History (Mock) */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
              <Video className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Powered by Gemini Veo</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          {!apiKeyReady ? (
            <div className="bg-red-900/10 border border-red-900/30 rounded-xl p-4 mb-6">
              <h3 className="text-red-400 font-medium text-sm mb-2">API Key Required</h3>
              <p className="text-xs text-gray-500 mb-3">You need a paid API key to use the Veo model for video generation.</p>
              <Button onClick={handleSelectKey} variant="primary" className="w-full text-xs">
                Select API Key
              </Button>
              <div className="mt-2 text-[10px] text-gray-500 text-center">
                <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer" className="underline hover:text-gray-300">
                  Billing Information
                </a>
              </div>
            </div>
          ) : (
            <div className="flex items-center gap-2 mb-6 px-3 py-2 bg-[#18181b] rounded-lg border border-[#27272a]">
               <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>
               <span className="text-xs text-gray-400">API Key Active</span>
            </div>
          )}

          <div className="space-y-4">
             <label className="block">
               <span className="text-sm font-medium text-gray-300 mb-2 block">Input Image</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">PNG, JPG up to 10MB</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a]">
                    <img src={selectedImage} alt="Input" className="w-full h-auto object-cover" />
                    <button 
