import { MotionPreset } from '../types';

// Easing function: Ease In Out Quad
const easeInOutQuad = (t: number): number => {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
};

// Simple noise function for shake
const noise = (t: number) => {
    return Math.sin(t * 10) * 0.5 + Math.sin(t * 23) * 0.25 + Math.sin(t * 47) * 0.125;
}

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  progress: number, // 0 to 1
  preset: MotionPreset,
  canvasWidth: number,
  canvasHeight: number
) => {
  const { params } = preset;

  // Ease the progress
  const t = easeInOutQuad(progress);

  // Calculate current parameters
  let scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
  let xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
  let yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
  let rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;

  // Add Shake noise if type is shake
  if (preset.type === 'shake') {
      const shakeIntensity = 0.02 * canvasWidth;
      xOffset += noise(progress * 20) * shakeIntensity;
      yOffset += noise(progress * 15 + 100) * shakeIntensity;
      rotation += noise(progress * 10 + 200) * 0.5;
  }

  // Clear canvas
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  // Transformations
  ctx.save();
  ctx.translate(canvasWidth / 2 + xOffset, canvasHeight / 2 + yOffset);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(scale, scale);

  // Draw Image Centered
  // We need to cover the canvas, so we calculate "cover" dimensions
  const imgRatio = image.width / image.height;
  const canvasRatio = canvasWidth / canvasHeight;

  let drawWidth, drawHeight;

  if (imgRatio > canvasRatio) {
    drawHeight = canvasHeight;
    drawWidth = canvasHeight * imgRatio;
  } else {
    drawWidth = canvasWidth;
    drawHeight = canvasWidth / imgRatio;
  }

  ctx.drawImage(image, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
  ctx.restore();
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { AspectRatio, MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5, // Default duration in seconds
    aspectRatio: AspectRatio.PORTRAIT,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds
    const duration = config.duration;

    // Loop
    const t = (elapsed % duration) / duration;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = MOTION_PRESETS.find(p => p.id === config.presetId);

        if (ctx && preset) {
            // Set canvas size based on aspect ratio
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            // Calculate target dimensions
            let width = containerWidth;
            let height = containerHeight;

            if (config.aspectRatio === AspectRatio.PORTRAIT) {
                 // 9:16
                 const targetRatio = 9/16;
                 if (width / height > targetRatio) {
                     width = height * targetRatio;
                 } else {
                     height = width / targetRatio;
                 }
            } else if (config.aspectRatio === AspectRatio.LANDSCAPE) {
                 // 16:9
                 const targetRatio = 16/9;
                 if (width / height > targetRatio) {
                    height = width / targetRatio; // constrain by width
                 } else {
                    width = height * targetRatio;
                 }
            } else {
                // Square
                const size = Math.min(width, height);
                width = size;
                height = size;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            renderFrame(ctx, imageElement, t, preset, width, height);
        }
    }

    if (isPlaying) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying]);

  useEffect(() => {
    if (isPlaying && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording (guarantees one full loop)
    const fps = 60;
    const totalFrames = config.duration * fps;
    const preset = MOTION_PRESETS.find(p => p.id === config.presetId);

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // We use the actual canvas size (already set)
    // We need to "normalize" the coordinate system for the render function which expects the CSS size
    // But since we scaled the context with DPR, we pass the CSS size to renderFrame
    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= totalFrames; i++) {
            const t = i / totalFrames;
            renderFrame(ctx, imageElement, t, preset, width, height);
            // Wait for frame interval to keep recording realistic (though captureStream handles stream)
            // Actually for captureStream we just need to draw.
            // But we need to give the MediaRecorder time to capture frames.
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

