     const sineWave = (Math.sin(progress * Math.PI * 2 * freq) + 1) / 2;

     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * sineWave;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     rotation = params.rotationStart;

  } else if (preset.type === 'swing') {
     const freq = params.frequency || 1;
     const sineWave = Math.sin(progress * Math.PI * 2 * freq);

     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * 0.5 * sineWave;
     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;

  } else if (preset.type === 'float') {
     const freq = params.frequency || 0.5;
     const sineX = Math.sin(progress * Math.PI * 2 * freq);
     const cosY = Math.cos(progress * Math.PI * 2 * freq * 0.7);

     const floatAmp = 0.03 * canvasWidth;

     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;

     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth + sineX * floatAmp;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight + cosY * floatAmp;

  } else {
     // Standard Linear Interpolation
     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;
  }

  // Add Shake noise (additive)
  if (preset.type === 'shake') {
      const shakeIntensity = 0.02 * canvasWidth;
      xOffset += noise(progress * 20) * shakeIntensity;
      yOffset += noise(progress * 15 + 100) * shakeIntensity;
      rotation += noise(progress * 10 + 200) * 0.5;
  }

  // 3. Rotation Safety Logic
  // If rotated, we need extra scale to ensure corners don't expose background.
  if (Math.abs(rotation) > 0.1) {
      const rotationRad = Math.abs(rotation * Math.PI / 180);
      // Heuristic boost: roughly 1.0 at 0deg, increasing with angle
      const rotationScaleBoost = 1 + (rotationRad * 0.6); 
      scale = scale * rotationScaleBoost;
  }

  // 4. Boundary Clamping (Crucial Step)
  // Ensure scale is never below 1.0 relative to cover dimensions
  scale = Math.max(1.0, scale);

  // Calculate actual current dimensions
  const currentW = drawWidth * scale;
  const currentH = drawHeight * scale;

  // Calculate maximum allowed offset from center
  // If currentW == canvasWidth, maxOffsetX is 0 (no panning allowed)
  const maxOffsetX = (currentW - canvasWidth) / 2;
  const maxOffsetY = (currentH - canvasHeight) / 2;

  // Clamp the requested offset to the available overflow
  // This forces the image to stay within bounds
  xOffset = Math.max(-maxOffsetX, Math.min(maxOffsetX, xOffset));
  yOffset = Math.max(-maxOffsetY, Math.min(maxOffsetY, yOffset));

  // 5. Draw
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  ctx.save();
  ctx.translate(canvasWidth / 2 + xOffset, canvasHeight / 2 + yOffset);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(scale, scale);

  ctx.drawImage(image, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
  ctx.restore();
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { AspectRatio, MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);
  const [focusPoint, setFocusPoint] = useState<{ x: number, y: number } | null>(null);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5, // Default duration in seconds
    aspectRatio: AspectRatio.PORTRAIT,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Handle preset change to reset focus point if needed
  useEffect(() => {
    if (config.presetId !== 'custom-focus') {
      setFocusPoint(null);
    }
  }, [config.presetId]);

  // Calculate dynamic preset based on config and focus point
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (config.presetId === 'custom-focus' && focusPoint) {
      // Return a new object with overridden params
      return {
        ...basePreset,
        params: {
          ...basePreset.params,
          xEnd: -focusPoint.x, // Invert because moving camera right means shifting image left
          yEnd: -focusPoint.y
        }
      };
    }
    return basePreset;
  }, [config.presetId, focusPoint]);

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds
    const duration = config.duration;

    // Loop
    const t = (elapsed % duration) / duration;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on aspect ratio
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            // Calculate target dimensions
            let width = containerWidth;
            let height = containerHeight;

            if (config.aspectRatio === AspectRatio.PORTRAIT) {
                 // 9:16
                 const targetRatio = 9/16;
                 if (width / height > targetRatio) {
                     width = height * targetRatio;
                 } else {
                     height = width / targetRatio;
                 }
            } else if (config.aspectRatio === AspectRatio.LANDSCAPE) {
                 // 16:9
                 const targetRatio = 16/9;
                 if (width / height > targetRatio) {
                    height = width / targetRatio; // constrain by width
                 } else {
                    width = height * targetRatio;
                 }
            } else {
                // Square
                const size = Math.min(width, height);
                width = size;
                height = size;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            renderFrame(ctx, imageElement, t, preset, width, height);

            // Draw Focus Point Indicator
            if (config.presetId === 'custom-focus' && focusPoint) {
               const centerX = width / 2;
               const centerY = height / 2;
               // The visual marker should be at the clicked position relative to canvas
               // focusPoint x is relative to center / width.
               // x = (clickX - center) / width  => clickX = x * width + center
               const markerX = focusPoint.x * width + centerX;
               const markerY = focusPoint.y * height + centerY;

               ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
               ctx.lineWidth = 2;
               ctx.beginPath();
               ctx.arc(markerX, markerY, 10, 0, Math.PI * 2);
               ctx.moveTo(markerX - 15, markerY);
               ctx.lineTo(markerX + 15, markerY);
               ctx.moveTo(markerX, markerY - 15);
               ctx.lineTo(markerX, markerY + 15);
               ctx.stroke();
            }
        }
    }

    if (isPlaying) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, focusPoint]);

  useEffect(() => {
    if (isPlaying && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setFocusPoint(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (config.presetId !== 'custom-focus' || !canvasRef.current) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // Calculate normalized deviation from center (-0.5 to 0.5 roughly)
    // Actually our render logic expects fraction of WIDTH/HEIGHT.
    // xOffset = param * width.
    // We want the point at x to move to center.
    // Deviation = x - center.
    // normalized = Deviation / width.
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    setFocusPoint({ x: normalizedX, y: normalizedY });

    // Temporarily pause to let user see selection? No, continuous play is fine.
    // Reset animation to start to visualize zoom better?
    startTimeRef.current = performance.now(); 
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording (guarantees one full loop)
    const fps = 60;
    const totalFrames = config.duration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // We use the actual canvas size (already set)
    // We need to "normalize" the coordinate system for the render function which expects the CSS size
    // But since we scaled the context with DPR, we pass the CSS size to renderFrame
    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= totalFrames; i++) {
            const t = i / totalFrames;
            renderFrame(ctx, imageElement, t, preset, width, height);
            // Wait for frame interval to keep recording realistic (though captureStream handles stream)
            // Actually for captureStream we just need to draw.
            // But we need to give the MediaRecorder time to capture frames.
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">High-res recommended</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a] bg-black">
                    <img src={selectedImage} alt="Input" className="w-full h-48 object-contain" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] text-gray-300">
                        {imageElement ? `${imageElement.naturalWidth} x ${imageElement.naturalHeight}` : 'Loading...'}
                    </div>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             {/* Presets List moved to left sidebar for better flow */}
             {selectedImage && (
                <div className="mt-8">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Motion Style</h3>
                    <div className="grid grid-cols-1 gap-2">
                    {MOTION_PRESETS.map((preset) => (
                        <MotionCard 
                        key={preset.id}
                        preset={preset}
                        isSelected={config.presetId === preset.id}
                        onClick={() => setConfig(prev => ({ ...prev, presetId: preset.id }))}
                        />
                    ))}
                    </div>
                </div>
             )}
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Canvas Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        {/* Toolbar */}
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-[#18181b]/80 backdrop-blur-md border border-[#27272a] p-1.5 rounded-full shadow-2xl">
            <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 transition-colors"
                disabled={!selectedImage || isRecording}
            >
                {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
            </button>
            <div className="w-px h-6 bg-white/10 mx-1"></div>
            <div className="px-3 flex flex-col">
                <span className="text-[10px] text-gray-400 font-medium">PREVIEW</span>
                <span className="text-xs text-white font-mono">
                    {config.duration.toFixed(1)}s
                </span>
            </div>
        </div>

        {/* Instruction Toast for Custom Focus */}
        {selectedImage && config.presetId === 'custom-focus' && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur animate-in fade-in slide-in-from-bottom-4">
                 <MousePointerClick size={16} />
                 <span className="text-xs font-medium">Click anywhere on the image to focus</span>
             </div>
        )}

        <div className="flex-1 flex items-center justify-center p-8 overflow-hidden relative">

          {selectedImage ? (
             <div className="relative shadow-2xl shadow-black/50 border border-[#27272a] rounded-sm overflow-hidden bg-black group">
                <canvas 
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    className={`block ${config.presetId === 'custom-focus' ? 'cursor-crosshair' : 'cursor-default'}`}
                />
                {isRecording && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center flex-col gap-3 z-30">
                        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-white font-medium tracking-wide">Rendering Video...</span>
                    </div>
                )}
             </div>
          ) : (
            <div className="text-center opacity-60">
              <div className="w-24 h-24 bg-[#18181b] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#27272a] shadow-inner">
                <ImageIcon className="text-gray-600 w-10 h-10" />
              </div>
              <h2 className="text-2xl font-light text-gray-300 mb-2">Motion Studio</h2>
              <p className="text-gray-500 max-w-sm mx-auto">Upload an image to start designing cinematic motion effects.</p>
            </div>
          )}
        </div>
      </main>

      {/* 3. Right Sidebar: Fine Tuning */}
      <aside className="w-80 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a]">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            Configuration
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {/* Duration Control */}
          <section>
             <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-medium text-gray-400">Duration</h3>
                <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                    {config.duration}s
                </span>
             </div>
             <input 
                type="range" 
                min="2" 
                max="10" 
                step="0.5" 
                value={config.duration}
                onChange={(e) => setConfig(prev => ({ ...prev, duration: parseFloat(e.target.value) }))}
                className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
             />
             <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                <span>Fast (2s)</span>
                <span>Slow (10s)</span>
             </div>
          </section>

          {/* Aspect Ratio */}
          <section>
            <h3 className="text-sm font-medium text-gray-400 mb-3">Dimensions</h3>
            <div className="grid grid-cols-2 gap-3">
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.PORTRAIT }))}
                 className={`flex flex-col items-center justify-center gap-2 py-4 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.PORTRAIT ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-4 h-7 border-2 border-current rounded-[2px] opacity-80"></div>
                 9:16 Story
               </button>
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.LANDSCAPE }))}
                 className={`flex flex-col items-center justify-center gap-2 py-4 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.LANDSCAPE ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-7 h-4 border-2 border-current rounded-[2px] opacity-80"></div>
                 16:9 Video
               </button>
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.SQUARE }))}
                 className={`col-span-2 flex flex-row items-center justify-center gap-3 py-3 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.SQUARE ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-4 h-4 border-2 border-current rounded-[2px] opacity-80"></div>
                 1:1 Post
               </button>
            </div>
          </section>

          <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
             <div className="flex items-start gap-3">
                <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                <p className="text-[11px] text-gray-400 leading-relaxed">
                    This tool renders motion client-side. The export quality depends on your screen resolution. For best results, keep the window active during export.
                </p>
             </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-white text-black hover:bg-gray-200 border-0 shadow-lg shadow-white/5"
              onClick={handleExport}
              isLoading={isRecording}
              disabled={!selectedImage}
              icon={<Download size={18} />}
            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

export enum AspectRatio {
  PORTRAIT = '9:16',
  LANDSCAPE = '16:9',
  SQUARE = '1:1',
}

export interface MotionPreset {
  id: string;
  name: string;
  description: string;
  icon: string;
  type: 'zoom' | 'pan' | 'rotate' | 'shake' | 'pulse' | 'swing' | 'float' | 'path';
  params: {
    scaleStart: number;
    scaleEnd: number;
    xStart: number; // Percentage of width (-1 to 1)
    xEnd: number;
    yStart: number; // Percentage of height
    yEnd: number;
    rotationStart: number; // Degrees
    rotationEnd: number;
    frequency?: number; // Oscillations per duration (for pulse/swing/float)
    path?: { x: number, y: number }[]; // Array of normalized coordinates for path movement
  }
}

export interface MotionConfig {
  presetId: string;
  duration: number; // Seconds
  aspectRatio: AspectRatio;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2 } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { AspectRatio, MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);
  const [focusPoint, setFocusPoint] = useState<{ x: number, y: number } | null>(null);
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5, // Default duration in seconds
    aspectRatio: AspectRatio.PORTRAIT,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Handle preset change to reset focus/path points if needed
  useEffect(() => {
    if (config.presetId !== 'custom-focus') {
      setFocusPoint(null);
    }
    if (config.presetId !== 'custom-path') {
        // We don't necessarily want to clear path points immediately when switching away
        // But maybe we should for clean state? Let's keep them in case user switches back.
        // Actually for simplicity, let's clear them if the image changes, but not preset.
    }
  }, [config.presetId]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (config.presetId === 'custom-focus' && focusPoint) {
      return {
        ...basePreset,
        params: {
          ...basePreset.params,
          xEnd: -focusPoint.x, 
          yEnd: -focusPoint.y
        }
      };
    }

    if (config.presetId === 'custom-path' && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass path points inverted because moving camera to X means shifting image by -X
                path: pathPoints.map(p => ({ x: -p.x, y: -p.y }))
            }
        };
    }

    return basePreset;
  }, [config.presetId, focusPoint, pathPoints]);

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds
    const duration = config.duration;

    // Loop
    const t = (elapsed % duration) / duration;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on aspect ratio
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            // Calculate target dimensions
            let width = containerWidth;
            let height = containerHeight;

            if (config.aspectRatio === AspectRatio.PORTRAIT) {
                 // 9:16
                 const targetRatio = 9/16;
                 if (width / height > targetRatio) {
                     width = height * targetRatio;
                 } else {
                     height = width / targetRatio;
                 }
            } else if (config.aspectRatio === AspectRatio.LANDSCAPE) {
                 // 16:9
                 const targetRatio = 16/9;
                 if (width / height > targetRatio) {
                    height = width / targetRatio; // constrain by width
                 } else {
                    width = height * targetRatio;
                 }
            } else {
                // Square
                const size = Math.min(width, height);
                width = size;
                height = size;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            renderFrame(ctx, imageElement, t, preset, width, height);

            // Draw Focus Point Indicator
            if (config.presetId === 'custom-focus' && focusPoint) {
               const centerX = width / 2;
               const centerY = height / 2;
               const markerX = focusPoint.x * width + centerX;
               const markerY = focusPoint.y * height + centerY;

               ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
               ctx.lineWidth = 2;
               ctx.shadowColor = 'black';
               ctx.shadowBlur = 4;
               ctx.beginPath();
               ctx.arc(markerX, markerY, 8, 0, Math.PI * 2);
               ctx.moveTo(markerX - 12, markerY);
               ctx.lineTo(markerX + 12, markerY);
               ctx.moveTo(markerX, markerY - 12);
               ctx.lineTo(markerX, markerY + 12);
               ctx.stroke();
               ctx.shadowBlur = 0;
            }

            // Draw Path Indicators
            if (config.presetId === 'custom-path' && pathPoints.length > 0) {
                const centerX = width / 2;
                const centerY = height / 2;

                // Draw connecting lines
                if (pathPoints.length > 1) {
                    ctx.beginPath();
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
                    ctx.lineWidth = 2;
                    ctx.setLineDash([5, 5]);
                    pathPoints.forEach((p, index) => {
                        const px = p.x * width + centerX;
                        const py = p.y * height + centerY;
                        if (index === 0) ctx.moveTo(px, py);
                        else ctx.lineTo(px, py);
                    });
                    ctx.stroke();
                    ctx.setLineDash([]);
                }

                // Draw points
                pathPoints.forEach((p, index) => {
                    const px = p.x * width + centerX;
                    const py = p.y * height + centerY;

                    ctx.fillStyle = 'rgba(99, 102, 241, 0.9)'; // Indigo
                    ctx.strokeStyle = 'white';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.arc(px, py, 6, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();

                    // Draw number
                    ctx.fillStyle = 'white';
                    ctx.font = 'bold 10px Inter, sans-serif';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    // Offset number slightly
                    ctx.fillText(`${index + 1}`, px + 12, py - 12);
                });
            }
        }
    }

    if (isPlaying) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, focusPoint, pathPoints]);

  useEffect(() => {
    if (isPlaying && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
        setFocusPoint(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setFocusPoint(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // Normalize coordinates (-0.5 to 0.5)
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    if (config.presetId === 'custom-focus') {
        setFocusPoint({ x: normalizedX, y: normalizedY });
        startTimeRef.current = performance.now(); 
    } else if (config.presetId === 'custom-path') {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
        // Don't reset time for path, usually better to keep adding
    }
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const totalFrames = config.duration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= totalFrames; i++) {
            const t = i / totalFrames;
            renderFrame(ctx, imageElement, t, preset, width, height);
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">High-res recommended</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a] bg-black">
                    <img src={selectedImage} alt="Input" className="w-full h-48 object-contain" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] text-gray-300">
                        {imageElement ? `${imageElement.naturalWidth} x ${imageElement.naturalHeight}` : 'Loading...'}
                    </div>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             {selectedImage && (
                <div className="mt-8">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Motion Style</h3>
                    <div className="grid grid-cols-1 gap-2">
                    {MOTION_PRESETS.map((preset) => (
                        <MotionCard 
                        key={preset.id}
                        preset={preset}
                        isSelected={config.presetId === preset.id}
                        onClick={() => setConfig(prev => ({ ...prev, presetId: preset.id }))}
                        />
                    ))}
                    </div>
                </div>
             )}
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Canvas Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        {/* Toolbar */}
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-[#18181b]/80 backdrop-blur-md border border-[#27272a] p-1.5 rounded-full shadow-2xl">
            <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 transition-colors"
                disabled={!selectedImage || isRecording}
            >
                {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
            </button>
            <div className="w-px h-6 bg-white/10 mx-1"></div>
            <div className="px-3 flex flex-col">
                <span className="text-[10px] text-gray-400 font-medium">PREVIEW</span>
                <span className="text-xs text-white font-mono">
                    {config.duration.toFixed(1)}s
                </span>
            </div>
        </div>

        {/* Instructions / Toasts */}
        {selectedImage && config.presetId === 'custom-focus' && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur animate-in fade-in slide-in-from-bottom-4">
                 <MousePointerClick size={16} />
                 <span className="text-xs font-medium">Click anywhere to set focus</span>
             </div>
        )}

        {selectedImage && config.presetId === 'custom-path' && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-3 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur animate-in fade-in slide-in-from-bottom-4">
                 <Route size={16} />
                 <span className="text-xs font-medium">
                     {pathPoints.length === 0 ? "Click points to build a path" : `${pathPoints.length} points added`}
                 </span>
                 {pathPoints.length > 0 && (
                     <button 
                       onClick={clearPath}
                       className="ml-2 p-1 hover:bg-white/20 rounded-full transition-colors"
                       title="Clear path"
                     >
                        <Trash2 size={12} />
                     </button>
                 )}
             </div>
        )}

        <div className="flex-1 flex items-center justify-center p-8 overflow-hidden relative">

          {selectedImage ? (
             <div className="relative shadow-2xl shadow-black/50 border border-[#27272a] rounded-sm overflow-hidden bg-black group">
                <canvas 
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    className={`block ${['custom-focus', 'custom-path'].includes(config.presetId) ? 'cursor-crosshair' : 'cursor-default'}`}
                />
                {isRecording && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center flex-col gap-3 z-30">
                        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-white font-medium tracking-wide">Rendering Video...</span>
                    </div>
                )}
             </div>
          ) : (
            <div className="text-center opacity-60">
              <div className="w-24 h-24 bg-[#18181b] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#27272a] shadow-inner">
                <ImageIcon className="text-gray-600 w-10 h-10" />
              </div>
              <h2 className="text-2xl font-light text-gray-300 mb-2">Motion Studio</h2>
              <p className="text-gray-500 max-w-sm mx-auto">Upload an image to start designing cinematic motion effects.</p>
            </div>
          )}
        </div>
      </main>

      {/* 3. Right Sidebar: Fine Tuning */}
      <aside className="w-80 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a]">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            Configuration
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {/* Duration Control */}
          <section>
             <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-medium text-gray-400">Duration</h3>
                <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                    {config.duration}s
                </span>
             </div>
             <input 
                type="range" 
                min="2" 
                max="10" 
                step="0.5" 
                value={config.duration}
                onChange={(e) => setConfig(prev => ({ ...prev, duration: parseFloat(e.target.value) }))}
                className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
             />
             <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                <span>Fast (2s)</span>
                <span>Slow (10s)</span>
             </div>
          </section>

          {/* Aspect Ratio */}
          <section>
            <h3 className="text-sm font-medium text-gray-400 mb-3">Dimensions</h3>
            <div className="grid grid-cols-2 gap-3">
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.PORTRAIT }))}
                 className={`flex flex-col items-center justify-center gap-2 py-4 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.PORTRAIT ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-4 h-7 border-2 border-current rounded-[2px] opacity-80"></div>
                 9:16 Story
               </button>
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.LANDSCAPE }))}
                 className={`flex flex-col items-center justify-center gap-2 py-4 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.LANDSCAPE ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-7 h-4 border-2 border-current rounded-[2px] opacity-80"></div>
                 16:9 Video
               </button>
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.SQUARE }))}
                 className={`col-span-2 flex flex-row items-center justify-center gap-3 py-3 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.SQUARE ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-4 h-4 border-2 border-current rounded-[2px] opacity-80"></div>
                 1:1 Post
               </button>
            </div>
          </section>

          <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
             <div className="flex items-start gap-3">
                <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                <p className="text-[11px] text-gray-400 leading-relaxed">
                    This tool renders motion client-side. The export quality depends on your screen resolution. For best results, keep the window active during export.
                </p>
             </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-white text-black hover:bg-gray-200 border-0 shadow-lg shadow-white/5"
              onClick={handleExport}
              isLoading={isRecording}
              disabled={!selectedImage}
              icon={<Download size={18} />}
            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

import { MotionPreset } from '../types';

// Easing function: Ease In Out Quad
const easeInOutQuad = (t: number): number => {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
};

// Simple noise function for shake
const noise = (t: number) => {
    return Math.sin(t * 10) * 0.5 + Math.sin(t * 23) * 0.25 + Math.sin(t * 47) * 0.125;
}

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  progress: number, // 0 to 1
  preset: MotionPreset,
  canvasWidth: number,
  canvasHeight: number
) => {
  const { params } = preset;

  // Ease the progress
  const t = easeInOutQuad(progress);

  // 1. Calculate Base Aspect Fill (Cover) Dimensions
  // This determines the size of the image such that it exactly covers the canvas at scale 1.0
  const imgRatio = image.width / image.height;
  const canvasRatio = canvasWidth / canvasHeight;

  let drawWidth, drawHeight;

  if (imgRatio > canvasRatio) {
    // Image is wider than canvas: Fit Height, Crop Width
    drawHeight = canvasHeight;
    drawWidth = canvasHeight * imgRatio;
  } else {
    // Image is taller than canvas: Fit Width, Crop Height
    drawWidth = canvasWidth;
    drawHeight = canvasWidth / imgRatio;
  }

  // 2. Interpolate Motion Parameters
  let scale = 1;
  let xOffset = 0;
  let yOffset = 0;
  let rotation = 0;

  if (preset.type === 'pulse') {
     const freq = params.frequency || 1;
     const sineWave = (Math.sin(progress * Math.PI * 2 * freq) + 1) / 2;

     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * sineWave;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     rotation = params.rotationStart;

  } else if (preset.type === 'swing') {
     const freq = params.frequency || 1;
     const sineWave = Math.sin(progress * Math.PI * 2 * freq);

     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * 0.5 * sineWave;
     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;

  } else if (preset.type === 'float') {
     const freq = params.frequency || 0.5;
     const sineX = Math.sin(progress * Math.PI * 2 * freq);
     const cosY = Math.cos(progress * Math.PI * 2 * freq * 0.7);

     const floatAmp = 0.03 * canvasWidth;

     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;

     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth + sineX * floatAmp;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight + cosY * floatAmp;

  } else if (preset.type === 'path' && params.path && params.path.length > 0) {
      // Custom Path Interpolation
      const points = params.path;

      scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
      rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;

      if (points.length === 1) {
          // If only one point, just go there
          xOffset = points[0].x * canvasWidth;
          yOffset = points[0].y * canvasHeight;
      } else {
          // Multiple points interpolation
          const totalSegments = points.length - 1;
          // We use the eased 't' to determine progress along the entire path
          const segmentIndex = Math.min(Math.floor(t * totalSegments), totalSegments - 1);
          const segmentProgress = (t - (segmentIndex / totalSegments)) * totalSegments;

          const p1 = points[segmentIndex];
          const p2 = points[segmentIndex + 1];

          const currentX = p1.x + (p2.x - p1.x) * segmentProgress;
          const currentY = p1.y + (p2.y - p1.y) * segmentProgress;

          xOffset = currentX * canvasWidth;
          yOffset = currentY * canvasHeight;
      }
  } else {
     // Standard Linear Interpolation
     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;
  }

  // Add Shake noise (additive)
  if (preset.type === 'shake') {
      const shakeIntensity = 0.02 * canvasWidth;
      xOffset += noise(progress * 20) * shakeIntensity;
      yOffset += noise(progress * 15 + 100) * shakeIntensity;
      rotation += noise(progress * 10 + 200) * 0.5;
  }

  // 3. Rotation Safety Logic
  // If rotated, we need extra scale to ensure corners don't expose background.
  if (Math.abs(rotation) > 0.1) {
      const rotationRad = Math.abs(rotation * Math.PI / 180);
      // Heuristic boost: roughly 1.0 at 0deg, increasing with angle
      const rotationScaleBoost = 1 + (rotationRad * 0.6); 
      scale = scale * rotationScaleBoost;
  }

  // 4. Boundary Clamping (Crucial Step)
  // Ensure scale is never below 1.0 relative to cover dimensions
  scale = Math.max(1.0, scale);

  // Calculate actual current dimensions
  const currentW = drawWidth * scale;
  const currentH = drawHeight * scale;

  // Calculate maximum allowed offset from center
  // If currentW == canvasWidth, maxOffsetX is 0 (no panning allowed)
  const maxOffsetX = (currentW - canvasWidth) / 2;
  const maxOffsetY = (currentH - canvasHeight) / 2;

  // Clamp the requested offset to the available overflow
  // This forces the image to stay within bounds
  xOffset = Math.max(-maxOffsetX, Math.min(maxOffsetX, xOffset));
  yOffset = Math.max(-maxOffsetY, Math.min(maxOffsetY, yOffset));

  // 5. Draw
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  ctx.save();
  ctx.translate(canvasWidth / 2 + xOffset, canvasHeight / 2 + yOffset);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(scale, scale);

  ctx.drawImage(image, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
  ctx.restore();
};

import { MotionPreset } from '../types';

// Easing function: Ease In Out Quad
const easeInOutQuad = (t: number): number => {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
};

// Simple noise function for shake
const noise = (t: number) => {
    return Math.sin(t * 10) * 0.5 + Math.sin(t * 23) * 0.25 + Math.sin(t * 47) * 0.125;
}

// Catmull-Rom Spline Math
const solveCatmullRom = (p0: number, p1: number, p2: number, p3: number, t: number) => {
    const v0 = (p2 - p0) * 0.5;
    const v1 = (p3 - p1) * 0.5;
    const t2 = t * t;
    const t3 = t * t2;
    return (2 * p1 - 2 * p2 + v0 + v1) * t3 + (-3 * p1 + 3 * p2 - 2 * v0 - v1) * t2 + v0 * t + p1;
};

const getDistance = (p1: {x: number, y: number}, p2: {x: number, y: number}) => {
    return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
}

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  progress: number, // 0 to 1
  preset: MotionPreset,
  canvasWidth: number,
  canvasHeight: number
) => {
  const { params } = preset;

  // Ease the progress
  const t = easeInOutQuad(progress);

  // 1. Calculate Base Aspect Fill (Cover) Dimensions
  const imgRatio = image.width / image.height;
  const canvasRatio = canvasWidth / canvasHeight;

  let drawWidth, drawHeight;

  if (imgRatio > canvasRatio) {
    // Image is wider than canvas: Fit Height, Crop Width
    drawHeight = canvasHeight;
    drawWidth = canvasHeight * imgRatio;
  } else {
    // Image is taller than canvas: Fit Width, Crop Height
    drawWidth = canvasWidth;
    drawHeight = canvasWidth / imgRatio;
  }

  // 2. Interpolate Motion Parameters
  let scale = 1;
  let xOffset = 0;
  let yOffset = 0;
  let rotation = 0;

  if (preset.type === 'pulse') {
     const freq = params.frequency || 1;
     const sineWave = (Math.sin(progress * Math.PI * 2 * freq) + 1) / 2;

     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * sineWave;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     rotation = params.rotationStart;

  } else if (preset.type === 'swing') {
     const freq = params.frequency || 1;
     const sineWave = Math.sin(progress * Math.PI * 2 * freq);

     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * 0.5 * sineWave;
     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;

  } else if (preset.type === 'float') {
     const freq = params.frequency || 0.5;
     const sineX = Math.sin(progress * Math.PI * 2 * freq);
     const cosY = Math.cos(progress * Math.PI * 2 * freq * 0.7);

     const floatAmp = 0.03 * canvasWidth;

     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;

     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth + sineX * floatAmp;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight + cosY * floatAmp;

  } else if (preset.type === 'path' && params.path && params.path.length > 0) {
      // Custom Smooth Path Interpolation
      const points = params.path;

      // Standard linear interpolation for scale and rotation
      scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
      rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;

      if (points.length === 1) {
          xOffset = points[0].x * canvasWidth;
          yOffset = points[0].y * canvasHeight;
      } else {
          // Calculate total path length to normalize T for constant speed
          let totalLength = 0;
          const segmentLengths: number[] = [];

          for (let i = 0; i < points.length - 1; i++) {
              const len = getDistance(points[i], points[i+1]);
              segmentLengths.push(len);
              totalLength += len;
          }

          if (totalLength === 0) {
              // fallback if all points are same
              xOffset = points[0].x * canvasWidth;
              yOffset = points[0].y * canvasHeight;
          } else {
              // Find current segment based on distance covered
              const currentDist = t * totalLength;
              let accumDist = 0;
              let segIndex = 0;
              let segT = 0; // Local T for the segment

              for (let i = 0; i < segmentLengths.length; i++) {
                  if (currentDist <= accumDist + segmentLengths[i]) {
                      segIndex = i;
                      // Local T = (dist covered in this segment) / (length of this segment)
                      segT = (currentDist - accumDist) / segmentLengths[i];
                      break;
                  }
                  accumDist += segmentLengths[i];
              }
              // Edge case: if t=1, we might be slightly past the loop
              if (t >= 0.999) {
                  segIndex = points.length - 2;
                  segT = 1;
              }

              // Catmull-Rom requires 4 points: p0 (prev), p1 (start), p2 (end), p3 (next)
              // Handle boundaries by duplicating start/end points
              const p1 = points[segIndex];
              const p2 = points[segIndex + 1];
              const p0 = points[Math.max(0, segIndex - 1)];
              const p3 = points[Math.min(points.length - 1, segIndex + 2)];

              const curX = solveCatmullRom(p0.x, p1.x, p2.x, p3.x, segT);
              const curY = solveCatmullRom(p0.y, p1.y, p2.y, p3.y, segT);

              xOffset = curX * canvasWidth;
              yOffset = curY * canvasHeight;
          }
      }
  } else {
     // Standard Linear Interpolation
     scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
     xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
     yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;
  }

  // Add Shake noise (additive)
  if (preset.type === 'shake') {
      const shakeIntensity = 0.02 * canvasWidth;
      xOffset += noise(progress * 20) * shakeIntensity;
      yOffset += noise(progress * 15 + 100) * shakeIntensity;
      rotation += noise(progress * 10 + 200) * 0.5;
  }

  // 3. Rotation Safety Logic
  // If rotated, we need extra scale to ensure corners don't expose background.
  if (Math.abs(rotation) > 0.1) {
      const rotationRad = Math.abs(rotation * Math.PI / 180);
      // Heuristic boost: roughly 1.0 at 0deg, increasing with angle
      const rotationScaleBoost = 1 + (rotationRad * 0.6); 
      scale = scale * rotationScaleBoost;
  }

  // 4. Boundary Clamping (Crucial Step)
  // Ensure scale is never below 1.0 relative to cover dimensions
  scale = Math.max(1.0, scale);

  // Calculate actual current dimensions
  const currentW = drawWidth * scale;
  const currentH = drawHeight * scale;

  // Calculate maximum allowed offset from center
  // If currentW == canvasWidth, maxOffsetX is 0 (no panning allowed)
  const maxOffsetX = (currentW - canvasWidth) / 2;
  const maxOffsetY = (currentH - canvasHeight) / 2;

  // Clamp the requested offset to the available overflow
  // This forces the image to stay within bounds
  xOffset = Math.max(-maxOffsetX, Math.min(maxOffsetX, xOffset));
  yOffset = Math.max(-maxOffsetY, Math.min(maxOffsetY, yOffset));

  // 5. Draw
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  ctx.save();
  ctx.translate(canvasWidth / 2 + xOffset, canvasHeight / 2 + yOffset);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(scale, scale);

  ctx.drawImage(image, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
  ctx.restore();
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2 } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { AspectRatio, MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);
  const [focusPoint, setFocusPoint] = useState<{ x: number, y: number } | null>(null);
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5, // Default duration in seconds
    aspectRatio: AspectRatio.PORTRAIT,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Handle preset change to reset focus/path points if needed
  useEffect(() => {
    if (config.presetId !== 'custom-focus') {
      setFocusPoint(null);
    }
  }, [config.presetId]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (config.presetId === 'custom-focus' && focusPoint) {
      return {
        ...basePreset,
        params: {
          ...basePreset.params,
          xEnd: -focusPoint.x, 
          yEnd: -focusPoint.y
        }
      };
    }

    if (config.presetId === 'custom-path' && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass path points inverted because moving camera to X means shifting image by -X
                path: pathPoints.map(p => ({ x: -p.x, y: -p.y }))
            }
        };
    }

    return basePreset;
  }, [config.presetId, focusPoint, pathPoints]);

  // Spline helper for visualization (simplified version of motionService)
  const getSplinePoint = (p0: any, p1: any, p2: any, p3: any, t: number) => {
      const v0x = (p2.x - p0.x) * 0.5;
      const v0y = (p2.y - p0.y) * 0.5;
      const v1x = (p3.x - p1.x) * 0.5;
      const v1y = (p3.y - p1.y) * 0.5;
      const t2 = t * t;
      const t3 = t * t2;
      return {
          x: (2 * p1.x - 2 * p2.x + v0x + v1x) * t3 + (-3 * p1.x + 3 * p2.x - 2 * v0x - v1x) * t2 + v0x * t + p1.x,
          y: (2 * p1.y - 2 * p2.y + v0y + v1y) * t3 + (-3 * p1.y + 3 * p2.y - 2 * v0y - v1y) * t2 + v0y * t + p1.y
      };
  };

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds
    const duration = config.duration;

    // Loop
    const t = (elapsed % duration) / duration;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on aspect ratio
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            // Calculate target dimensions
            let width = containerWidth;
            let height = containerHeight;

            if (config.aspectRatio === AspectRatio.PORTRAIT) {
                 // 9:16
                 const targetRatio = 9/16;
                 if (width / height > targetRatio) {
                     width = height * targetRatio;
                 } else {
                     height = width / targetRatio;
                 }
            } else if (config.aspectRatio === AspectRatio.LANDSCAPE) {
                 // 16:9
                 const targetRatio = 16/9;
                 if (width / height > targetRatio) {
                    height = width / targetRatio; // constrain by width
                 } else {
                    width = height * targetRatio;
                 }
            } else {
                // Square
                const size = Math.min(width, height);
                width = size;
                height = size;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            renderFrame(ctx, imageElement, t, preset, width, height);

            // Draw Focus Point Indicator
            if (config.presetId === 'custom-focus' && focusPoint) {
               const centerX = width / 2;
               const centerY = height / 2;
               const markerX = focusPoint.x * width + centerX;
               const markerY = focusPoint.y * height + centerY;

               ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
               ctx.lineWidth = 2;
               ctx.shadowColor = 'black';
               ctx.shadowBlur = 4;
               ctx.beginPath();
               ctx.arc(markerX, markerY, 8, 0, Math.PI * 2);
               ctx.moveTo(markerX - 12, markerY);
               ctx.lineTo(markerX + 12, markerY);
               ctx.moveTo(markerX, markerY - 12);
               ctx.lineTo(markerX, markerY + 12);
               ctx.stroke();
               ctx.shadowBlur = 0;
            }

            // Draw Smooth Path Visualization
            if (config.presetId === 'custom-path' && pathPoints.length > 0) {
                const centerX = width / 2;
                const centerY = height / 2;

                // Draw connecting curve
                if (pathPoints.length > 1) {
                    ctx.beginPath();
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
                    ctx.lineWidth = 2;
                    ctx.setLineDash([5, 5]);

                    // Draw Catmull-Rom Spline
                    ctx.moveTo(pathPoints[0].x * width + centerX, pathPoints[0].y * height + centerY);

                    // We draw segments between point i and i+1
                    for (let i = 0; i < pathPoints.length - 1; i++) {
                        const p0 = pathPoints[Math.max(0, i - 1)];
                        const p1 = pathPoints[i];
                        const p2 = pathPoints[i + 1];
                        const p3 = pathPoints[Math.min(pathPoints.length - 1, i + 2)];

                        // Sample the curve
                        const steps = 20;
                        for (let s = 1; s <= steps; s++) {
                            const tVal = s / steps;
                            const pos = getSplinePoint(p0, p1, p2, p3, tVal);
                            ctx.lineTo(pos.x * width + centerX, pos.y * height + centerY);
                        }
                    }

                    ctx.stroke();
                    ctx.setLineDash([]);
                }

                // Draw points
                pathPoints.forEach((p, index) => {
                    const px = p.x * width + centerX;
                    const py = p.y * height + centerY;

                    ctx.fillStyle = 'rgba(99, 102, 241, 0.9)'; // Indigo
                    ctx.strokeStyle = 'white';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.arc(px, py, 6, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();

                    // Draw number
                    ctx.fillStyle = 'white';
                    ctx.font = 'bold 10px Inter, sans-serif';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    // Offset number slightly
                    ctx.fillText(`${index + 1}`, px + 12, py - 12);
                });
            }
        }
    }

    if (isPlaying) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, focusPoint, pathPoints]);

  useEffect(() => {
    if (isPlaying && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
        setFocusPoint(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setFocusPoint(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // Normalize coordinates (-0.5 to 0.5)
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    if (config.presetId === 'custom-focus') {
        setFocusPoint({ x: normalizedX, y: normalizedY });
        startTimeRef.current = performance.now(); 
    } else if (config.presetId === 'custom-path') {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
        // Don't reset time for path, usually better to keep adding
    }
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const totalFrames = config.duration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= totalFrames; i++) {
            const t = i / totalFrames;
            renderFrame(ctx, imageElement, t, preset, width, height);
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">High-res recommended</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a] bg-black">
                    <img src={selectedImage} alt="Input" className="w-full h-48 object-contain" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] text-gray-300">
                        {imageElement ? `${imageElement.naturalWidth} x ${imageElement.naturalHeight}` : 'Loading...'}
                    </div>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             {selectedImage && (
                <div className="mt-8">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Motion Style</h3>
                    <div className="grid grid-cols-1 gap-2">
                    {MOTION_PRESETS.map((preset) => (
                        <MotionCard 
                        key={preset.id}
                        preset={preset}
                        isSelected={config.presetId === preset.id}
                        onClick={() => setConfig(prev => ({ ...prev, presetId: preset.id }))}
                        />
                    ))}
                    </div>
                </div>
             )}
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Canvas Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        {/* Toolbar */}
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-[#18181b]/80 backdrop-blur-md border border-[#27272a] p-1.5 rounded-full shadow-2xl">
            <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 transition-colors"
                disabled={!selectedImage || isRecording}
            >
                {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
            </button>
            <div className="w-px h-6 bg-white/10 mx-1"></div>
            <div className="px-3 flex flex-col">
                <span className="text-[10px] text-gray-400 font-medium">PREVIEW</span>
                <span className="text-xs text-white font-mono">
                    {config.duration.toFixed(1)}s
                </span>
            </div>
        </div>

        {/* Instructions / Toasts */}
        {selectedImage && config.presetId === 'custom-focus' && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur animate-in fade-in slide-in-from-bottom-4">
                 <MousePointerClick size={16} />
                 <span className="text-xs font-medium">Click anywhere to set focus</span>
             </div>
        )}

        {selectedImage && config.presetId === 'custom-path' && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex items-center gap-3 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur animate-in fade-in slide-in-from-bottom-4">
                 <Route size={16} />
                 <span className="text-xs font-medium">
                     {pathPoints.length === 0 ? "Click points to build a path" : `${pathPoints.length} points added`}
                 </span>
                 {pathPoints.length > 0 && (
                     <button 
                       onClick={clearPath}
                       className="ml-2 p-1 hover:bg-white/20 rounded-full transition-colors"
                       title="Clear path"
                     >
                        <Trash2 size={12} />
                     </button>
                 )}
             </div>
        )}

        <div className="flex-1 flex items-center justify-center p-8 overflow-hidden relative">

          {selectedImage ? (
             <div className="relative shadow-2xl shadow-black/50 border border-[#27272a] rounded-sm overflow-hidden bg-black group">
                <canvas 
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    className={`block ${['custom-focus', 'custom-path'].includes(config.presetId) ? 'cursor-crosshair' : 'cursor-default'}`}
                />
                {isRecording && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center flex-col gap-3 z-30">
                        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-white font-medium tracking-wide">Rendering Video...</span>
                    </div>
                )}
             </div>
          ) : (
            <div className="text-center opacity-60">
              <div className="w-24 h-24 bg-[#18181b] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#27272a] shadow-inner">
                <ImageIcon className="text-gray-600 w-10 h-10" />
              </div>
              <h2 className="text-2xl font-light text-gray-300 mb-2">Motion Studio</h2>
              <p className="text-gray-500 max-w-sm mx-auto">Upload an image to start designing cinematic motion effects.</p>
            </div>
          )}
        </div>
      </main>

      {/* 3. Right Sidebar: Fine Tuning */}
      <aside className="w-80 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a]">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            Configuration
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {/* Duration Control */}
          <section>
             <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-medium text-gray-400">Duration</h3>
                <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                    {config.duration}s
                </span>
             </div>
             <input 
                type="range" 
                min="2" 
                max="10" 
                step="0.5" 
                value={config.duration}
                onChange={(e) => setConfig(prev => ({ ...prev, duration: parseFloat(e.target.value) }))}
                className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
             />
             <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                <span>Fast (2s)</span>
                <span>Slow (10s)</span>
             </div>
          </section>

          {/* Aspect Ratio */}
          <section>
            <h3 className="text-sm font-medium text-gray-400 mb-3">Dimensions</h3>
            <div className="grid grid-cols-2 gap-3">
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.PORTRAIT }))}
                 className={`flex flex-col items-center justify-center gap-2 py-4 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.PORTRAIT ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-4 h-7 border-2 border-current rounded-[2px] opacity-80"></div>
                 9:16 Story
               </button>
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.LANDSCAPE }))}
                 className={`flex flex-col items-center justify-center gap-2 py-4 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.LANDSCAPE ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-7 h-4 border-2 border-current rounded-[2px] opacity-80"></div>
                 16:9 Video
               </button>
               <button 
                 onClick={() => setConfig(prev => ({ ...prev, aspectRatio: AspectRatio.SQUARE }))}
                 className={`col-span-2 flex flex-row items-center justify-center gap-3 py-3 rounded-xl border text-xs font-medium transition-all ${config.aspectRatio === AspectRatio.SQUARE ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' : 'bg-[#18181b] border-[#27272a] text-gray-400 hover:border-gray-600'}`}
               >
                 <div className="w-4 h-4 border-2 border-current rounded-[2px] opacity-80"></div>
                 1:1 Post
               </button>
            </div>
          </section>

          <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
             <div className="flex items-start gap-3">
                <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                <p className="text-[11px] text-gray-400 leading-relaxed">
                    This tool renders motion client-side. The export quality depends on your screen resolution. For best results, keep the window active during export.
                </p>
             </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-white text-black hover:bg-gray-200 border-0 shadow-lg shadow-white/5"
              onClick={handleExport}
              isLoading={isRecording}
              disabled={!selectedImage}
              icon={<Download size={18} />}
            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

export enum AspectRatio {
  PORTRAIT = '9:16',
  LANDSCAPE = '16:9',
  SQUARE = '1:1',
}

export interface MotionPreset {
  id: string;
  name: string;
  description: string;
  icon: string;
  type: 'zoom' | 'pan' | 'rotate' | 'shake' | 'pulse' | 'swing' | 'float' | 'path';
  params: {
    scaleStart: number;
    scaleEnd: number;
    xStart: number; // Percentage of width (-1 to 1)
    xEnd: number;
    yStart: number; // Percentage of height
    yEnd: number;
    rotationStart: number; // Degrees
    rotationEnd: number;
    frequency?: number; // Oscillations per duration (for pulse/swing/float)
    path?: { x: number, y: number }[]; // Array of normalized coordinates for path movement
    pathLoop?: boolean; // Whether the path should form a closed loop
  }
}

export interface MotionConfig {
  presetId: string;
  duration: number; // Seconds
  aspectRatio: AspectRatio;
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2, Undo2, Repeat } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { AspectRatio, MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);
  const [focusPoint, setFocusPoint] = useState<{ x: number, y: number } | null>(null);
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);
  const [isPathLooping, setIsPathLooping] = useState<boolean>(false);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5, // Default duration in seconds
    aspectRatio: AspectRatio.PORTRAIT,
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Handle preset change to reset focus/path points if needed
  useEffect(() => {
    if (config.presetId !== 'custom-focus') {
      setFocusPoint(null);
    }
  }, [config.presetId]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (config.presetId === 'custom-focus' && focusPoint) {
      return {
        ...basePreset,
        params: {
          ...basePreset.params,
          xEnd: -focusPoint.x, 
          yEnd: -focusPoint.y
        }
      };
    }

    if (config.presetId === 'custom-path' && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass path points inverted because moving camera to X means shifting image by -X
                path: pathPoints.map(p => ({ x: -p.x, y: -p.y })),
                pathLoop: isPathLooping
            }
        };
    }

    return basePreset;
  }, [config.presetId, focusPoint, pathPoints, isPathLooping]);

  // Spline helper for visualization (simplified version of motionService)
  const getSplinePoint = (p0: any, p1: any, p2: any, p3: any, t: number) => {
      const v0x = (p2.x - p0.x) * 0.5;
      const v0y = (p2.y - p0.y) * 0.5;
      const v1x = (p3.x - p1.x) * 0.5;
      const v1y = (p3.y - p1.y) * 0.5;
      const t2 = t * t;
      const t3 = t * t2;
      return {
          x: (2 * p1.x - 2 * p2.x + v0x + v1x) * t3 + (-3 * p1.x + 3 * p2.x - 2 * v0x - v1x) * t2 + v0x * t + p1.x,
          y: (2 * p1.y - 2 * p2.y + v0y + v1y) * t3 + (-3 * p1.y + 3 * p2.y - 2 * v0y - v1y) * t2 + v0y * t + p1.y
      };
  };

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds
    const duration = config.duration;

    // Loop
    const t = (elapsed % duration) / duration;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on aspect ratio
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            // Calculate target dimensions
            let width = containerWidth;
            let height = containerHeight;

            if (config.aspectRatio === AspectRatio.PORTRAIT) {
                 // 9:16
                 const targetRatio = 9/16;
                 if (width / height > targetRatio) {
                     width = height * targetRatio;
                 } else {
                     height = width / targetRatio;
                 }
            } else if (config.aspectRatio === AspectRatio.LANDSCAPE) {
                 // 16:9
                 const targetRatio = 16/9;
                 if (width / height > targetRatio) {
                    height = width / targetRatio; // constrain by width
                 } else {
                    width = height * targetRatio;
                 }
            } else {
                // Square
                const size = Math.min(width, height);
                width = size;
                height = size;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            renderFrame(ctx, imageElement, t, preset, width, height);

            // Draw Focus Point Indicator
            if (config.presetId === 'custom-focus' && focusPoint) {
               const centerX = width / 2;
               const centerY = height / 2;
               const markerX = focusPoint.x * width + centerX;
               const markerY = focusPoint.y * height + centerY;

               ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
               ctx.lineWidth = 2;
               ctx.shadowColor = 'black';
               ctx.shadowBlur = 4;
               ctx.beginPath();
               ctx.arc(markerX, markerY, 8, 0, Math.PI * 2);
               ctx.moveTo(markerX - 12, markerY);
               ctx.lineTo(markerX + 12, markerY);
               ctx.moveTo(markerX, markerY - 12);
               ctx.lineTo(markerX, markerY + 12);
               ctx.stroke();
               ctx.shadowBlur = 0;
            }

            // Draw Smooth Path Visualization
            if (config.presetId === 'custom-path' && pathPoints.length > 0) {
                const centerX = width / 2;
                const centerY = height / 2;

                // Draw connecting curve
                if (pathPoints.length > 1) {
                    ctx.beginPath();
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
                    ctx.lineWidth = 2;
                    ctx.setLineDash([5, 5]);

                    const numSegments = isPathLooping ? pathPoints.length : pathPoints.length - 1;

                    // Draw Catmull-Rom Spline
                    ctx.moveTo(pathPoints[0].x * width + centerX, pathPoints[0].y * height + centerY);

                    for (let i = 0; i < numSegments; i++) {
                        // For looping, wrap indices
                        const p0 = pathPoints[(i - 1 + pathPoints.length) % pathPoints.length];
                        const p1 = pathPoints[i];
                        const p2 = pathPoints[(i + 1) % pathPoints.length];
                        const p3 = pathPoints[(i + 2) % pathPoints.length];

                        // Handle non-looping boundaries
                        if (!isPathLooping) {
                            if (i === 0) { /* p0 needs clamping if not looping, but index logic above handles i-1 via max/min manually if we didn't use modulo */ }
                            // Re-implement boundary logic for visualization to match service
                        }

                        // Let's use specific logic for visualization to match service
                        let pp0, pp1, pp2, pp3;

                        if (isPathLooping) {
                             pp0 = pathPoints[(i - 1 + pathPoints.length) % pathPoints.length];
                             pp1 = pathPoints[i];
                             pp2 = pathPoints[(i + 1) % pathPoints.length];
                             pp3 = pathPoints[(i + 2) % pathPoints.length];
                        } else {
                             pp1 = pathPoints[i];
                             pp2 = pathPoints[i + 1];
                             pp0 = pathPoints[Math.max(0, i - 1)];
                             pp3 = pathPoints[Math.min(pathPoints.length - 1, i + 2)];
                        }

                        // Sample the curve
                        const steps = 20;
                        for (let s = 1; s <= steps; s++) {
                            const tVal = s / steps;
                            const pos = getSplinePoint(pp0, pp1, pp2, pp3, tVal);
                            ctx.lineTo(pos.x * width + centerX, pos.y * height + centerY);
                        }
                    }

                    ctx.stroke();
                    ctx.setLineDash([]);
                }

                // Draw points
                pathPoints.forEach((p, index) => {
                    const px = p.x * width + centerX;
                    const py = p.y * height + centerY;

                    // Colors
                    let fillColor = 'rgba(99, 102, 241, 0.9)'; // Default Indigo
                    let strokeColor = 'white';

                    if (index === 0) {
                        fillColor = '#22c55e'; // Green for Start
                    } else if (index === pathPoints.length - 1 && !isPathLooping) {
                        fillColor = '#ef4444'; // Red for End (unless looping)
                    }

                    ctx.fillStyle = fillColor;
                    ctx.strokeStyle = strokeColor;
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.arc(px, py, 6, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();

                    // Draw number
                    ctx.fillStyle = 'white';
                    ctx.font = 'bold 10px Inter, sans-serif';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    // Offset number slightly
                    ctx.fillText(`${index + 1}`, px + 12, py - 12);
                });
            }
        }
    }

    if (isPlaying) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, focusPoint, pathPoints, isPathLooping]);

  useEffect(() => {
    if (isPlaying && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
        setFocusPoint(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setFocusPoint(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // Normalize coordinates (-0.5 to 0.5)
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    if (config.presetId === 'custom-focus') {
        setFocusPoint({ x: normalizedX, y: normalizedY });
        startTimeRef.current = performance.now(); 
    } else if (config.presetId === 'custom-path') {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
        // Don't reset time for path, usually better to keep adding
    }
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const undoPathPoint = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints(prev => prev.slice(0, -1));
  }

  const toggleLoop = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPathLooping(prev => !prev);
  }

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const totalFrames = config.duration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= totalFrames; i++) {
            const t = i / totalFrames;
            renderFrame(ctx, imageElement, t, preset, width, height);
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
