import { MotionPreset } from '../types';

// Easing function: Ease In Out Quad
const easeInOutQuad = (t: number): number => {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
};

// Simple noise function for shake
const noise = (t: number) => {
    return Math.sin(t * 10) * 0.5 + Math.sin(t * 23) * 0.25 + Math.sin(t * 47) * 0.125;
}

// Catmull-Rom Spline Math
const solveCatmullRom = (p0: number, p1: number, p2: number, p3: number, t: number) => {
    const v0 = (p2 - p0) * 0.5;
    const v1 = (p3 - p1) * 0.5;
    const t2 = t * t;
    const t3 = t * t2;
    return (2 * p1 - 2 * p2 + v0 + v1) * t3 + (-3 * p1 + 3 * p2 - 2 * v0 - v1) * t2 + v0 * t + p1;
};

const getDistance = (p1: {x: number, y: number}, p2: {x: number, y: number}) => {
    return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
}

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  progress: number, // 0 to 1
  preset: MotionPreset,
  canvasWidth: number,
  canvasHeight: number,
  travelTime: number = 2.0, // Seconds per move
  delayTime: number = 0.5, // Seconds to wait
  totalDuration: number = 5.0 // Total calculated duration
) => {
  const { params } = preset;

  // 1. Calculate Base Aspect Fill (Cover) Dimensions
  const imgRatio = image.width / image.height;
  const canvasRatio = canvasWidth / canvasHeight;

  let drawWidth, drawHeight;

  if (imgRatio > canvasRatio) {
    // Image is wider than canvas: Fit Height, Crop Width
    drawHeight = canvasHeight;
    drawWidth = canvasHeight * imgRatio;
  } else {
    // Image is taller than canvas: Fit Width, Crop Height
    drawWidth = canvasWidth;
    drawHeight = canvasWidth / imgRatio;
  }

  // 2. Interpolate Motion Parameters
  let scale = 1;
  let xOffset = 0;
  let yOffset = 0;
  let rotation = 0;

  const points = params.path;

  // Check if we are in a multi-point mode (Custom Path or Custom Focus with multiple points)
  if (points && points.length > 0) {
      // De-normalize progress to current time in seconds
      const currentTime = progress * totalDuration;

      // Handle Single Point Case (Static Focus)
      if (points.length === 1) {
          scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * easeInOutQuad(progress);
          rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * progress;
          xOffset = -points[0].x * drawWidth * scale;
          yOffset = -points[0].y * drawHeight * scale;

          // Apply Focus Creep if it's custom-focus
          if (preset.id === 'custom-focus') {
             // Continuous slow creep zoom
             scale *= (1 + progress * 0.1); 
          }

      } else {
          // MULTI-POINT TIMELINE LOGIC
          const isClosed = !!params.pathLoop;
          const numPoints = points.length;
          const numSegments = isClosed ? numPoints : numPoints - 1;
          const isSpline = preset.id === 'custom-path'; // Custom Path uses Splines, Focus uses Linear

          let timeCursor = 0;
          let found = false;
          let curX = points[0].x;
          let curY = points[0].y;

          // Base Global Zoom/Rotation
          const globalT = easeInOutQuad(progress);
          scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * globalT;
          rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * globalT;

          for (let i = 0; i < numPoints; i++) {
              // 1. WAIT PHASE (Delay at Point i)
              if (currentTime < timeCursor + delayTime) {
                  const p = points[i];
                  curX = p.x;
                  curY = p.y;

                  // Feature: "Maintain zoom in to focus point"
                  // For custom-focus, we apply a subtle zoom creep during the wait to make it feel alive
                  if (preset.id === 'custom-focus' && delayTime > 0) {
                      const waitProgress = (currentTime - timeCursor) / delayTime;
                      // Creep zoom in by 5% during the hold
                      scale *= (1 + waitProgress * 0.05);
                  }

                  found = true;
                  break;
              }
              timeCursor += delayTime;

              // 2. MOVE PHASE (Travel from i to i+1)
              if (i < numSegments) {
                  if (currentTime < timeCursor + travelTime) {
                      const moveLocalTime = currentTime - timeCursor;
                      const moveProgress = easeInOutQuad(moveLocalTime / travelTime); // Ease the movement

                      let p1, p2;
                      if (isClosed) {
                           p1 = points[i];
                           p2 = points[(i + 1) % points.length];
                      } else {
                           p1 = points[i];
                           p2 = points[i + 1];
                      }

                      if (isSpline) {
                          // Catmull-Rom Spline for Smooth Path
                          let p0, p3;
                          if (isClosed) {
                              p0 = points[(i - 1 + points.length) % points.length];
                              p3 = points[(i + 2) % points.length];
                          } else {
                              p0 = points[Math.max(0, i - 1)];
                              p3 = points[Math.min(points.length - 1, i + 2)];
                          }
                          curX = solveCatmullRom(p0.x, p1.x, p2.x, p3.x, moveProgress);
                          curY = solveCatmullRom(p0.y, p1.y, p2.y, p3.y, moveProgress);
                      } else {
                          // Linear Interpolation for Focus (Direct Movement)
                          curX = p1.x + (p2.x - p1.x) * moveProgress;
                          curY = p1.y + (p2.y - p1.y) * moveProgress;
                      }

                      found = true;
                      break;
                  }
                  timeCursor += travelTime;
              }
          }

          if (!found) {
              // End of timeline, stay at last point
              const lastP = points[isClosed ? 0 : points.length - 1];
              curX = lastP.x;
              curY = lastP.y;

              // End creep for focus
              if (preset.id === 'custom-focus') {
                  scale *= 1.05; // Stay zoomed at the final creep level
              }
          }

          // Apply offset (inverted because moving camera +X = moving image -X)
          xOffset = -curX * drawWidth * scale;
          yOffset = -curY * drawHeight * scale;
      }

  } else {
     // STANDARD PRESET LOGIC (Simple Zoom/Pan without points)
     // Use global progress eased
     const t = easeInOutQuad(progress);

     if (preset.type === 'pulse') {
        const freq = params.frequency || 1;
        const sineWave = (Math.sin(progress * Math.PI * 2 * freq) + 1) / 2;
        scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * sineWave;
        xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
        yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
        rotation = params.rotationStart;

     } else if (preset.type === 'shake') {
        // ... existing shake logic
        scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
        xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
        yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     } else {
        // Standard Linear Interpolation
        scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
        xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
        yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
        rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;
     }
  }

  // Add Shake noise (additive)
  if (preset.type === 'shake') {
      const shakeIntensity = 0.02 * canvasWidth;
      xOffset += noise(progress * 20) * shakeIntensity;
      yOffset += noise(progress * 15 + 100) * shakeIntensity;
      rotation += noise(progress * 10 + 200) * 0.5;
  }

  // 3. Rotation Safety Logic
  if (Math.abs(rotation) > 0.1) {
      const rotationRad = Math.abs(rotation * Math.PI / 180);
      const rotationScaleBoost = 1 + (rotationRad * 0.6); 
      scale = scale * rotationScaleBoost;
  }

  // 4. Boundary Clamping
  scale = Math.max(1.0, scale);

  const currentW = drawWidth * scale;
  const currentH = drawHeight * scale;
  const maxOffsetX = (currentW - canvasWidth) / 2;
  const maxOffsetY = (currentH - canvasHeight) / 2;

  xOffset = Math.max(-maxOffsetX, Math.min(maxOffsetX, xOffset));
  yOffset = Math.max(-maxOffsetY, Math.min(maxOffsetY, yOffset));

  // 5. Draw
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  ctx.save();
  ctx.translate(canvasWidth / 2 + xOffset, canvasHeight / 2 + yOffset);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(scale, scale);

  ctx.drawImage(image, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
  ctx.restore();
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2, Undo2, Repeat, Clock, Timer } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Unified Path Points (used for both Custom Path and Custom Focus)
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);
  const [isPathLooping, setIsPathLooping] = useState<boolean>(false);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    travelTime: 2.0, // Default 2s move time
    delayTime: 1.0,  // Default 1s stop time
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Reset points when changing preset mode if switching away from custom modes
  useEffect(() => {
    const isCustomMode = ['custom-path', 'custom-focus'].includes(config.presetId);

    // Auto-pause when switching to custom modes to allow editing
    if (isCustomMode && selectedImage) {
        setIsPlaying(false);
    } else if (selectedImage) {
        setIsPlaying(true);
    }
  }, [config.presetId, selectedImage]);

  // Determine if we are in a multi-point editing mode
  const isMultiPointMode = ['custom-path', 'custom-focus'].includes(config.presetId);

  // Calculate Total Duration Dynamically
  const totalDuration = useMemo(() => {
      // If we have points in custom mode
      if (isMultiPointMode && pathPoints.length > 0) {
          const numPoints = pathPoints.length;
          const numSegments = isPathLooping ? numPoints : Math.max(0, numPoints - 1);

          // Total = (Wait at points) + (Travel between points)
          if (numPoints === 1) return config.delayTime > 0 ? config.delayTime : 3.0;

          return (numPoints * config.delayTime) + (numSegments * config.travelTime);
      }

      // For standard presets, "Travel Time" effectively acts as the total duration
      return config.travelTime;
  }, [config.travelTime, config.delayTime, pathPoints.length, isPathLooping, isMultiPointMode]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (isMultiPointMode && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass points directly. renderFrame handles coordinate math.
                path: pathPoints,
                pathLoop: isPathLooping,
            }
        };
    }

    return basePreset;
  }, [config.presetId, pathPoints, isPathLooping, isMultiPointMode]);

  // Spline helper for visualization
  const getSplinePoint = (p0: any, p1: any, p2: any, p3: any, t: number) => {
      const v0x = (p2.x - p0.x) * 0.5;
      const v0y = (p2.y - p0.y) * 0.5;
      const v1x = (p3.x - p1.x) * 0.5;
      const v1y = (p3.y - p1.y) * 0.5;
      const t2 = t * t;
      const t3 = t * t2;
      return {
          x: (2 * p1.x - 2 * p2.x + v0x + v1x) * t3 + (-3 * p1.x + 3 * p2.x - 2 * v0x - v1x) * t2 + v0x * t + p1.x,
          y: (2 * p1.y - 2 * p2.y + v0y + v1y) * t3 + (-3 * p1.y + 3 * p2.y - 2 * v0y - v1y) * t2 + v0y * t + p1.y
      };
  };

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!isPlaying && !isMultiPointMode) {
        startTimeRef.current = null;
        return; 
    }

    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds

    // Loop
    const t = isPlaying ? (elapsed % totalDuration) / totalDuration : 0;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on IMAGE aspect ratio (Automatic)
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            let targetRatio = 16/9; // Default if no image
            if (imageElement) {
                targetRatio = imageElement.naturalWidth / imageElement.naturalHeight;
            }

            // Calculate dimensions to fit container while maintaining target ratio
            let width = containerWidth;
            let height = containerHeight;

            if (width / height > targetRatio) {
                 width = height * targetRatio;
            } else {
                 height = width / targetRatio;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            // RENDER LOGIC SWITCH
            const isEditMode = isMultiPointMode && !isPlaying;

            if (isEditMode) {
                // EDIT MODE: Render FULL Image (Contain)
                ctx.fillStyle = '#09090b';
                ctx.fillRect(0, 0, width, height);
                ctx.drawImage(imageElement, 0, 0, width, height);

                // Draw Path Points (overlay)
                if (pathPoints.length > 0) {
                    const centerX = width / 2;
                    const centerY = height / 2;

                    // Draw connecting curve
                    if (pathPoints.length > 1) {
                        ctx.beginPath();
                        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
                        ctx.lineWidth = 2;

                        // Use Dashed line for Focus (Linear), Solid for Path (Curved) to visualize difference
                        const isFocusMode = config.presetId === 'custom-focus';
                        if (isFocusMode) ctx.setLineDash([2, 4]); // Dotted for jumps
                        else ctx.setLineDash([5, 5]); // Dashed for path

                        const numSegments = isPathLooping ? pathPoints.length : pathPoints.length - 1;

                        const getScreenPos = (p: {x:number, y:number}) => ({
                            x: centerX + p.x * width,
                            y: centerY + p.y * height
                        });

                        const startPos = getScreenPos(pathPoints[0]);
                        ctx.moveTo(startPos.x, startPos.y);

                        for (let i = 0; i < numSegments; i++) {
                            let pp1, pp2;
                            if (isPathLooping) {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[(i + 1) % pathPoints.length];
                            } else {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[i + 1];
                            }

                            if (isFocusMode) {
                                // Linear Line for Focus Mode
                                const pos = getScreenPos(pp2);
                                ctx.lineTo(pos.x, pos.y);
                            } else {
                                // Spline Curve for Path Mode
                                let pp0, pp3;
                                if (isPathLooping) {
                                    pp0 = pathPoints[(i - 1 + pathPoints.length) % pathPoints.length];
                                    pp3 = pathPoints[(i + 2) % pathPoints.length];
                                } else {
                                    pp0 = pathPoints[Math.max(0, i - 1)];
                                    pp3 = pathPoints[Math.min(pathPoints.length - 1, i + 2)];
                                }

                                const steps = 20;
                                for (let s = 1; s <= steps; s++) {
                                    const tVal = s / steps;
                                    const interp = getSplinePoint(pp0, pp1, pp2, pp3, tVal);
                                    const pos = getScreenPos(interp);
                                    ctx.lineTo(pos.x, pos.y);
                                }
                            }
                        }
                        ctx.stroke();
                        ctx.setLineDash([]);
                    }

                    // Draw points
                    pathPoints.forEach((p, index) => {
                        const px = centerX + p.x * width;
                        const py = centerY + p.y * height;

                        let fillColor = 'rgba(99, 102, 241, 0.9)'; 
                        let strokeColor = 'white';

                        if (index === 0) fillColor = '#22c55e';
                        else if (index === pathPoints.length - 1 && !isPathLooping) fillColor = '#ef4444';

                        ctx.fillStyle = fillColor;
                        ctx.strokeStyle = strokeColor;
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.arc(px, py, 6, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.stroke();

                        ctx.fillStyle = 'white';
                        ctx.font = 'bold 10px Inter, sans-serif';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(`${index + 1}`, px + 12, py - 12);
                    });
                }

            } else {
                // PLAYBACK MODE: Use renderFrame
                // Pass dynamic timing parameters
                renderFrame(
                    ctx, 
                    imageElement, 
                    t, 
                    preset, 
                    width, 
                    height, 
                    config.travelTime, 
                    config.delayTime, 
                    totalDuration
                );
            }
        }
    }

    if (isPlaying || (!isPlaying && isMultiPointMode)) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, pathPoints, isPathLooping, isMultiPointMode, totalDuration]);

  useEffect(() => {
    // Kickstart animation loop when needed
    if ((isPlaying || (!isPlaying && isMultiPointMode)) && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement, isMultiPointMode]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current || !imageElement) return;

    // Only allow clicking in custom modes
    if (!isMultiPointMode) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // With auto-aspect ratio, simple normalization works.
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    // Clamp to image bounds
    if (Math.abs(normalizedX) <= 0.5 && Math.abs(normalizedY) <= 0.5) {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
    }
    setIsPlaying(false);
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const undoPathPoint = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints(prev => prev.slice(0, -1));
  }

  const toggleLoop = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPathLooping(prev => !prev);
  }

  // Handle Preset Switching with Intelligent Defaults
  const handlePresetSelect = (presetId: string) => {
      // Apply defaults for specific modes to improve UX
      if (presetId === 'custom-path') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 3.0, // Slower travel for smooth path
              delayTime: 0.0   // No stops by default for path
          }));
      } else if (presetId === 'custom-focus') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 1.0, // Quick jump
              delayTime: 1.5   // Longer dwell on focus point
          }));
      } else {
          // Reset to standard defaults for other presets
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 5.0 // acts as total duration
          }));
      }
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const framesToRender = totalDuration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= framesToRender; i++) {
            const t = i / framesToRender;
            renderFrame(
                ctx, 
                imageElement, 
                t, 
                preset, 
                width, 
                height, 
                config.travelTime, 
                config.delayTime, 
                totalDuration
            );
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">High-res recommended</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a] bg-black">
                    <img src={selectedImage} alt="Input" className="w-full h-48 object-contain" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] text-gray-300">
                        {imageElement ? `${imageElement.naturalWidth} x ${imageElement.naturalHeight}` : 'Loading...'}
                    </div>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             {selectedImage && (
                <div className="mt-8">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Motion Style</h3>
                    <div className="grid grid-cols-1 gap-2">
                    {MOTION_PRESETS.map((preset) => (
                        <MotionCard 
                        key={preset.id}
                        preset={preset}
                        isSelected={config.presetId === preset.id}
                        onClick={() => handlePresetSelect(preset.id)}
                        />
                    ))}
                    </div>
                </div>
             )}
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Canvas Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        {/* Toolbar */}
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-[#18181b]/80 backdrop-blur-md border border-[#27272a] p-1.5 rounded-full shadow-2xl">
            <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 transition-colors"
                disabled={!selectedImage || isRecording}
            >
                {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
            </button>
            <div className="w-px h-6 bg-white/10 mx-1"></div>
            <div className="px-3 flex flex-col">
                <span className="text-[10px] text-gray-400 font-medium">TOTAL TIME</span>
                <span className="text-xs text-white font-mono">
                    {totalDuration.toFixed(1)}s
                </span>
            </div>
        </div>

        {/* Instructions / Toasts */}
        {selectedImage && isMultiPointMode && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center gap-2 animate-in fade-in slide-in-from-bottom-4 w-full max-w-sm pointer-events-none">

                 <div className="pointer-events-auto flex items-center gap-3 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur">
                    {config.presetId === 'custom-focus' ? <MousePointerClick size={16} /> : <Route size={16} />}
                    <span className="text-xs font-medium min-w-[80px] text-center">
                        {pathPoints.length === 0 ? "Click to add" : `${pathPoints.length} points`}
                    </span>

                    <div className="w-px h-4 bg-white/20 mx-1"></div>

                    <div className="flex items-center gap-1">
                        <button 
                        onClick={undoPathPoint}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Undo Last Point"
                        >
                            <Undo2 size={14} />
                        </button>
                        <button 
                        onClick={clearPath}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Clear Path"
                        >
                            <Trash2 size={14} />
                        </button>
                    </div>
                 </div>

                 {pathPoints.length > 2 && (
                     <button 
                        onClick={toggleLoop}
                        className={`pointer-events-auto flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-medium transition-all shadow-md backdrop-blur ${isPathLooping ? 'bg-green-500 text-white' : 'bg-[#18181b]/80 border border-[#27272a] text-gray-400 hover:text-white'}`}
                     >
                         <Repeat size={12} />
                         {isPathLooping ? 'Loop Active' : 'Loop Path'}
                     </button>
                 )}
             </div>
        )}

        <div className="flex-1 flex items-center justify-center p-8 overflow-hidden relative">

          {selectedImage ? (
             <div className="relative shadow-2xl shadow-black/50 border border-[#27272a] rounded-sm overflow-hidden bg-black group">
                <canvas 
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    className={`block ${isMultiPointMode ? 'cursor-crosshair' : 'cursor-default'}`}
                />
                {isRecording && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center flex-col gap-3 z-30">
                        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-white font-medium tracking-wide">Rendering Video...</span>
                    </div>
                )}
             </div>
          ) : (
            <div className="text-center opacity-60">
              <div className="w-24 h-24 bg-[#18181b] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#27272a] shadow-inner">
                <ImageIcon className="text-gray-600 w-10 h-10" />
              </div>
              <h2 className="text-2xl font-light text-gray-300 mb-2">Motion Studio</h2>
              <p className="text-gray-500 max-w-sm mx-auto">Upload an image to start designing cinematic motion effects.</p>
            </div>
          )}
        </div>
      </main>

      {/* 3. Right Sidebar: Fine Tuning */}
      <aside className="w-80 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a]">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            Timing Controls
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {/* Travel Time Control */}
          <section>
             <div className="flex items-center justify-between mb-3">
                <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                   <Timer size={14} /> 
                   {isMultiPointMode ? "Time between Points" : "Effect Duration"}
                </h3>
                <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                    {config.travelTime}s
                </span>
             </div>
             <input 
                type="range" 
                min="0.5" 
                max="5" 
                step="0.5" 
                value={config.travelTime}
                onChange={(e) => setConfig(prev => ({ ...prev, travelTime: parseFloat(e.target.value) }))}
                className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
             />
             <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                <span>Fast (0.5s)</span>
                <span>Slow (5s)</span>
             </div>
          </section>

          {/* Delay Time Control */}
          <section className="animate-in fade-in slide-in-from-right-4">
                 <div className="flex items-center justify-between mb-3">
                    <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                        <Clock size={14} /> 
                        {isMultiPointMode ? "Wait at Focus Point" : "End Delay"}
                    </h3>
                    <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                        {config.delayTime}s
                    </span>
                 </div>
                 <input 
                    type="range" 
                    min="0" 
                    max="3" 
                    step="0.1" 
                    value={config.delayTime}
                    onChange={(e) => setConfig(prev => ({ ...prev, delayTime: parseFloat(e.target.value) }))}
                    className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                 />
                 <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                    <span>No Stop</span>
                    <span>Long Pause (3s)</span>
                 </div>
          </section>

          <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
             <div className="flex items-start gap-3">
                <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                <p className="text-[11px] text-gray-400 leading-relaxed">
                    Total video length is calculated automatically: <br/>
                    <span className="font-mono text-indigo-300">
                        (Points × Wait) + (Moves × Travel)
                    </span>
                </p>
             </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-white text-black hover:bg-gray-200 border-0 shadow-lg shadow-white/5"
              onClick={handleExport}
              isLoading={isRecording}
              disabled={!selectedImage}
              icon={<Download size={18} />}
            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

export interface MotionPreset {
  id: string;
  name: string;
  description: string;
  icon: string;
  type: 'zoom' | 'pan' | 'rotate' | 'shake' | 'pulse' | 'swing' | 'float' | 'path';
  params: {
    scaleStart: number;
    scaleEnd: number;
    xStart: number; // Percentage of width (-1 to 1)
    xEnd: number;
    yStart: number; // Percentage of height
    yEnd: number;
    rotationStart: number; // Degrees
    rotationEnd: number;
    frequency?: number; // Oscillations per duration (for pulse/swing/float)
    path?: { x: number, y: number }[]; // Array of normalized coordinates for path movement
    pathLoop?: boolean; // Whether the path should form a closed loop
    delay?: number; // Deprecated in params, moved to config
  }
}

export interface MotionConfig {
  presetId: string;
  duration: number;   // Global duration for standard presets (seconds)
  travelTime: number; // Seconds to move between points (Custom modes)
  delayTime: number;  // Seconds to wait at each point (Custom modes)
}

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2, Undo2, Repeat, Clock, Timer } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Unified Path Points (used for both Custom Path and Custom Focus)
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);
  const [isPathLooping, setIsPathLooping] = useState<boolean>(false);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5.0,   // Default for standard presets
    travelTime: 2.0, // Default 2s move time
    delayTime: 1.0,  // Default 1s stop time
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Reset points when changing preset mode if switching away from custom modes
  useEffect(() => {
    const isCustomMode = ['custom-path', 'custom-focus'].includes(config.presetId);

    // Auto-pause when switching to custom modes to allow editing
    if (isCustomMode && selectedImage) {
        setIsPlaying(false);
    } else if (selectedImage) {
        setIsPlaying(true);
    }
  }, [config.presetId, selectedImage]);

  // Determine if we are in a multi-point editing mode
  const isMultiPointMode = ['custom-path', 'custom-focus'].includes(config.presetId);

  // Calculate Total Duration Dynamically
  const totalDuration = useMemo(() => {
      // If we have points in custom mode
      if (isMultiPointMode && pathPoints.length > 0) {
          const numPoints = pathPoints.length;
          const numSegments = isPathLooping ? numPoints : Math.max(0, numPoints - 1);

          // Total = (Wait at points) + (Travel between points)
          if (numPoints === 1) return config.delayTime > 0 ? config.delayTime : 3.0;

          return (numPoints * config.delayTime) + (numSegments * config.travelTime);
      }

      // For standard presets, use the global duration slider
      return config.duration;
  }, [config.duration, config.travelTime, config.delayTime, pathPoints.length, isPathLooping, isMultiPointMode]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (isMultiPointMode && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass points directly. renderFrame handles coordinate math.
                path: pathPoints,
                pathLoop: isPathLooping,
            }
        };
    }

    return basePreset;
  }, [config.presetId, pathPoints, isPathLooping, isMultiPointMode]);

  // Spline helper for visualization
  const getSplinePoint = (p0: any, p1: any, p2: any, p3: any, t: number) => {
      const v0x = (p2.x - p0.x) * 0.5;
      const v0y = (p2.y - p0.y) * 0.5;
      const v1x = (p3.x - p1.x) * 0.5;
      const v1y = (p3.y - p1.y) * 0.5;
      const t2 = t * t;
      const t3 = t * t2;
      return {
          x: (2 * p1.x - 2 * p2.x + v0x + v1x) * t3 + (-3 * p1.x + 3 * p2.x - 2 * v0x - v1x) * t2 + v0x * t + p1.x,
          y: (2 * p1.y - 2 * p2.y + v0y + v1y) * t3 + (-3 * p1.y + 3 * p2.y - 2 * v0y - v1y) * t2 + v0y * t + p1.y
      };
  };

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!isPlaying && !isMultiPointMode) {
        startTimeRef.current = null;
        return; 
    }

    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds

    // Loop
    const t = isPlaying ? (elapsed % totalDuration) / totalDuration : 0;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on IMAGE aspect ratio (Automatic)
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            let targetRatio = 16/9; // Default if no image
            if (imageElement) {
                targetRatio = imageElement.naturalWidth / imageElement.naturalHeight;
            }

            // Calculate dimensions to fit container while maintaining target ratio
            let width = containerWidth;
            let height = containerHeight;

            if (width / height > targetRatio) {
                 width = height * targetRatio;
            } else {
                 height = width / targetRatio;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            // RENDER LOGIC SWITCH
            const isEditMode = isMultiPointMode && !isPlaying;

            if (isEditMode) {
                // EDIT MODE: Render FULL Image (Contain)
                ctx.fillStyle = '#09090b';
                ctx.fillRect(0, 0, width, height);
                ctx.drawImage(imageElement, 0, 0, width, height);

                // Draw Path Points (overlay)
                if (pathPoints.length > 0) {
                    const centerX = width / 2;
                    const centerY = height / 2;

                    // Draw connecting curve
                    if (pathPoints.length > 1) {
                        ctx.beginPath();
                        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
                        ctx.lineWidth = 2;

                        // Use Dashed line for Focus (Linear), Solid for Path (Curved) to visualize difference
                        const isFocusMode = config.presetId === 'custom-focus';
                        if (isFocusMode) ctx.setLineDash([2, 4]); // Dotted for jumps
                        else ctx.setLineDash([5, 5]); // Dashed for path

                        const numSegments = isPathLooping ? pathPoints.length : pathPoints.length - 1;

                        const getScreenPos = (p: {x:number, y:number}) => ({
                            x: centerX + p.x * width,
                            y: centerY + p.y * height
                        });

                        const startPos = getScreenPos(pathPoints[0]);
                        ctx.moveTo(startPos.x, startPos.y);

                        for (let i = 0; i < numSegments; i++) {
                            let pp1, pp2;
                            if (isPathLooping) {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[(i + 1) % pathPoints.length];
                            } else {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[i + 1];
                            }

                            if (isFocusMode) {
                                // Linear Line for Focus Mode
                                const pos = getScreenPos(pp2);
                                ctx.lineTo(pos.x, pos.y);
                            } else {
                                // Spline Curve for Path Mode
                                let pp0, pp3;
                                if (isPathLooping) {
                                    pp0 = pathPoints[(i - 1 + pathPoints.length) % pathPoints.length];
                                    pp3 = pathPoints[(i + 2) % pathPoints.length];
                                } else {
                                    pp0 = pathPoints[Math.max(0, i - 1)];
                                    pp3 = pathPoints[Math.min(pathPoints.length - 1, i + 2)];
                                }

                                const steps = 20;
                                for (let s = 1; s <= steps; s++) {
                                    const tVal = s / steps;
                                    const interp = getSplinePoint(pp0, pp1, pp2, pp3, tVal);
                                    const pos = getScreenPos(interp);
                                    ctx.lineTo(pos.x, pos.y);
                                }
                            }
                        }
                        ctx.stroke();
                        ctx.setLineDash([]);
                    }

                    // Draw points
                    pathPoints.forEach((p, index) => {
                        const px = centerX + p.x * width;
                        const py = centerY + p.y * height;

                        let fillColor = 'rgba(99, 102, 241, 0.9)'; 
                        let strokeColor = 'white';

                        if (index === 0) fillColor = '#22c55e';
                        else if (index === pathPoints.length - 1 && !isPathLooping) fillColor = '#ef4444';

                        ctx.fillStyle = fillColor;
                        ctx.strokeStyle = strokeColor;
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.arc(px, py, 6, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.stroke();

                        ctx.fillStyle = 'white';
                        ctx.font = 'bold 10px Inter, sans-serif';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(`${index + 1}`, px + 12, py - 12);
                    });
                }

            } else {
                // PLAYBACK MODE: Use renderFrame
                // Pass dynamic timing parameters
                renderFrame(
                    ctx, 
                    imageElement, 
                    t, 
                    preset, 
                    width, 
                    height, 
                    config.travelTime, 
                    config.delayTime, 
                    totalDuration
                );
            }
        }
    }

    if (isPlaying || (!isPlaying && isMultiPointMode)) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, pathPoints, isPathLooping, isMultiPointMode, totalDuration]);

  useEffect(() => {
    // Kickstart animation loop when needed
    if ((isPlaying || (!isPlaying && isMultiPointMode)) && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement, isMultiPointMode]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current || !imageElement) return;

    // Only allow clicking in custom modes
    if (!isMultiPointMode) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // With auto-aspect ratio, simple normalization works.
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    // Clamp to image bounds
    if (Math.abs(normalizedX) <= 0.5 && Math.abs(normalizedY) <= 0.5) {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
    }
    setIsPlaying(false);
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const undoPathPoint = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints(prev => prev.slice(0, -1));
  }

  const toggleLoop = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPathLooping(prev => !prev);
  }

  // Handle Preset Switching with Intelligent Defaults
  const handlePresetSelect = (presetId: string) => {
      // Apply defaults for specific modes to improve UX
      if (presetId === 'custom-path') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 3.0, // Slower travel for smooth path
              delayTime: 0.0   // No stops by default for path
          }));
      } else if (presetId === 'custom-focus') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 1.0, // Quick jump
              delayTime: 1.5   // Longer dwell on focus point
          }));
      } else {
          // Reset to standard defaults for other presets
          setConfig(prev => ({ 
              ...prev, 
              presetId,
              duration: 5.0 // Reset standard duration
          }));
      }
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const framesToRender = totalDuration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= framesToRender; i++) {
            const t = i / framesToRender;
            renderFrame(
                ctx, 
                imageElement, 
                t, 
                preset, 
                width, 
                height, 
                config.travelTime, 
                config.delayTime, 
                totalDuration
            );
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">High-res recommended</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a] bg-black">
                    <img src={selectedImage} alt="Input" className="w-full h-48 object-contain" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] text-gray-300">
                        {imageElement ? `${imageElement.naturalWidth} x ${imageElement.naturalHeight}` : 'Loading...'}
                    </div>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             {selectedImage && (
                <div className="mt-8">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Motion Style</h3>
                    <div className="grid grid-cols-1 gap-2">
                    {MOTION_PRESETS.map((preset) => (
                        <MotionCard 
                        key={preset.id}
                        preset={preset}
                        isSelected={config.presetId === preset.id}
                        onClick={() => handlePresetSelect(preset.id)}
                        />
                    ))}
                    </div>
                </div>
             )}
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Canvas Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        {/* Toolbar */}
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-[#18181b]/80 backdrop-blur-md border border-[#27272a] p-1.5 rounded-full shadow-2xl">
            <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 transition-colors"
                disabled={!selectedImage || isRecording}
            >
                {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
            </button>
            <div className="w-px h-6 bg-white/10 mx-1"></div>
            <div className="px-3 flex flex-col">
                <span className="text-[10px] text-gray-400 font-medium">TOTAL TIME</span>
                <span className="text-xs text-white font-mono">
                    {totalDuration.toFixed(1)}s
                </span>
            </div>
        </div>

        {/* Instructions / Toasts */}
        {selectedImage && isMultiPointMode && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center gap-2 animate-in fade-in slide-in-from-bottom-4 w-full max-w-sm pointer-events-none">

                 <div className="pointer-events-auto flex items-center gap-3 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur">
                    {config.presetId === 'custom-focus' ? <MousePointerClick size={16} /> : <Route size={16} />}
                    <span className="text-xs font-medium min-w-[80px] text-center">
                        {pathPoints.length === 0 ? "Click to add" : `${pathPoints.length} points`}
                    </span>

                    <div className="w-px h-4 bg-white/20 mx-1"></div>

                    <div className="flex items-center gap-1">
                        <button 
                        onClick={undoPathPoint}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Undo Last Point"
                        >
                            <Undo2 size={14} />
                        </button>
                        <button 
                        onClick={clearPath}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Clear Path"
                        >
                            <Trash2 size={14} />
                        </button>
                    </div>
                 </div>

                 {pathPoints.length > 2 && (
                     <button 
                        onClick={toggleLoop}
                        className={`pointer-events-auto flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-medium transition-all shadow-md backdrop-blur ${isPathLooping ? 'bg-green-500 text-white' : 'bg-[#18181b]/80 border border-[#27272a] text-gray-400 hover:text-white'}`}
                     >
                         <Repeat size={12} />
                         {isPathLooping ? 'Loop Active' : 'Loop Path'}
                     </button>
                 )}
             </div>
        )}

        <div className="flex-1 flex items-center justify-center p-8 overflow-hidden relative">

          {selectedImage ? (
             <div className="relative shadow-2xl shadow-black/50 border border-[#27272a] rounded-sm overflow-hidden bg-black group">
                <canvas 
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    className={`block ${isMultiPointMode ? 'cursor-crosshair' : 'cursor-default'}`}
                />
                {isRecording && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center flex-col gap-3 z-30">
                        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-white font-medium tracking-wide">Rendering Video...</span>
                    </div>
                )}
             </div>
          ) : (
            <div className="text-center opacity-60">
              <div className="w-24 h-24 bg-[#18181b] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#27272a] shadow-inner">
                <ImageIcon className="text-gray-600 w-10 h-10" />
              </div>
              <h2 className="text-2xl font-light text-gray-300 mb-2">Motion Studio</h2>
              <p className="text-gray-500 max-w-sm mx-auto">Upload an image to start designing cinematic motion effects.</p>
            </div>
          )}
        </div>
      </main>

      {/* 3. Right Sidebar: Fine Tuning */}
      <aside className="w-80 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a]">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            {isMultiPointMode ? "Timing Controls" : "Configuration"}
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {isMultiPointMode ? (
            <>
              {/* Travel Time Control */}
              <section>
                 <div className="flex items-center justify-between mb-3">
                    <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                       <Timer size={14} /> 
                       Time between Points
                    </h3>
                    <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                        {config.travelTime}s
                    </span>
                 </div>
                 <input 
                    type="range" 
                    min="0.5" 
                    max="5" 
                    step="0.5" 
                    value={config.travelTime}
                    onChange={(e) => setConfig(prev => ({ ...prev, travelTime: parseFloat(e.target.value) }))}
                    className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                 />
                 <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                    <span>Fast (0.5s)</span>
                    <span>Slow (5s)</span>
                 </div>
              </section>

              {/* Delay Time Control */}
              <section className="animate-in fade-in slide-in-from-right-4">
                     <div className="flex items-center justify-between mb-3">
                        <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                            <Clock size={14} /> 
                            Wait at Focus Point
                        </h3>
                        <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                            {config.delayTime}s
                        </span>
                     </div>
                     <input 
                        type="range" 
                        min="0" 
                        max="3" 
                        step="0.1" 
                        value={config.delayTime}
                        onChange={(e) => setConfig(prev => ({ ...prev, delayTime: parseFloat(e.target.value) }))}
                        className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                     />
                     <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                        <span>No Stop</span>
                        <span>Long Pause (3s)</span>
                     </div>
              </section>
            </>
          ) : (
            /* Duration Control for Standard Presets */
            <section>
                 <div className="flex items-center justify-between mb-3">
                    <h3 className="text-sm font-medium text-gray-400">Duration</h3>
                    <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                        {config.duration}s
                    </span>
                 </div>
                 <input 
                    type="range" 
                    min="2" 
                    max="10" 
                    step="0.5" 
                    value={config.duration}
                    onChange={(e) => setConfig(prev => ({ ...prev, duration: parseFloat(e.target.value) }))}
                    className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                 />
                 <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                    <span>Fast (2s)</span>
                    <span>Slow (10s)</span>
                 </div>
            </section>
          )}

          <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
             <div className="flex items-start gap-3">
                <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                <p className="text-[11px] text-gray-400 leading-relaxed">
                    {isMultiPointMode 
                     ? "Total video length is calculated automatically: (Points × Wait) + (Moves × Travel)"
                     : "This tool renders motion client-side. The export quality depends on your screen resolution."}
                </p>
             </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-white text-black hover:bg-gray-200 border-0 shadow-lg shadow-white/5"
              onClick={handleExport}
              isLoading={isRecording}
              disabled={!selectedImage}
              icon={<Download size={18} />}
            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

import { MotionPreset } from '../types';

// Easing function: Ease In Out Quad
const easeInOutQuad = (t: number): number => {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
};

// Simple noise function for shake
const noise = (t: number) => {
    return Math.sin(t * 10) * 0.5 + Math.sin(t * 23) * 0.25 + Math.sin(t * 47) * 0.125;
}

// Catmull-Rom Spline Math
const solveCatmullRom = (p0: number, p1: number, p2: number, p3: number, t: number) => {
    const v0 = (p2 - p0) * 0.5;
    const v1 = (p3 - p1) * 0.5;
    const t2 = t * t;
    const t3 = t * t2;
    return (2 * p1 - 2 * p2 + v0 + v1) * t3 + (-3 * p1 + 3 * p2 - 2 * v0 - v1) * t2 + v0 * t + p1;
};

const getDistance = (p1: {x: number, y: number}, p2: {x: number, y: number}) => {
    return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
}

export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  progress: number, // 0 to 1
  preset: MotionPreset,
  canvasWidth: number,
  canvasHeight: number,
  travelTime: number = 2.0, // Seconds per move
  delayTime: number = 0.5, // Seconds to wait
  totalDuration: number = 5.0 // Total calculated duration
) => {
  const { params } = preset;

  // 1. Calculate Base Aspect Fill (Cover) Dimensions
  const imgRatio = image.width / image.height;
  const canvasRatio = canvasWidth / canvasHeight;

  let drawWidth, drawHeight;

  if (imgRatio > canvasRatio) {
    // Image is wider than canvas: Fit Height, Crop Width
    drawHeight = canvasHeight;
    drawWidth = canvasHeight * imgRatio;
  } else {
    // Image is taller than canvas: Fit Width, Crop Height
    drawWidth = canvasWidth;
    drawHeight = canvasWidth / imgRatio;
  }

  // 2. Interpolate Motion Parameters
  let scale = 1;
  let xOffset = 0;
  let yOffset = 0;
  let rotation = 0;

  const points = params.path;

  // Check if we are in a multi-point mode (Custom Path or Custom Focus with multiple points)
  if (points && points.length > 0) {
      // De-normalize progress to current time in seconds
      const currentTime = progress * totalDuration;

      // Handle Single Point Case (Static Focus)
      if (points.length === 1) {
          scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * easeInOutQuad(progress);
          rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * progress;
          xOffset = -points[0].x * drawWidth * scale;
          yOffset = -points[0].y * drawHeight * scale;
          // Single point is static, no zoom creep or extra logic needed.
      } else {
          // MULTI-POINT TIMELINE LOGIC
          const isClosed = !!params.pathLoop;
          const numPoints = points.length;
          const numSegments = isClosed ? numPoints : numPoints - 1;
          const isSpline = preset.id === 'custom-path'; 

          // Calculate Scale Progress based on Travel Distance only (pauses during wait)
          const totalTravelTime = numSegments * travelTime;
          let currentTravelTime = 0;
          let calculatedScaleProgress = 0;

          // Find current position in timeline
          let timeCursor = 0;
          let found = false;
          let curX = points[0].x;
          let curY = points[0].y;

          for (let i = 0; i < numPoints; i++) {
              // 1. WAIT PHASE (Delay at Point i)
              if (currentTime < timeCursor + delayTime) {
                  const p = points[i];
                  curX = p.x;
                  curY = p.y;

                  // Static Hold: Use the travel time accumulated so far
                  calculatedScaleProgress = currentTravelTime / totalTravelTime;

                  found = true;
                  break;
              }
              timeCursor += delayTime;

              // 2. MOVE PHASE (Travel from i to i+1)
              if (i < numSegments) {
                  if (currentTime < timeCursor + travelTime) {
                      const moveLocalTime = currentTime - timeCursor;
                      const moveProgress = easeInOutQuad(moveLocalTime / travelTime); // Ease the movement

                      // Accumulate travel time for scale calculation
                      const linearTravelProgress = moveLocalTime / travelTime;
                      currentTravelTime += linearTravelProgress * travelTime;
                      calculatedScaleProgress = currentTravelTime / totalTravelTime;

                      // Position Math
                      let p1, p2;
                      if (isClosed) {
                           p1 = points[i];
                           p2 = points[(i + 1) % points.length];
                      } else {
                           p1 = points[i];
                           p2 = points[i + 1];
                      }

                      if (isSpline) {
                          let p0, p3;
                          if (isClosed) {
                              p0 = points[(i - 1 + points.length) % points.length];
                              p3 = points[(i + 2) % points.length];
                          } else {
                              p0 = points[Math.max(0, i - 1)];
                              p3 = points[Math.min(points.length - 1, i + 2)];
                          }
                          curX = solveCatmullRom(p0.x, p1.x, p2.x, p3.x, moveProgress);
                          curY = solveCatmullRom(p0.y, p1.y, p2.y, p3.y, moveProgress);
                      } else {
                          // Linear Interpolation
                          curX = p1.x + (p2.x - p1.x) * moveProgress;
                          curY = p1.y + (p2.y - p1.y) * moveProgress;
                      }

                      found = true;
                      break;
                  }
                  timeCursor += travelTime;
                  currentTravelTime += travelTime; // Add full segment duration
              }
          }

          if (!found) {
              // End of timeline
              const lastP = points[isClosed ? 0 : points.length - 1];
              curX = lastP.x;
              curY = lastP.y;
              calculatedScaleProgress = 1.0;
          }

          // Apply Scale based on calculated "distance traveled" progress
          // This ensures zoom stops when camera stops waiting.
          // We apply global ease to the whole range if path, or linear? 
          // Let's use the eased `calculatedScaleProgress` derived above.
          // Note: moveProgress above is already eased. 
          // If we want smooth zoom across segments, linear mapping of `currentTravelTime` might be better, 
          // but easing per segment feels disjointed for zoom.
          // Let's re-normalize `currentTravelTime` linearly and apply a global ease?
          // Actually, linear zoom is usually safer for complex paths.
          const linearScaleT = currentTravelTime / totalTravelTime;
          // Or just use the already computed progress if valid
          // Let's stick to linear scale interpolation mapped to travel time to avoid jerkiness.
          scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * (Math.min(1, Math.max(0, linearScaleT)));
          rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * (Math.min(1, Math.max(0, linearScaleT)));

          // Apply offset (inverted because moving camera +X = moving image -X)
          xOffset = -curX * drawWidth * scale;
          yOffset = -curY * drawHeight * scale;
      }

  } else {
     // STANDARD PRESET LOGIC (Simple Zoom/Pan without points)
     // Use global progress eased
     const t = easeInOutQuad(progress);

     if (preset.type === 'pulse') {
        const freq = params.frequency || 1;
        const sineWave = (Math.sin(progress * Math.PI * 2 * freq) + 1) / 2;
        scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * sineWave;
        xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
        yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
        rotation = params.rotationStart;

     } else if (preset.type === 'shake') {
        scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
        xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
        yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
     } else {
        // Standard Linear Interpolation
        scale = params.scaleStart + (params.scaleEnd - params.scaleStart) * t;
        xOffset = (params.xStart + (params.xEnd - params.xStart) * t) * canvasWidth;
        yOffset = (params.yStart + (params.yEnd - params.yStart) * t) * canvasHeight;
        rotation = params.rotationStart + (params.rotationEnd - params.rotationStart) * t;
     }
  }

  // Add Shake noise (additive)
  if (preset.type === 'shake') {
      const shakeIntensity = 0.02 * canvasWidth;
      xOffset += noise(progress * 20) * shakeIntensity;
      yOffset += noise(progress * 15 + 100) * shakeIntensity;
      rotation += noise(progress * 10 + 200) * 0.5;
  }

  // 3. Rotation Safety Logic
  if (Math.abs(rotation) > 0.1) {
      const rotationRad = Math.abs(rotation * Math.PI / 180);
      const rotationScaleBoost = 1 + (rotationRad * 0.6); 
      scale = scale * rotationScaleBoost;
  }

  // 4. Boundary Clamping
  scale = Math.max(1.0, scale);

  const currentW = drawWidth * scale;
  const currentH = drawHeight * scale;
  const maxOffsetX = (currentW - canvasWidth) / 2;
  const maxOffsetY = (currentH - canvasHeight) / 2;

  xOffset = Math.max(-maxOffsetX, Math.min(maxOffsetX, xOffset));
  yOffset = Math.max(-maxOffsetY, Math.min(maxOffsetY, yOffset));

  // 5. Draw
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  ctx.save();
  ctx.translate(canvasWidth / 2 + xOffset, canvasHeight / 2 + yOffset);
  ctx.rotate((rotation * Math.PI) / 180);
  ctx.scale(scale, scale);

  ctx.drawImage(image, -drawWidth / 2, -drawHeight / 2, drawWidth, drawHeight);
  ctx.restore();
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2, Undo2, Repeat, Clock, Timer } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Unified Path Points (used for both Custom Path and Custom Focus)
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);
  const [isPathLooping, setIsPathLooping] = useState<boolean>(false);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5.0,   // Default for standard presets
    travelTime: 2.0, // Default 2s move time
    delayTime: 1.0,  // Default 1s stop time
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Reset points when changing preset mode if switching away from custom modes
  useEffect(() => {
    const isCustomMode = ['custom-path', 'custom-focus'].includes(config.presetId);

    // Auto-pause when switching to custom modes to allow editing
    if (isCustomMode && selectedImage) {
        setIsPlaying(false);
    } else if (selectedImage) {
        setIsPlaying(true);
    }
  }, [config.presetId, selectedImage]);

  // Determine if we are in a multi-point editing mode
  const isMultiPointMode = ['custom-path', 'custom-focus'].includes(config.presetId);

  // Calculate Total Duration Dynamically
  const totalDuration = useMemo(() => {
      // If we have points in custom mode
      if (isMultiPointMode && pathPoints.length > 0) {
          const numPoints = pathPoints.length;

          // Case 1: Custom Focus with 1 Point -> Intro Zoom (travelTime) + Hold (delayTime)
          if (config.presetId === 'custom-focus' && numPoints === 1) {
              return config.travelTime + config.delayTime;
          }

          // Case 2: Custom Path with 1 Point -> Static Hold or Default
          if (numPoints === 1) return config.delayTime > 0 ? config.delayTime : 3.0;

          // Case 3: Multi-point sequence
          // For Custom Focus: (Wait * Points) + (Travel * Segments)
          // For Custom Path: Same logic usually
          const numSegments = isPathLooping ? numPoints : Math.max(0, numPoints - 1);
          return (numPoints * config.delayTime) + (numSegments * config.travelTime);
      }

      // For standard presets, use the global duration slider
      return config.duration;
  }, [config.duration, config.travelTime, config.delayTime, pathPoints.length, isPathLooping, isMultiPointMode, config.presetId]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (isMultiPointMode && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass points directly. renderFrame handles coordinate math.
                path: pathPoints,
                pathLoop: isPathLooping,
            }
        };
    }

    return basePreset;
  }, [config.presetId, pathPoints, isPathLooping, isMultiPointMode]);

  // Spline helper for visualization
  const getSplinePoint = (p0: any, p1: any, p2: any, p3: any, t: number) => {
      const v0x = (p2.x - p0.x) * 0.5;
      const v0y = (p2.y - p0.y) * 0.5;
      const v1x = (p3.x - p1.x) * 0.5;
      const v1y = (p3.y - p1.y) * 0.5;
      const t2 = t * t;
      const t3 = t * t2;
      return {
          x: (2 * p1.x - 2 * p2.x + v0x + v1x) * t3 + (-3 * p1.x + 3 * p2.x - 2 * v0x - v1x) * t2 + v0x * t + p1.x,
          y: (2 * p1.y - 2 * p2.y + v0y + v1y) * t3 + (-3 * p1.y + 3 * p2.y - 2 * v0y - v1y) * t2 + v0y * t + p1.y
      };
  };

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!isPlaying && !isMultiPointMode) {
        startTimeRef.current = null;
        return; 
    }

    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds

    // Loop
    const t = isPlaying ? (elapsed % totalDuration) / totalDuration : 0;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on IMAGE aspect ratio (Automatic)
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            let targetRatio = 16/9; // Default if no image
            if (imageElement) {
                targetRatio = imageElement.naturalWidth / imageElement.naturalHeight;
            }

            // Calculate dimensions to fit container while maintaining target ratio
            let width = containerWidth;
            let height = containerHeight;

            if (width / height > targetRatio) {
                 width = height * targetRatio;
            } else {
                 height = width / targetRatio;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            // RENDER LOGIC SWITCH
            const isEditMode = isMultiPointMode && !isPlaying;

            if (isEditMode) {
                // EDIT MODE: Render FULL Image (Contain)
                ctx.fillStyle = '#09090b';
                ctx.fillRect(0, 0, width, height);
                ctx.drawImage(imageElement, 0, 0, width, height);

                // Draw Path Points (overlay)
                if (pathPoints.length > 0) {
                    const centerX = width / 2;
                    const centerY = height / 2;

                    // Draw connecting curve
                    if (pathPoints.length > 1) {
                        ctx.beginPath();
                        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
                        ctx.lineWidth = 2;

                        // Use Dashed line for Focus (Linear), Solid for Path (Curved) to visualize difference
                        const isFocusMode = config.presetId === 'custom-focus';
                        if (isFocusMode) ctx.setLineDash([2, 4]); // Dotted for jumps
                        else ctx.setLineDash([5, 5]); // Dashed for path

                        const numSegments = isPathLooping ? pathPoints.length : pathPoints.length - 1;

                        const getScreenPos = (p: {x:number, y:number}) => ({
                            x: centerX + p.x * width,
                            y: centerY + p.y * height
                        });

                        const startPos = getScreenPos(pathPoints[0]);
                        ctx.moveTo(startPos.x, startPos.y);

                        for (let i = 0; i < numSegments; i++) {
                            let pp1, pp2;
                            if (isPathLooping) {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[(i + 1) % pathPoints.length];
                            } else {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[i + 1];
                            }

                            if (isFocusMode) {
                                // Linear Line for Focus Mode
                                const pos = getScreenPos(pp2);
                                ctx.lineTo(pos.x, pos.y);
                            } else {
                                // Spline Curve for Path Mode
                                let pp0, pp3;
                                if (isPathLooping) {
                                    pp0 = pathPoints[(i - 1 + pathPoints.length) % pathPoints.length];
                                    pp3 = pathPoints[(i + 2) % pathPoints.length];
                                } else {
                                    pp0 = pathPoints[Math.max(0, i - 1)];
                                    pp3 = pathPoints[Math.min(pathPoints.length - 1, i + 2)];
                                }

                                const steps = 20;
                                for (let s = 1; s <= steps; s++) {
                                    const tVal = s / steps;
                                    const interp = getSplinePoint(pp0, pp1, pp2, pp3, tVal);
                                    const pos = getScreenPos(interp);
                                    ctx.lineTo(pos.x, pos.y);
                                }
                            }
                        }
                        ctx.stroke();
                        ctx.setLineDash([]);
                    }

                    // Draw points
                    pathPoints.forEach((p, index) => {
                        const px = centerX + p.x * width;
                        const py = centerY + p.y * height;

                        let fillColor = 'rgba(99, 102, 241, 0.9)'; 
                        let strokeColor = 'white';

                        if (index === 0) fillColor = '#22c55e';
                        else if (index === pathPoints.length - 1 && !isPathLooping) fillColor = '#ef4444';

                        ctx.fillStyle = fillColor;
                        ctx.strokeStyle = strokeColor;
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.arc(px, py, 6, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.stroke();

                        ctx.fillStyle = 'white';
                        ctx.font = 'bold 10px Inter, sans-serif';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(`${index + 1}`, px + 12, py - 12);
                    });
                }

            } else {
                // PLAYBACK MODE: Use renderFrame
                // Pass dynamic timing parameters
                renderFrame(
                    ctx, 
                    imageElement, 
                    t, 
                    preset, 
                    width, 
                    height, 
                    config.travelTime, 
                    config.delayTime, 
                    totalDuration
                );
            }
        }
    }

    if (isPlaying || (!isPlaying && isMultiPointMode)) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, pathPoints, isPathLooping, isMultiPointMode, totalDuration]);

  useEffect(() => {
    // Kickstart animation loop when needed
    if ((isPlaying || (!isPlaying && isMultiPointMode)) && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement, isMultiPointMode]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current || !imageElement) return;

    // Only allow clicking in custom modes
    if (!isMultiPointMode) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // With auto-aspect ratio, simple normalization works.
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    // Clamp to image bounds
    if (Math.abs(normalizedX) <= 0.5 && Math.abs(normalizedY) <= 0.5) {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
    }
    setIsPlaying(false);
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const undoPathPoint = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints(prev => prev.slice(0, -1));
  }

  const toggleLoop = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPathLooping(prev => !prev);
  }

  // Handle Preset Switching with Intelligent Defaults
  const handlePresetSelect = (presetId: string) => {
      // Apply defaults for specific modes to improve UX
      if (presetId === 'custom-path') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 3.0, // Slower travel for smooth path
              delayTime: 0.0   // No stops by default for path
          }));
      } else if (presetId === 'custom-focus') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 2.0, // Standard move
              delayTime: 2.0   // Standard wait
          }));
      } else {
          // Reset to standard defaults for other presets
          setConfig(prev => ({ 
              ...prev, 
              presetId,
              duration: 5.0 // Reset standard duration
          }));
      }
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const framesToRender = totalDuration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= framesToRender; i++) {
            const t = i / framesToRender;
            renderFrame(
                ctx, 
                imageElement, 
                t, 
                preset, 
                width, 
                height, 
                config.travelTime, 
                config.delayTime, 
                totalDuration
            );
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
