            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2, Undo2, Repeat, Clock, Timer, Map } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Unified Path Points (used for both Custom Path and Custom Focus)
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);
  const [isPathLooping, setIsPathLooping] = useState<boolean>(false);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5.0,   // Default for standard presets
    travelTime: 2.0, // Default 2s move time
    delayTime: 1.0,  // Default 1s stop time
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null); // Ref for the available space container
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Reset points when changing preset mode if switching away from custom modes
  useEffect(() => {
    const isCustomMode = ['custom-path', 'custom-focus', 'cinematic-tour'].includes(config.presetId);

    // Auto-pause when switching to custom modes to allow editing
    if (isCustomMode && selectedImage) {
        setIsPlaying(false);
    } else if (selectedImage) {
        setIsPlaying(true);
    }
  }, [config.presetId, selectedImage]);

  // Determine if we are in a multi-point editing mode
  const isMultiPointMode = ['custom-path', 'custom-focus', 'cinematic-tour'].includes(config.presetId);

  // Calculate Total Duration Dynamically
  const totalDuration = useMemo(() => {
      // If we have points in custom mode
      if (isMultiPointMode && pathPoints.length > 0) {
          const numPoints = pathPoints.length;

          // Case 1: Custom Focus OR Cinematic Tour (Segmented: Intro + N-1 moves + N waits)
          // Simplified Formula: N * (Travel + Wait)
          if (config.presetId === 'custom-focus' || config.presetId === 'cinematic-tour') {
              return numPoints * (config.travelTime + config.delayTime);
          }

          // Case 2: Custom Path (Smooth Spline Continuous)
          if (numPoints === 1) return config.delayTime > 0 ? config.delayTime : 3.0;

          const numSegments = isPathLooping ? numPoints : Math.max(0, numPoints - 1);
          return (numPoints * config.delayTime) + (numSegments * config.travelTime);
      }

      // For standard presets, use the global duration slider
      return config.duration;
  }, [config.duration, config.travelTime, config.delayTime, pathPoints.length, isPathLooping, isMultiPointMode, config.presetId]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (isMultiPointMode && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass points directly. renderFrame handles coordinate math.
                path: pathPoints,
                pathLoop: isPathLooping,
            }
        };
    }

    return basePreset;
  }, [config.presetId, pathPoints, isPathLooping, isMultiPointMode]);

  // Spline helper for visualization
  const getSplinePoint = (p0: any, p1: any, p2: any, p3: any, t: number) => {
      const v0x = (p2.x - p0.x) * 0.5;
      const v0y = (p2.y - p0.y) * 0.5;
      const v1x = (p3.x - p1.x) * 0.5;
      const v1y = (p3.y - p1.y) * 0.5;
      const t2 = t * t;
      const t3 = t * t2;
      return {
          x: (2 * p1.x - 2 * p2.x + v0x + v1x) * t3 + (-3 * p1.x + 3 * p2.x - 2 * v0x - v1x) * t2 + v0x * t + p1.x,
          y: (2 * p1.y - 2 * p2.y + v0y + v1y) * t3 + (-3 * p1.y + 3 * p2.y - 2 * v0y - v1y) * t2 + v0y * t + p1.y
      };
  };

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!isPlaying && !isMultiPointMode) {
        startTimeRef.current = null;
        return; 
    }

    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds

    // Loop
    const t = isPlaying ? (elapsed % totalDuration) / totalDuration : 0;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // MEASUREMENT LOGIC UPDATE: Use containerRef for available space
            // Default to measuring parent if ref not available, though ref is preferred
            const containerEl = containerRef.current || canvasRef.current.parentElement;

            // Subtract padding (approx 64px for p-8) to ensure it fits comfortably
            const availableWidth = containerEl ? containerEl.clientWidth - 64 : 800;
            const availableHeight = containerEl ? containerEl.clientHeight - 64 : 600;

            let targetRatio = 16/9; // Fallback
            if (imageElement) {
                targetRatio = imageElement.naturalWidth / imageElement.naturalHeight;
            }

            // Calculate dimensions to fit container while maintaining exact image ratio
            let width = availableWidth;
            let height = availableHeight;

            // Logic: `availableWidth / availableHeight` gives the container's aspect ratio.
            // If the image is wider than the container (relative to height), we limit by width.
            // If the image is taller, we limit by height.
            if (width / height > targetRatio) {
                 // Container is wider than image -> Image fits by height
                 width = height * targetRatio;
            } else {
                 // Container is taller than image -> Image fits by width
                 height = width / targetRatio;
            }

            // Round to avoid sub-pixel blurring
            width = Math.floor(width);
            height = Math.floor(height);

            // High DPI scaling for crisp rendering on retina screens
            const dpr = window.devicePixelRatio || 1;

            // Only resize canvas buffer if dimensions changed (optimization)
            if (canvasRef.current.width !== width * dpr || canvasRef.current.height !== height * dpr) {
                canvasRef.current.width = width * dpr;
                canvasRef.current.height = height * dpr;
                canvasRef.current.style.width = `${width}px`;
                canvasRef.current.style.height = `${height}px`;
            }

            // Always reset transform before rendering
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

            // RENDER LOGIC SWITCH
            const isEditMode = isMultiPointMode && !isPlaying;

            if (isEditMode) {
                // EDIT MODE: Render FULL Image (Contain)
                ctx.fillStyle = '#09090b';
                ctx.fillRect(0, 0, width, height);
                ctx.drawImage(imageElement, 0, 0, width, height);

                // Draw Path Points (overlay)
                if (pathPoints.length > 0) {
                    const centerX = width / 2;
                    const centerY = height / 2;

                    // Draw connecting curve
                    if (pathPoints.length > 1) {
                        ctx.beginPath();
                        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
                        ctx.lineWidth = 2;

                        // Use Dashed line for Focus (Linear), Solid for Path/Tour (Curved)
                        const isLinearMode = config.presetId === 'custom-focus';

                        if (isLinearMode) ctx.setLineDash([2, 4]); // Dotted
                        else ctx.setLineDash([5, 5]); // Dashed

                        const numSegments = isPathLooping ? pathPoints.length : pathPoints.length - 1;

                        const getScreenPos = (p: {x:number, y:number}) => ({
                            x: centerX + p.x * width,
                            y: centerY + p.y * height
                        });

                        const startPos = getScreenPos(pathPoints[0]);
                        ctx.moveTo(startPos.x, startPos.y);

                        for (let i = 0; i < numSegments; i++) {
                            let pp1, pp2;
                            if (isPathLooping) {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[(i + 1) % pathPoints.length];
                            } else {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[i + 1];
                            }

                            if (isLinearMode) {
                                // Linear Line for Focus Mode
                                const pos = getScreenPos(pp2);
                                ctx.lineTo(pos.x, pos.y);
                            } else {
                                // Spline Curve for Path Mode & Cinematic Tour
                                let pp0, pp3;
                                if (isPathLooping) {
                                    pp0 = pathPoints[(i - 1 + pathPoints.length) % pathPoints.length];
                                    pp3 = pathPoints[(i + 2) % pathPoints.length];
                                } else {
                                    pp0 = pathPoints[Math.max(0, i - 1)];
                                    pp3 = pathPoints[Math.min(pathPoints.length - 1, i + 2)];
                                }

                                const steps = 20;
                                for (let s = 1; s <= steps; s++) {
                                    const tVal = s / steps;
                                    const interp = getSplinePoint(pp0, pp1, pp2, pp3, tVal);
                                    const pos = getScreenPos(interp);
                                    ctx.lineTo(pos.x, pos.y);
                                }
                            }
                        }
                        ctx.stroke();
                        ctx.setLineDash([]);
                    }

                    // Draw points
                    pathPoints.forEach((p, index) => {
                        const px = centerX + p.x * width;
                        const py = centerY + p.y * height;

                        let fillColor = 'rgba(99, 102, 241, 0.9)'; 
                        let strokeColor = 'white';

                        if (index === 0) fillColor = '#22c55e';
                        else if (index === pathPoints.length - 1 && !isPathLooping) fillColor = '#ef4444';

                        ctx.fillStyle = fillColor;
                        ctx.strokeStyle = strokeColor;
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.arc(px, py, 6, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.stroke();

                        ctx.fillStyle = 'white';
                        ctx.font = 'bold 10px Inter, sans-serif';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(`${index + 1}`, px + 12, py - 12);
                    });
                }

            } else {
                // PLAYBACK MODE: Use renderFrame
                // Pass dynamic timing parameters
                renderFrame(
                    ctx, 
                    imageElement, 
                    t, 
                    preset, 
                    width, 
                    height, 
                    config.travelTime, 
                    config.delayTime, 
                    totalDuration
                );
            }
        }
    }

    if (isPlaying || (!isPlaying && isMultiPointMode)) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, pathPoints, isPathLooping, isMultiPointMode, totalDuration]);

  useEffect(() => {
    // Kickstart animation loop when needed
    if ((isPlaying || (!isPlaying && isMultiPointMode)) && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement, isMultiPointMode]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current || !imageElement) return;

    // Only allow clicking in custom modes
    if (!isMultiPointMode) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // With auto-aspect ratio, simple normalization works.
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    // Clamp to image bounds
    if (Math.abs(normalizedX) <= 0.5 && Math.abs(normalizedY) <= 0.5) {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
    }
    setIsPlaying(false);
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const undoPathPoint = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints(prev => prev.slice(0, -1));
  }

  const toggleLoop = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPathLooping(prev => !prev);
  }

  // Handle Preset Switching with Intelligent Defaults
  const handlePresetSelect = (presetId: string) => {
      // Apply defaults for specific modes to improve UX
      if (presetId === 'custom-path') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 3.0, // Slower travel for smooth path
              delayTime: 0.0   // No stops by default for path
          }));
      } else if (presetId === 'custom-focus') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 2.0, // Standard move
              delayTime: 2.0   // Standard wait
          }));
      } else if (presetId === 'cinematic-tour') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 2.5, // Bit slower for smooth curves
              delayTime: 1.5   // Bit shorter wait
          }));
      } else {
          // Reset to standard defaults for other presets
          setConfig(prev => ({ 
              ...prev, 
              presetId,
              duration: 5.0 // Reset standard duration
          }));
      }
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;

    // Use the High Quality Stream
    const stream = canvas.captureStream(60); 
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9', videoBitsPerSecond: 5000000 }); // 5Mbps
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const framesToRender = totalDuration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Use current canvas dimensions (which now respect aspect ratio)
    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= framesToRender; i++) {
            const t = i / framesToRender;
            renderFrame(
                ctx, 
                imageElement, 
                t, 
                preset, 
                width, 
                height, 
                config.travelTime, 
                config.delayTime, 
                totalDuration
            );
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">High-res recommended</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a] bg-black">
                    <img src={selectedImage} alt="Input" className="w-full h-48 object-contain" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] text-gray-300">
                        {imageElement ? `${imageElement.naturalWidth} x ${imageElement.naturalHeight}` : 'Loading...'}
                    </div>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             <div className="mt-8">
                <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Motion Style</h3>
                <div className="grid grid-cols-1 gap-2">
                {MOTION_PRESETS.map((preset) => (
                    <MotionCard 
                    key={preset.id}
                    preset={preset}
                    isSelected={config.presetId === preset.id}
                    onClick={() => handlePresetSelect(preset.id)}
                    />
                ))}
                </div>
            </div>
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Canvas Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        {/* Toolbar */}
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-[#18181b]/80 backdrop-blur-md border border-[#27272a] p-1.5 rounded-full shadow-2xl">
            <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 transition-colors"
                disabled={!selectedImage || isRecording}
            >
                {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
            </button>
            <div className="w-px h-6 bg-white/10 mx-1"></div>
            <div className="px-3 flex flex-col">
                <span className="text-[10px] text-gray-400 font-medium">TOTAL TIME</span>
                <span className="text-xs text-white font-mono">
                    {totalDuration.toFixed(1)}s
                </span>
            </div>
        </div>

        {/* Instructions / Toasts */}
        {selectedImage && isMultiPointMode && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center gap-2 animate-in fade-in slide-in-from-bottom-4 w-full max-w-sm pointer-events-none">

                 <div className="pointer-events-auto flex items-center gap-3 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur">
                    {config.presetId === 'custom-focus' ? <MousePointerClick size={16} /> : config.presetId === 'cinematic-tour' ? <Map size={16} /> : <Route size={16} />}
                    <span className="text-xs font-medium min-w-[80px] text-center">
                        {pathPoints.length === 0 ? "Click to add" : `${pathPoints.length} points`}
                    </span>

                    <div className="w-px h-4 bg-white/20 mx-1"></div>

                    <div className="flex items-center gap-1">
                        <button 
                        onClick={undoPathPoint}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Undo Last Point"
                        >
                            <Undo2 size={14} />
                        </button>
                        <button 
                        onClick={clearPath}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Clear Path"
                        >
                            <Trash2 size={14} />
                        </button>
                    </div>
                 </div>

                 {pathPoints.length > 2 && (
                     <button 
                        onClick={toggleLoop}
                        className={`pointer-events-auto flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-medium transition-all shadow-md backdrop-blur ${isPathLooping ? 'bg-green-500 text-white' : 'bg-[#18181b]/80 border border-[#27272a] text-gray-400 hover:text-white'}`}
                     >
                         <Repeat size={12} />
                         {isPathLooping ? 'Loop Active' : 'Loop Path'}
                     </button>
                 )}
             </div>
        )}

        <div ref={containerRef} className="flex-1 flex items-center justify-center p-8 overflow-hidden relative">

          {selectedImage ? (
             <div className="relative shadow-2xl shadow-black/50 border border-[#27272a] rounded-sm overflow-hidden bg-black group">
                <canvas 
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    className={`block ${isMultiPointMode ? 'cursor-crosshair' : 'cursor-default'}`}
                />
                {isRecording && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center flex-col gap-3 z-30">
                        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-white font-medium tracking-wide">Rendering Video...</span>
                    </div>
                )}
             </div>
          ) : (
            <div className="text-center opacity-60">
              <div className="w-24 h-24 bg-[#18181b] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#27272a] shadow-inner">
                <ImageIcon className="text-gray-600 w-10 h-10" />
              </div>
              <h2 className="text-2xl font-light text-gray-300 mb-2">Motion Studio</h2>
              <p className="text-gray-500 max-w-sm mx-auto">Upload an image to start designing cinematic motion effects.</p>
            </div>
          )}
        </div>
      </main>

      {/* 3. Right Sidebar: Fine Tuning */}
      <aside className="w-80 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a]">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            {isMultiPointMode ? "Timing Controls" : "Configuration"}
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {isMultiPointMode ? (
            <>
              {/* Travel Time Control */}
              <section>
                 <div className="flex items-center justify-between mb-3">
                    <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                       <Timer size={14} /> 
                       Time between Points
                    </h3>
                    <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                        {config.travelTime}s
                    </span>
                 </div>
                 <input 
                    type="range" 
                    min="0.5" 
                    max="5" 
                    step="0.5" 
                    value={config.travelTime}
                    onChange={(e) => setConfig(prev => ({ ...prev, travelTime: parseFloat(e.target.value) }))}
                    className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                 />
                 <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                    <span>Fast (0.5s)</span>
                    <span>Slow (5s)</span>
                 </div>
              </section>

              {/* Delay Time Control */}
              <section className="animate-in fade-in slide-in-from-right-4">
                     <div className="flex items-center justify-between mb-3">
                        <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                            <Clock size={14} /> 
                            Wait at Focus Point
                        </h3>
                        <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                            {config.delayTime}s
                        </span>
                     </div>
                     <input 
                        type="range" 
                        min="0" 
                        max="3" 
                        step="0.1" 
                        value={config.delayTime}
                        onChange={(e) => setConfig(prev => ({ ...prev, delayTime: parseFloat(e.target.value) }))}
                        className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                     />
                     <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                        <span>No Stop</span>
                        <span>Long Pause (3s)</span>
                     </div>
              </section>
            </>
          ) : (
            /* Duration Control for Standard Presets */
            <section>
                 <div className="flex items-center justify-between mb-3">
                    <h3 className="text-sm font-medium text-gray-400">Duration</h3>
                    <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                        {config.duration}s
                    </span>
                 </div>
                 <input 
                    type="range" 
                    min="2" 
                    max="10" 
                    step="0.5" 
                    value={config.duration}
                    onChange={(e) => setConfig(prev => ({ ...prev, duration: parseFloat(e.target.value) }))}
                    className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                 />
                 <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                    <span>Fast (2s)</span>
                    <span>Slow (10s)</span>
                 </div>
            </section>
          )}

          <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
             <div className="flex items-start gap-3">
                <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                <p className="text-[11px] text-gray-400 leading-relaxed">
                    {isMultiPointMode 
                     ? "Total video length is calculated automatically: (Points × Wait) + (Moves × Travel)"
                     : "This tool renders motion client-side. The export quality depends on your screen resolution."}
                </p>
             </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-white text-black hover:bg-gray-200 border-0 shadow-lg shadow-white/5"
              onClick={handleExport}
              isLoading={isRecording}
              disabled={!selectedImage}
              icon={<Download size={18} />}
            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Upload, Download, Play, Pause, Video, Settings2, Image as ImageIcon, X, Film, Info, RefreshCw, MousePointerClick, Route, Trash2, Undo2, Repeat, Clock, Timer, Map } from 'lucide-react';
import { Button } from './components/Button';
import { MotionCard } from './components/MotionCard';
import { MOTION_PRESETS } from './constants';
import { MotionConfig } from './types';
import { renderFrame } from './services/motionService';

const App: React.FC = () => {
  // State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [progress, setProgress] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  // Unified Path Points (used for both Custom Path and Custom Focus)
  const [pathPoints, setPathPoints] = useState<{ x: number, y: number }[]>([]);
  const [isPathLooping, setIsPathLooping] = useState<boolean>(false);

  // Configuration State
  const [config, setConfig] = useState<MotionConfig>({
    presetId: MOTION_PRESETS[0].id,
    duration: 5.0,   // Default for standard presets
    travelTime: 2.0, // Default 2s move time
    delayTime: 1.0,  // Default 1s stop time
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);

  // Load Image Object
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setIsPlaying(true);
      };
      img.onerror = () => setError("Failed to load image");
    } else {
      setImageElement(null);
    }
  }, [selectedImage]);

  // Reset points when changing preset mode if switching away from custom modes
  useEffect(() => {
    const isCustomMode = ['custom-path', 'custom-focus', 'cinematic-tour'].includes(config.presetId);

    // Auto-pause when switching to custom modes to allow editing
    if (isCustomMode && selectedImage) {
        setIsPlaying(false);
    } else if (selectedImage) {
        setIsPlaying(true);
    }
  }, [config.presetId, selectedImage]);

  // Determine if we are in a multi-point editing mode
  const isMultiPointMode = ['custom-path', 'custom-focus', 'cinematic-tour'].includes(config.presetId);

  // Calculate Total Duration Dynamically
  const totalDuration = useMemo(() => {
      // If we have points in custom mode
      if (isMultiPointMode && pathPoints.length > 0) {
          const numPoints = pathPoints.length;

          // Case 1: Custom Focus OR Cinematic Tour (Segmented: Intro + N-1 moves + N waits)
          // Simplified Formula: N * (Travel + Wait)
          if (config.presetId === 'custom-focus' || config.presetId === 'cinematic-tour') {
              return numPoints * (config.travelTime + config.delayTime);
          }

          // Case 2: Custom Path (Smooth Spline Continuous)
          if (numPoints === 1) return config.delayTime > 0 ? config.delayTime : 3.0;

          const numSegments = isPathLooping ? numPoints : Math.max(0, numPoints - 1);
          return (numPoints * config.delayTime) + (numSegments * config.travelTime);
      }

      // For standard presets, use the global duration slider
      return config.duration;
  }, [config.duration, config.travelTime, config.delayTime, pathPoints.length, isPathLooping, isMultiPointMode, config.presetId]);

  // Calculate dynamic preset based on config and custom points
  const getActivePreset = useCallback(() => {
    const basePreset = MOTION_PRESETS.find(p => p.id === config.presetId);
    if (!basePreset) return null;

    if (isMultiPointMode && pathPoints.length > 0) {
        return {
            ...basePreset,
            params: {
                ...basePreset.params,
                // Pass points directly. renderFrame handles coordinate math.
                path: pathPoints,
                pathLoop: isPathLooping,
            }
        };
    }

    return basePreset;
  }, [config.presetId, pathPoints, isPathLooping, isMultiPointMode]);

  // Spline helper for visualization
  const getSplinePoint = (p0: any, p1: any, p2: any, p3: any, t: number) => {
      const v0x = (p2.x - p0.x) * 0.5;
      const v0y = (p2.y - p0.y) * 0.5;
      const v1x = (p3.x - p1.x) * 0.5;
      const v1y = (p3.y - p1.y) * 0.5;
      const t2 = t * t;
      const t3 = t * t2;
      return {
          x: (2 * p1.x - 2 * p2.x + v0x + v1x) * t3 + (-3 * p1.x + 3 * p2.x - 2 * v0x - v1x) * t2 + v0x * t + p1.x,
          y: (2 * p1.y - 2 * p2.y + v0y + v1y) * t3 + (-3 * p1.y + 3 * p2.y - 2 * v0y - v1y) * t2 + v0y * t + p1.y
      };
  };

  // Animation Loop for Preview
  const animate = useCallback((time: number) => {
    if (!isPlaying && !isMultiPointMode) {
        startTimeRef.current = null;
        return; 
    }

    if (!startTimeRef.current) startTimeRef.current = time;
    const elapsed = (time - startTimeRef.current) / 1000; // seconds

    // Loop
    const t = isPlaying ? (elapsed % totalDuration) / totalDuration : 0;
    setProgress(t);

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        const preset = getActivePreset();

        if (ctx && preset) {
            // Set canvas size based on IMAGE aspect ratio (Automatic)
            const containerHeight = canvasRef.current.parentElement?.clientHeight || 600;
            const containerWidth = canvasRef.current.parentElement?.clientWidth || 400;

            let targetRatio = 16/9; // Default if no image
            if (imageElement) {
                targetRatio = imageElement.naturalWidth / imageElement.naturalHeight;
            }

            // Calculate dimensions to fit container while maintaining target ratio
            let width = containerWidth;
            let height = containerHeight;

            if (width / height > targetRatio) {
                 width = height * targetRatio;
            } else {
                 height = width / targetRatio;
            }

            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvasRef.current.width = width * dpr;
            canvasRef.current.height = height * dpr;
            canvasRef.current.style.width = `${width}px`;
            canvasRef.current.style.height = `${height}px`;
            ctx.scale(dpr, dpr);

            // RENDER LOGIC SWITCH
            const isEditMode = isMultiPointMode && !isPlaying;

            if (isEditMode) {
                // EDIT MODE: Render FULL Image (Contain)
                ctx.fillStyle = '#09090b';
                ctx.fillRect(0, 0, width, height);
                ctx.drawImage(imageElement, 0, 0, width, height);

                // Draw Path Points (overlay)
                if (pathPoints.length > 0) {
                    const centerX = width / 2;
                    const centerY = height / 2;

                    // Draw connecting curve
                    if (pathPoints.length > 1) {
                        ctx.beginPath();
                        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
                        ctx.lineWidth = 2;

                        // Use Dashed line for Focus (Linear), Solid for Path/Tour (Curved)
                        const isLinearMode = config.presetId === 'custom-focus';

                        if (isLinearMode) ctx.setLineDash([2, 4]); // Dotted
                        else ctx.setLineDash([5, 5]); // Dashed

                        const numSegments = isPathLooping ? pathPoints.length : pathPoints.length - 1;

                        const getScreenPos = (p: {x:number, y:number}) => ({
                            x: centerX + p.x * width,
                            y: centerY + p.y * height
                        });

                        const startPos = getScreenPos(pathPoints[0]);
                        ctx.moveTo(startPos.x, startPos.y);

                        for (let i = 0; i < numSegments; i++) {
                            let pp1, pp2;
                            if (isPathLooping) {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[(i + 1) % pathPoints.length];
                            } else {
                                pp1 = pathPoints[i];
                                pp2 = pathPoints[i + 1];
                            }

                            if (isLinearMode) {
                                // Linear Line for Focus Mode
                                const pos = getScreenPos(pp2);
                                ctx.lineTo(pos.x, pos.y);
                            } else {
                                // Spline Curve for Path Mode & Cinematic Tour
                                let pp0, pp3;
                                if (isPathLooping) {
                                    pp0 = pathPoints[(i - 1 + pathPoints.length) % pathPoints.length];
                                    pp3 = pathPoints[(i + 2) % pathPoints.length];
                                } else {
                                    pp0 = pathPoints[Math.max(0, i - 1)];
                                    pp3 = pathPoints[Math.min(pathPoints.length - 1, i + 2)];
                                }

                                const steps = 20;
                                for (let s = 1; s <= steps; s++) {
                                    const tVal = s / steps;
                                    const interp = getSplinePoint(pp0, pp1, pp2, pp3, tVal);
                                    const pos = getScreenPos(interp);
                                    ctx.lineTo(pos.x, pos.y);
                                }
                            }
                        }
                        ctx.stroke();
                        ctx.setLineDash([]);
                    }

                    // Draw points
                    pathPoints.forEach((p, index) => {
                        const px = centerX + p.x * width;
                        const py = centerY + p.y * height;

                        let fillColor = 'rgba(99, 102, 241, 0.9)'; 
                        let strokeColor = 'white';

                        if (index === 0) fillColor = '#22c55e';
                        else if (index === pathPoints.length - 1 && !isPathLooping) fillColor = '#ef4444';

                        ctx.fillStyle = fillColor;
                        ctx.strokeStyle = strokeColor;
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.arc(px, py, 6, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.stroke();

                        ctx.fillStyle = 'white';
                        ctx.font = 'bold 10px Inter, sans-serif';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(`${index + 1}`, px + 12, py - 12);
                    });
                }

            } else {
                // PLAYBACK MODE: Use renderFrame
                // Pass dynamic timing parameters
                renderFrame(
                    ctx, 
                    imageElement, 
                    t, 
                    preset, 
                    width, 
                    height, 
                    config.travelTime, 
                    config.delayTime, 
                    totalDuration
                );
            }
        }
    }

    if (isPlaying || (!isPlaying && isMultiPointMode)) {
        requestRef.current = requestAnimationFrame(animate);
    }
  }, [config, imageElement, isPlaying, getActivePreset, pathPoints, isPathLooping, isMultiPointMode, totalDuration]);

  useEffect(() => {
    // Kickstart animation loop when needed
    if ((isPlaying || (!isPlaying && isMultiPointMode)) && imageElement) {
        requestRef.current = requestAnimationFrame(animate);
    }
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        startTimeRef.current = null;
    };
  }, [isPlaying, animate, imageElement, isMultiPointMode]);


  // Handlers
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setSelectedImage(e.target?.result as string);
        setError(null);
        setPathPoints([]);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    setImageElement(null);
    setPathPoints([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current || !imageElement) return;

    // Only allow clicking in custom modes
    if (!isMultiPointMode) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const width = rect.width;
    const height = rect.height;

    // With auto-aspect ratio, simple normalization works.
    const normalizedX = (x - width / 2) / width;
    const normalizedY = (y - height / 2) / height;

    // Clamp to image bounds
    if (Math.abs(normalizedX) <= 0.5 && Math.abs(normalizedY) <= 0.5) {
        setPathPoints(prev => [...prev, { x: normalizedX, y: normalizedY }]);
    }
    setIsPlaying(false);
  };

  const clearPath = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints([]);
  }

  const undoPathPoint = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPathPoints(prev => prev.slice(0, -1));
  }

  const toggleLoop = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPathLooping(prev => !prev);
  }

  // Handle Preset Switching with Intelligent Defaults
  const handlePresetSelect = (presetId: string) => {
      // Apply defaults for specific modes to improve UX
      if (presetId === 'custom-path') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 3.0, // Slower travel for smooth path
              delayTime: 0.0   // No stops by default for path
          }));
      } else if (presetId === 'custom-focus') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 2.0, // Standard move
              delayTime: 2.0   // Standard wait
          }));
      } else if (presetId === 'cinematic-tour') {
          setConfig(prev => ({ 
              ...prev, 
              presetId, 
              travelTime: 2.5, // Bit slower for smooth curves
              delayTime: 1.5   // Bit shorter wait
          }));
      } else {
          // Reset to standard defaults for other presets
          setConfig(prev => ({ 
              ...prev, 
              presetId,
              duration: 5.0 // Reset standard duration
          }));
      }
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageElement) return;

    setIsRecording(true);
    setIsPlaying(false); // Stop preview loop
    if (requestRef.current) cancelAnimationFrame(requestRef.current);

    const canvas = canvasRef.current;
    const stream = canvas.captureStream(60); // 60 FPS
    const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks: Blob[] = [];

    mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `motioncraft-${Date.now()}.webm`;
        a.click();
        URL.revokeObjectURL(url);
        setIsRecording(false);
        setIsPlaying(true); // Resume preview
    };

    mediaRecorder.start();

    // Render loop specifically for recording
    const fps = 60;
    const framesToRender = totalDuration * fps;
    const preset = getActivePreset();

    if (!preset) {
        setIsRecording(false);
        return;
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = parseFloat(canvas.style.width);
    const height = parseFloat(canvas.style.height);

    const recordLoop = async () => {
        for (let i = 0; i <= framesToRender; i++) {
            const t = i / framesToRender;
            renderFrame(
                ctx, 
                imageElement, 
                t, 
                preset, 
                width, 
                height, 
                config.travelTime, 
                config.delayTime, 
                totalDuration
            );
            await new Promise(r => setTimeout(r, 1000/fps));
        }
        mediaRecorder.stop();
    };

    recordLoop();
  };

  // UI Render
  return (
    <div className="flex h-screen w-full bg-[#0f0f11] overflow-hidden text-gray-100 font-sans">

      {/* 1. Left Sidebar: Header & Image */}
      <aside className="w-80 flex flex-col border-r border-[#27272a] bg-[#131316]">
        <div className="p-6 border-b border-[#27272a]">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Film className="text-white w-5 h-5" />
            </div>
            <h1 className="font-bold text-xl tracking-tight">MotionCraft</h1>
          </div>
          <p className="text-xs text-gray-500">Professional Camera Motion</p>
        </div>

        <div className="flex-1 p-6 overflow-y-auto">
          <div className="space-y-4">
             <label className="block">
               <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3 block">Source Asset</span>
               {!selectedImage ? (
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className="h-48 w-full border-2 border-dashed border-[#27272a] rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-[#18181b] transition-all group"
                 >
                   <div className="w-12 h-12 rounded-full bg-[#18181b] flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                     <Upload className="w-6 h-6 text-gray-400 group-hover:text-indigo-400" />
                   </div>
                   <span className="text-sm text-gray-400 font-medium">Click to upload</span>
                   <span className="text-xs text-gray-600 mt-1">High-res recommended</span>
                 </div>
               ) : (
                 <div className="relative group rounded-xl overflow-hidden border border-[#27272a] bg-black">
                    <img src={selectedImage} alt="Input" className="w-full h-48 object-contain" />
                    <button 
                      onClick={clearImage}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 backdrop-blur-md rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500/80"
                    >
                      <X size={16} />
                    </button>
                    <div className="absolute bottom-2 right-2 px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] text-gray-300">
                        {imageElement ? `${imageElement.naturalWidth} x ${imageElement.naturalHeight}` : 'Loading...'}
                    </div>
                 </div>
               )}
               <input 
                 type="file" 
                 ref={fileInputRef} 
                 className="hidden" 
                 accept="image/*" 
                 onChange={handleImageUpload} 
               />
             </label>

             <div className="mt-8">
                <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Motion Style</h3>
                <div className="grid grid-cols-1 gap-2">
                {MOTION_PRESETS.map((preset) => (
                    <MotionCard 
                    key={preset.id}
                    preset={preset}
                    isSelected={config.presetId === preset.id}
                    onClick={() => handlePresetSelect(preset.id)}
                    />
                ))}
                </div>
            </div>
          </div>
        </div>
      </aside>

      {/* 2. Main Area: Canvas Preview */}
      <main className="flex-1 flex flex-col bg-[#09090b] relative">
        {/* Toolbar */}
        <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-2 bg-[#18181b]/80 backdrop-blur-md border border-[#27272a] p-1.5 rounded-full shadow-2xl">
            <button 
                onClick={() => setIsPlaying(!isPlaying)}
                className="w-10 h-10 flex items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 transition-colors"
                disabled={!selectedImage || isRecording}
            >
                {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
            </button>
            <div className="w-px h-6 bg-white/10 mx-1"></div>
            <div className="px-3 flex flex-col">
                <span className="text-[10px] text-gray-400 font-medium">TOTAL TIME</span>
                <span className="text-xs text-white font-mono">
                    {totalDuration.toFixed(1)}s
                </span>
            </div>
        </div>

        {/* Instructions / Toasts */}
        {selectedImage && isMultiPointMode && (
             <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center gap-2 animate-in fade-in slide-in-from-bottom-4 w-full max-w-sm pointer-events-none">

                 <div className="pointer-events-auto flex items-center gap-3 bg-indigo-600/90 text-white px-4 py-2 rounded-full shadow-lg backdrop-blur">
                    {config.presetId === 'custom-focus' ? <MousePointerClick size={16} /> : config.presetId === 'cinematic-tour' ? <Map size={16} /> : <Route size={16} />}
                    <span className="text-xs font-medium min-w-[80px] text-center">
                        {pathPoints.length === 0 ? "Click to add" : `${pathPoints.length} points`}
                    </span>

                    <div className="w-px h-4 bg-white/20 mx-1"></div>

                    <div className="flex items-center gap-1">
                        <button 
                        onClick={undoPathPoint}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Undo Last Point"
                        >
                            <Undo2 size={14} />
                        </button>
                        <button 
                        onClick={clearPath}
                        disabled={pathPoints.length === 0}
                        className="p-1 hover:bg-white/20 rounded-md transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Clear Path"
                        >
                            <Trash2 size={14} />
                        </button>
                    </div>
                 </div>

                 {pathPoints.length > 2 && (
                     <button 
                        onClick={toggleLoop}
                        className={`pointer-events-auto flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-medium transition-all shadow-md backdrop-blur ${isPathLooping ? 'bg-green-500 text-white' : 'bg-[#18181b]/80 border border-[#27272a] text-gray-400 hover:text-white'}`}
                     >
                         <Repeat size={12} />
                         {isPathLooping ? 'Loop Active' : 'Loop Path'}
                     </button>
                 )}
             </div>
        )}

        <div className="flex-1 flex items-center justify-center p-8 overflow-hidden relative">

          {selectedImage ? (
             <div className="relative shadow-2xl shadow-black/50 border border-[#27272a] rounded-sm overflow-hidden bg-black group">
                <canvas 
                    ref={canvasRef}
                    onClick={handleCanvasClick}
                    className={`block ${isMultiPointMode ? 'cursor-crosshair' : 'cursor-default'}`}
                />
                {isRecording && (
                    <div className="absolute inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center flex-col gap-3 z-30">
                        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-white font-medium tracking-wide">Rendering Video...</span>
                    </div>
                )}
             </div>
          ) : (
            <div className="text-center opacity-60">
              <div className="w-24 h-24 bg-[#18181b] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#27272a] shadow-inner">
                <ImageIcon className="text-gray-600 w-10 h-10" />
              </div>
              <h2 className="text-2xl font-light text-gray-300 mb-2">Motion Studio</h2>
              <p className="text-gray-500 max-w-sm mx-auto">Upload an image to start designing cinematic motion effects.</p>
            </div>
          )}
        </div>
      </main>

      {/* 3. Right Sidebar: Fine Tuning */}
      <aside className="w-80 bg-[#131316] border-l border-[#27272a] flex flex-col">
        <div className="p-6 border-b border-[#27272a]">
          <h2 className="font-semibold text-gray-200 flex items-center gap-2">
            <Settings2 size={18} />
            {isMultiPointMode ? "Timing Controls" : "Configuration"}
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">

          {isMultiPointMode ? (
            <>
              {/* Travel Time Control */}
              <section>
                 <div className="flex items-center justify-between mb-3">
                    <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                       <Timer size={14} /> 
                       Time between Points
                    </h3>
                    <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                        {config.travelTime}s
                    </span>
                 </div>
                 <input 
                    type="range" 
                    min="0.5" 
                    max="5" 
                    step="0.5" 
                    value={config.travelTime}
                    onChange={(e) => setConfig(prev => ({ ...prev, travelTime: parseFloat(e.target.value) }))}
                    className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                 />
                 <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                    <span>Fast (0.5s)</span>
                    <span>Slow (5s)</span>
                 </div>
              </section>

              {/* Delay Time Control */}
              <section className="animate-in fade-in slide-in-from-right-4">
                     <div className="flex items-center justify-between mb-3">
                        <h3 className="text-sm font-medium text-gray-400 flex items-center gap-2">
                            <Clock size={14} /> 
                            Wait at Focus Point
                        </h3>
                        <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                            {config.delayTime}s
                        </span>
                     </div>
                     <input 
                        type="range" 
                        min="0" 
                        max="3" 
                        step="0.1" 
                        value={config.delayTime}
                        onChange={(e) => setConfig(prev => ({ ...prev, delayTime: parseFloat(e.target.value) }))}
                        className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                     />
                     <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                        <span>No Stop</span>
                        <span>Long Pause (3s)</span>
                     </div>
              </section>
            </>
          ) : (
            /* Duration Control for Standard Presets */
            <section>
                 <div className="flex items-center justify-between mb-3">
                    <h3 className="text-sm font-medium text-gray-400">Duration</h3>
                    <span className="text-xs font-mono text-indigo-400 bg-indigo-400/10 px-2 py-0.5 rounded">
                        {config.duration}s
                    </span>
                 </div>
                 <input 
                    type="range" 
                    min="2" 
                    max="10" 
                    step="0.5" 
                    value={config.duration}
                    onChange={(e) => setConfig(prev => ({ ...prev, duration: parseFloat(e.target.value) }))}
                    className="w-full accent-indigo-500 h-1.5 bg-[#27272a] rounded-lg appearance-none cursor-pointer"
                 />
                 <div className="flex justify-between mt-2 text-[10px] text-gray-600">
                    <span>Fast (2s)</span>
                    <span>Slow (10s)</span>
                 </div>
            </section>
          )}

          <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
             <div className="flex items-start gap-3">
                <Info className="w-4 h-4 text-indigo-400 mt-0.5 shrink-0" />
                <p className="text-[11px] text-gray-400 leading-relaxed">
                    {isMultiPointMode 
                     ? "Total video length is calculated automatically: (Points × Wait) + (Moves × Travel)"
                     : "This tool renders motion client-side. The export quality depends on your screen resolution."}
                </p>
             </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-[#27272a] bg-[#131316]">
            <Button 
              variant="primary" 
              className="w-full py-4 text-base bg-white text-black hover:bg-gray-200 border-0 shadow-lg shadow-white/5"
              onClick={handleExport}
              isLoading={isRecording}
              disabled={!selectedImage}
              icon={<Download size={18} />}
            >
              {isRecording ? 'Rendering...' : 'Export MP4'}
            </Button>
        </div>
      </aside>

    </div>
  );
};

export default App;

export type AnimationCategory = 'professional' | 'cinematic' | 'scifi';

export interface AnimationStyle {
  id: string;
  label: string;
  icon: string; // Lucide icon name
  category: AnimationCategory;
  description: string;
}

export interface Layer {
  id: string;
  x: number; // Normalized 0-1
  y: number; // Normalized 0-1
  w: number; // Normalized 0-1
  h: number; // Normalized 0-1
  type: string; // AnimationStyle id
  color: string;
  speed: number; // 0.1 to 3.0
  intensity: number; // 0.0 to 1.0
  delay: number; // Seconds
  label?: string; // For UI identification
}

export interface GlobalConfig {
  duration: number;
  bgDimming: number; // 0 to 1
  vignette: number; // 0 to 1
}

export interface RenderState {
  image: HTMLImageElement;
  layers: Layer[];
  config: GlobalConfig;
  canvasWidth: number;
  canvasHeight: number;
  time: number;
}

import { Layer, GlobalConfig } from '../types';

// Helper for easing
const easeInOutQuad = (t: number) => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;

// Helper to draw rough hand-drawn lines
const drawRoughLine = (ctx: CanvasRenderingContext2D, x1: number, y1: number, x2: number, y2: number, offset: number) => {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    // Simple wobble
    const midX = (x1 + x2) / 2 + (Math.sin(offset) * 2);
    const midY = (y1 + y2) / 2 + (Math.cos(offset) * 2);
    ctx.quadraticCurveTo(midX, midY, x2, y2);
    ctx.stroke();
};

export const renderFrame = (
    ctx: CanvasRenderingContext2D,
    image: HTMLImageElement,
    layers: Layer[],
    config: GlobalConfig,
    canvasWidth: number,
    canvasHeight: number,
    time: number // Current playback time in seconds
) => {
    // 1. Draw Background Image (Contain Mode Logic)
    ctx.fillStyle = '#09090b';
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);

    const imgRatio = image.naturalWidth / image.naturalHeight;
    const canvasRatio = canvasWidth / canvasHeight;

    let drawW, drawH, drawX, drawY;

    if (imgRatio > canvasRatio) {
        drawW = canvasWidth;
        drawH = canvasWidth / imgRatio;
        drawX = 0;
        drawY = (canvasHeight - drawH) / 2;
    } else {
        drawH = canvasHeight;
        drawW = canvasHeight * imgRatio;
        drawY = 0;
        drawX = (canvasWidth - drawW) / 2;
    }

    ctx.drawImage(image, drawX, drawY, drawW, drawH);

    // 2. Global Dimming
    // We apply this first so "Spotlight" layers can draw ON TOP of it to pop out
    if (config.bgDimming > 0) {
        ctx.fillStyle = `rgba(0, 0, 0, ${config.bgDimming * 0.8})`; // Max 80% dim
        ctx.fillRect(0, 0, canvasWidth, canvasHeight);
    }

    // 3. Render Layers
    layers.forEach(layer => {
        // Calculate Layer Position in Canvas Pixels
        const lx = drawX + (layer.x * drawW);
        const ly = drawY + (layer.y * drawH);
        const lw = layer.w * drawW;
        const lh = layer.h * drawH;

        // Skip if invalid
        if (lw <= 0 || lh <= 0) return;

        // Local animation time
        const loopDuration = config.duration; 
        const activeTime = Math.max(0, time - layer.delay);
        const progress = (activeTime % loopDuration) / loopDuration; // 0 to 1

        // Speed multiplier adjustment (affects frequency of effects)
        const speed = layer.speed || 1;
        const tick = activeTime * speed; 

        // Apply Spotlight/Magnify "Pop" logic first (Draws clean image over dimming)
        if (layer.type === 'spotlight' || layer.type === 'magnify') {
            ctx.save();
            ctx.beginPath();
            ctx.rect(lx, ly, lw, lh);
            ctx.clip();

            // Draw clean image content again inside this rect
            // Magnify scales it slightly
            if (layer.type === 'magnify') {
                const scale = 1.0 + (0.1 * layer.intensity); // Up to 10% zoom
                const cx = lx + lw/2;
                const cy = ly + lh/2;
                ctx.translate(cx, cy);
                ctx.scale(scale, scale);
                ctx.translate(-cx, -cy);
            }

            ctx.drawImage(image, drawX, drawY, drawW, drawH);
            ctx.restore();
        }

        // --- Render Specific Effects ---
        ctx.save();
        ctx.strokeStyle = layer.color;
        ctx.fillStyle = layer.color;
        ctx.lineWidth = 2 + (4 * layer.intensity); // Base 2px, up to 6px
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (layer.type) {
            case 'reading': {
                // Progressive fill rect (Marker style)
                // We simulate "lines" by just filling the box height progressively
                const fillWidth = easeInOutQuad((progress * 1.5) % 1) * lw; // 1.5x to allow pause at end
                ctx.globalAlpha = 0.4 * layer.intensity;
                ctx.fillRect(lx, ly, Math.min(lw, fillWidth), lh);
                break;
            }
            case 'marker': {
                // Static highlighter
                ctx.globalAlpha = 0.5 * layer.intensity;
                ctx.globalCompositeOperation = 'multiply'; // Blend nicely
                ctx.fillRect(lx, ly, lw, lh);
                break;
            }
            case 'underline': {
                const drawProg = Math.min(1, progress * 1.5);
                ctx.beginPath();
                ctx.moveTo(lx, ly + lh);
                ctx.lineTo(lx + (lw * drawProg), ly + lh);
                ctx.stroke();
                break;
            }
            case 'strike': {
                const drawProg = Math.min(1, progress * 1.5);
                ctx.beginPath();
                ctx.moveTo(lx, ly + lh/2);
                ctx.lineTo(lx + (lw * drawProg), ly + lh/2);
                ctx.stroke();
                break;
            }
            case 'box': {
                // Rough box
                const drawProg = Math.min(1, progress * 1.2);
                const perimeter = 2*lw + 2*lh;
                const currentLen = perimeter * drawProg;

                ctx.setLineDash([perimeter, perimeter]);
                ctx.lineDashOffset = perimeter - currentLen;
                ctx.strokeRect(lx, ly, lw, lh);
                break;
            }
            case 'circle': {
                // Rough circle/ellipse
                ctx.beginPath();
                const cx = lx + lw/2;
                const cy = ly + lh/2;
                const rx = lw/2 * 1.2;
                const ry = lh/2 * 1.4;
                ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2 * Math.min(1, progress * 1.5));
                ctx.stroke();
                break;
            }
            case 'brackets': {
                const len = Math.min(lw, lh) * 0.3;
                // Top Left
                ctx.beginPath();
                ctx.moveTo(lx + len, ly);
                ctx.lineTo(lx, ly);
                ctx.lineTo(lx, ly + len);
                ctx.stroke();
                // Bottom Right
                ctx.beginPath();
                ctx.moveTo(lx + lw - len, ly + lh);
                ctx.lineTo(lx + lw, ly + lh);
                ctx.lineTo(lx + lw, ly + lh - len);
                ctx.stroke();
                break;
            }
            case 'squiggle': {
                // Wavy line at bottom
                const freq = 0.2;
                const amp = 3 * layer.intensity;
                ctx.beginPath();
                ctx.moveTo(lx, ly + lh + 5);
                for (let i=0; i <= lw; i+=2) {
                    ctx.lineTo(lx + i, ly + lh + 5 + Math.sin((i + tick*50) * freq) * amp);
                }
                ctx.stroke();
                break;
            }
            case 'wiggle': {
                // Wiggling rect
                const wobble = () => (Math.random() - 0.5) * 4 * layer.intensity;
                ctx.beginPath();
                ctx.moveTo(lx + wobble(), ly + wobble());
                ctx.lineTo(lx + lw + wobble(), ly + wobble());
                ctx.lineTo(lx + lw + wobble(), ly + lh + wobble());
                ctx.lineTo(lx + wobble(), ly + lh + wobble());
                ctx.closePath();
                ctx.stroke();
                break;
            }
            case 'sweep': {
                // Shine gradient moving across
                ctx.save();
                ctx.beginPath();
                ctx.rect(lx, ly, lw, lh);
                ctx.clip();
                const grad = ctx.createLinearGradient(lx, ly, lx + lw, ly);
                const p = (tick % 2) / 2; // 2 sec loop usually
                const start = (p * 2) - 0.5; // -0.5 to 1.5
                grad.addColorStop(Math.max(0, start), 'rgba(255,255,255,0)');
                grad.addColorStop(Math.max(0, Math.min(1, start + 0.1)), 'rgba(255,255,255,0.4)');
                grad.addColorStop(Math.max(0, Math.min(1, start + 0.2)), 'rgba(255,255,255,0)');
                ctx.fillStyle = grad;
                ctx.fillRect(lx, ly, lw, lh);
                ctx.restore();
                break;
            }
            case 'blur': {
                // We simulated render above, but if not spotlight/magnify, we might want to blur just this region
                // Canvas blur is expensive. We can simulate blocky redaction or simple overlay.
                // Let's do a "pixelate" or "dark blur" overlay.
                ctx.fillStyle = layer.color;
                ctx.globalAlpha = 0.9;
                ctx.filter = `blur(${5 * layer.intensity}px)`;
                ctx.fillRect(lx, ly, lw, lh);
                ctx.filter = 'none';
                break;
            }
            case 'neon': {
                ctx.shadowBlur = 10 + (10 * Math.sin(tick * 5));
                ctx.shadowColor = layer.color;
                ctx.strokeRect(lx, ly, lw, lh);
                break;
            }
            case 'scanner': {
                const scanY = ly + (activeTime % 1.5 / 1.5) * lh;
                ctx.beginPath();
                ctx.moveTo(lx, scanY);
                ctx.lineTo(lx + lw, scanY);
                ctx.shadowBlur = 10;
                ctx.shadowColor = layer.color;
                ctx.stroke();

                // Trail
                const grad = ctx.createLinearGradient(lx, scanY, lx, scanY - (lh*0.2));
                grad.addColorStop(0, layer.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = 0.3;
                ctx.fillRect(lx, scanY - (lh*0.2), lw, lh*0.2);
                break;
            }
            case 'target': {
                // Crosshairs
                const cx = lx + lw/2;
                const cy = ly + lh/2;
                // Rotating outer ring
                ctx.beginPath();
                ctx.arc(cx, cy, Math.min(lw, lh)/2, tick, tick + Math.PI*1.5);
                ctx.stroke();
                // Inner cross
                ctx.beginPath();
                const size = 10;
                ctx.moveTo(cx - size, cy); ctx.lineTo(cx + size, cy);
                ctx.moveTo(cx, cy - size); ctx.lineTo(cx, cy + size);
                ctx.stroke();
                break;
            }
            case 'glitch': {
                // Random rects offset
                if (Math.random() > 0.8) {
                    const sliceH = Math.random() * lh * 0.2;
                    const sliceY = ly + Math.random() * (lh - sliceH);
                    const offsetX = (Math.random() - 0.5) * 20 * layer.intensity;

                    ctx.save();
                    ctx.beginPath();
                    ctx.rect(lx, sliceY, lw, sliceH);
                    ctx.clip();
                    ctx.drawImage(image, drawX + offsetX, drawY, drawW, drawH);

                    // Chromatic aberration hint
                    ctx.globalCompositeOperation = 'screen';
                    ctx.fillStyle = 'rgba(255,0,0,0.3)';
                    ctx.fillRect(lx + offsetX, sliceY, lw, sliceH);
                    ctx.restore();
                }
                break;
            }
            case 'pulse': {
                const alpha = 0.2 + (Math.sin(tick * 3) + 1) / 2 * 0.3;
                ctx.globalAlpha = alpha;
                ctx.fillStyle = layer.color;
                ctx.fillRect(lx, ly, lw, lh);
                ctx.globalAlpha = 1;
                ctx.strokeRect(lx, ly, lw, lh);
                break;
            }
            case 'ripple': {
                const maxR = Math.max(lw, lh) * 0.8;
                const r = (tick % 1) * maxR;
                const alpha = 1 - (tick % 1);

                ctx.globalAlpha = alpha;
                ctx.beginPath();
                ctx.arc(lx + lw/2, ly + lh/2, r, 0, Math.PI*2);
                ctx.stroke();
                break;
            }
            case 'rainbow': {
                const hue = (tick * 100) % 360;
                ctx.strokeStyle = `hsl(${hue}, 100%, 50%)`;
                ctx.strokeRect(lx, ly, lw, lh);
                break;
            }
            default:
                // Default box
                ctx.strokeRect(lx, ly, lw, lh);
        }

        ctx.restore();
    });

    // 4. Global Vignette
    if (config.vignette > 0) {
        const grad = ctx.createRadialGradient(
            canvasWidth/2, canvasHeight/2, Math.max(canvasWidth, canvasHeight) * 0.4,
            canvasWidth/2, canvasHeight/2, Math.max(canvasWidth, canvasHeight) * 0.8
        );
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(1, `rgba(0,0,0,${config.vignette})`);
        ctx.fillStyle = grad;
        ctx.fillRect(0,0, canvasWidth, canvasHeight);
    }
}

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { 
  Upload, Download, Play, Pause, Square, Trash2, Layers, 
  Settings, Image as ImageIcon, Plus, Video, Copy, 
  MousePointer2, Move, MonitorPlay
} from 'lucide-react';
import { Button } from './components/Button';
import { ANIMATION_STYLES, DEFAULT_COLORS } from './constants';
import { Layer, GlobalConfig } from './types';
import { renderFrame } from './services/motionService';
import * as Icons from 'lucide-react';

const App: React.FC = () => {
  // --- STATE ---
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageElement, setImageElement] = useState<HTMLImageElement | null>(null);
  const [layers, setLayers] = useState<Layer[]>([]);
  const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [currentTime, setCurrentTime] = useState<number>(0);

  const [config, setConfig] = useState<GlobalConfig>({
    duration: 3.0,
    bgDimming: 0.3,
    vignette: 0.2,
  });

  // Interaction State
  const [interactionMode, setInteractionMode] = useState<'draw' | 'select'>('draw');
  const [isDragging, setIsDragging] = useState<boolean>(false);
  const [dragStart, setDragStart] = useState<{x: number, y: number} | null>(null);
  const [activeDragLayer, setActiveDragLayer] = useState<string | null>(null);
  const [dragHandle, setDragHandle] = useState<'nw'|'ne'|'sw'|'se'|'move' | null>(null);

  // Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const requestRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);
  const lastFrameTimeRef = useRef<number>(0);

  // --- HELPERS ---
  const generateId = () => Math.random().toString(36).substr(2, 9);

  // Load Image
  useEffect(() => {
    if (selectedImage) {
      const img = new Image();
      img.src = selectedImage;
      img.onload = () => {
        setImageElement(img);
        setLayers([]); // Reset layers on new image
        setConfig(prev => ({ ...prev, duration: 3.0 }));
      };
    }
  }, [selectedImage]);

  // Main Render Loop
  const animate = useCallback((time: number) => {
    if (!startTimeRef.current) startTimeRef.current = time;
    const deltaTime = (time - lastFrameTimeRef.current) / 1000;
    lastFrameTimeRef.current = time;

    // Time Management
    if (isPlaying) {
      setCurrentTime(prev => (prev + deltaTime) % config.duration);
    }

    if (canvasRef.current && imageElement) {
        const ctx = canvasRef.current.getContext('2d');
        if (ctx) {
            // Sizing
            const container = containerRef.current;
            const w = container?.clientWidth || 800;
            const h = container?.clientHeight || 600;
            const dpr = window.devicePixelRatio || 1;

            // Only resize if needed (perf)
            if (canvasRef.current.width !== w * dpr || canvasRef.current.height !== h * dpr) {
                canvasRef.current.width = w * dpr;
                canvasRef.current.height = h * dpr;
                canvasRef.current.style.width = `${w}px`;
                canvasRef.current.style.height = `${h}px`;
                ctx.scale(dpr, dpr);
            }

            // --- RENDER ENGINE ---
            renderFrame(
                ctx,
                imageElement,
                layers,
                config,
                w,
                h,
                isPlaying ? currentTime : currentTime // Pass state time
            );

            // --- UI OVERLAYS (Handles) ---
            // Only draw if not recording
            if (!isRecording && selectedLayerId) {
                const activeLayer = layers.find(l => l.id === selectedLayerId);
                if (activeLayer) {
                     // Need to calculate screen coordinates same as renderFrame
                     // This is duplicate logic, ideally refactored, but kept inline for now
                     const imgRatio = imageElement.naturalWidth / imageElement.naturalHeight;
                     const canvasRatio = w / h;
                     let dw, dh, dx, dy;
                     if (imgRatio > canvasRatio) {
                         dw = w; dh = w / imgRatio; dx = 0; dy = (h - dh) / 2;
                     } else {
                         dh = h; dw = h * imgRatio; dy = 0; dx = (w - dw) / 2;
                     }

                     const lx = dx + (activeLayer.x * dw);
                     const ly = dy + (activeLayer.y * dh);
                     const lw = activeLayer.w * dw;
                     const lh = activeLayer.h * dh;

                     // Draw Border
                     ctx.strokeStyle = '#3b82f6';
                     ctx.lineWidth = 2;
                     ctx.setLineDash([4, 4]);
                     ctx.strokeRect(lx, ly, lw, lh);
                     ctx.setLineDash([]);

                     // Draw Handles
                     ctx.fillStyle = '#3b82f6';
                     const handleSize = 8;
                     const drawHandle = (hx: number, hy: number) => ctx.fillRect(hx - handleSize/2, hy - handleSize/2, handleSize, handleSize);
                     drawHandle(lx, ly); // NW
                     drawHandle(lx + lw, ly); // NE
                     drawHandle(lx, ly + lh); // SW
                     drawHandle(lx + lw, ly + lh); // SE
                }
            }
        }
    }

    requestRef.current = requestAnimationFrame(animate);
  }, [imageElement, layers, config, isPlaying, currentTime, isRecording, selectedLayerId]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  // --- HANDLERS ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setSelectedImage(ev.target?.result as string);
      reader.readAsDataURL(file);
    }
  };

  const addLayer = (rect: {x:number, y:number, w:number, h:number}) => {
    const newLayer: Layer = {
        id: generateId(),
        x: rect.x, y: rect.y, w: rect.w, h: rect.h,
        type: 'box',
        color: '#ef4444',
        speed: 1.0,
        intensity: 0.5,
        delay: 0,
        label: `Layer ${layers.length + 1}`
    };
    setLayers([...layers, newLayer]);
    setSelectedLayerId(newLayer.id);
  };

  // Canvas Interaction Logic
  const getNormCoords = (e: React.MouseEvent) => {
      if (!canvasRef.current || !imageElement) return null;
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const w = rect.width;
      const h = rect.height;

      // Inverse projection to get normalized image coords (0-1)
      const imgRatio = imageElement.naturalWidth / imageElement.naturalHeight;
      const canvasRatio = w / h;
      let dw, dh, dx, dy;
      if (imgRatio > canvasRatio) {
           dw = w; dh = w / imgRatio; dx = 0; dy = (h - dh) / 2;
      } else {
           dh = h; dw = h * imgRatio; dy = 0; dx = (w - dw) / 2;
      }

      // Check boundaries
      if (x < dx || x > dx + dw || y < dy || y > dy + dh) return null;

      return {
          x: (x - dx) / dw,
          y: (y - dy) / dh
      };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!imageElement) return;
    const coords = getNormCoords(e);
    if (!coords) return;

    // Check hit test for existing layers (Select/Resize)
    // Simple hit test: reverse loop to find top-most
    let hitLayer = null;
    let handle = null;

    // Tolerance for handles (in normalized coords, roughly 10px)
    // We need canvas dims to know 10px
    const rect = canvasRef.current!.getBoundingClientRect();
    const tolX = 15 / rect.width;
    const tolY = 15 / rect.height;

    for (let i = layers.length - 1; i >= 0; i--) {
        const l = layers[i];
        if (selectedLayerId === l.id) {
            // Check handles first
            if (Math.abs(coords.x - l.x) < tolX && Math.abs(coords.y - l.y) < tolY) { handle = 'nw'; hitLayer = l; break; }
            if (Math.abs(coords.x - (l.x + l.w)) < tolX && Math.abs(coords.y - (l.y + l.h)) < tolY) { handle = 'se'; hitLayer = l; break; }
        }

        if (coords.x >= l.x && coords.x <= l.x + l.w && coords.y >= l.y && coords.y <= l.y + l.h) {
            hitLayer = l;
            handle = 'move';
            break;
        }
    }

    if (hitLayer) {
        setSelectedLayerId(hitLayer.id);
        setActiveDragLayer(hitLayer.id);
        setDragHandle(handle as any);
        setDragStart(coords);
        setIsDragging(true);
        setInteractionMode('select');
    } else {
        // Start Drawing new box
        setSelectedLayerId(null);
        setDragStart(coords);
        setIsDragging(true);
        setInteractionMode('draw');
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
      if (!isDragging || !dragStart) return;
      const coords = getNormCoords(e);
      // Clamp to image bounds
      const cx = Math.max(0, Math.min(1, coords?.x || 0));
      const cy = Math.max(0, Math.min(1, coords?.y || 0));

      if (interactionMode === 'draw') {
          // Visual feedback for drawing (we could add a temp layer, but for now just wait for mouse up)
          // Actually, let's update a temp selection or just use a dedicated "ghost" layer if we want
          // To keep it simple, we'll just track dragStart and current to maybe draw a selection box?
          // Implemented via state "tempBox" would be better UX
      } else if (interactionMode === 'select' && activeDragLayer) {
          setLayers(prev => prev.map(l => {
              if (l.id !== activeDragLayer) return l;

              let nx = l.x, ny = l.y, nw = l.w, nh = l.h;
              const dx = cx - dragStart.x;
              const dy = cy - dragStart.y;

              if (dragHandle === 'move') {
                  nx += dx;
                  ny += dy;
              } else if (dragHandle === 'se') {
                  nw = Math.max(0.05, nw + dx);
                  nh = Math.max(0.05, nh + dy);
              } else if (dragHandle === 'nw') {
                  // Resizing from top-left is tricky with simple delta, 
                  // but effectively we shift x/y and reduce w/h
                  // Keep it simple: only support SE resize for this MVP or fix logic
                  // Implementing proper NW resize:
                  const newX = Math.min(l.x + l.w - 0.05, l.x + dx);
                  const newY = Math.min(l.y + l.h - 0.05, l.y + dy);
                  const newW = l.w + (l.x - newX);
                  const newH = l.h + (l.y - newY);
                  nx = newX; ny = newY; nw = newW; nh = newH;
              }

              return { ...l, x: nx, y: ny, w: nw, h: nh };
          }));
          setDragStart({ x: cx, y: cy }); // Reset delta
      }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
      if (!isDragging || !dragStart) return;
      setIsDragging(false);
      setActiveDragLayer(null);
      setDragHandle(null);

      const coords = getNormCoords(e);
      const cx = Math.max(0, Math.min(1, coords?.x || 0));
      const cy = Math.max(0, Math.min(1, coords?.y || 0));

      if (interactionMode === 'draw') {
          // Create layer
          const w = Math.abs(cx - dragStart.x);
          const h = Math.abs(cy - dragStart.y);
          const x = Math.min(cx, dragStart.x);
          const y = Math.min(cy, dragStart.y);

          if (w > 0.02 && h > 0.02) { // Min size
              addLayer({ x, y, w, h });
          }
      }
      setDragStart(null);
  };

  const updateSelectedLayer = (updates: Partial<Layer>) => {
      if (!selectedLayerId) return;
      setLayers(prev => prev.map(l => l.id === selectedLayerId ? { ...l, ...updates } : l));
  };

  const deleteSelectedLayer = () => {
      if (!selectedLayerId) return;
      setLayers(prev => prev.filter(l => l.id !== selectedLayerId));
      setSelectedLayerId(null);
  }

  const handleExport = () => {
      if (!canvasRef.current) return;
      setIsRecording(true);
      setIsPlaying(true);

      const stream = canvasRef.current.captureStream(60);
      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9', videoBitsPerSecond: 8000000 });
      const chunks: Blob[] = [];

      recorder.ondataavailable = e => { if (e.data.size > 0) chunks.push(e.data); };
      recorder.onstop = () => {
          const blob = new Blob(chunks, { type: 'video/webm' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = 'motioncraft-export.webm';
          a.click();
          setIsRecording(false);
      };

      recorder.start();
      // Record exactly one loop
      setCurrentTime(0);
      setTimeout(() => recorder.stop(), config.duration * 1000);
  };

  const getActiveLayer = () => layers.find(l => l.id === selectedLayerId);

  return (
    <div className="flex h-screen w-full bg-[#09090b] text-gray-200 font-sans overflow-hidden">

      {/* LEFT SIDEBAR: Layers & Global */}
      <aside className="w-64 bg-[#121214] border-r border-[#27272a] flex flex-col z-10">
          <div className="p-4 border-b border-[#27272a] flex items-center gap-2">
              <div className="w-8 h-8 bg-indigo-600 rounded-md flex items-center justify-center">
                  <MonitorPlay size={18} className="text-white"/>
              </div>
              <h1 className="font-bold text-lg tracking-tight">MotionCraft</h1>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-6">

              {/* Image Input */}
              <div className="space-y-2">
                  <p className="text-xs font-semibold text-gray-500 uppercase">Project Asset</p>
                  {!selectedImage ? (
                      <div onClick={() => fileInputRef.current?.click()} className="h-32 border border-dashed border-[#3f3f46] rounded-lg flex flex-col items-center justify-center hover:bg-[#27272a] cursor-pointer transition-colors">
                          <Upload size={20} className="mb-2 text-gray-400"/>
                          <span className="text-xs text-gray-400">Upload Image</span>
                      </div>
                  ) : (
                      <div className="relative group rounded-md overflow-hidden border border-[#3f3f46]">
                          <img src={selectedImage} className="h-32 w-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" alt="Source"/>
                          <button onClick={() => {setSelectedImage(null); setLayers([])}} className="absolute top-2 right-2 p-1 bg-black/50 rounded hover:bg-red-500/80 text-white"><Trash2 size={12}/></button>
                      </div>
                  )}
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
              </div>

              {/* Layers List */}
              {selectedImage && (
                  <div className="space-y-2">
                      <div className="flex items-center justify-between">
                          <p className="text-xs font-semibold text-gray-500 uppercase">Highlights ({layers.length})</p>
                      </div>

                      <div className="space-y-1">
                          {layers.length === 0 && (
                              <div className="text-xs text-gray-500 italic p-2 text-center border border-[#27272a] rounded-lg border-dashed">
                                  Drag on canvas to add highlights
                              </div>
                          )}
                          {layers.map((l, i) => (
                              <div 
                                key={l.id}
                                onClick={() => setSelectedLayerId(l.id)}
                                className={`flex items-center gap-2 px-3 py-2 rounded-md text-sm cursor-pointer transition-colors ${selectedLayerId === l.id ? 'bg-indigo-600/20 border border-indigo-500/50 text-white' : 'hover:bg-[#27272a] border border-transparent'}`}
                              >
                                  <div className="w-2 h-2 rounded-full" style={{backgroundColor: l.color}}></div>
                                  <span className="truncate flex-1">
                                      {ANIMATION_STYLES.find(s => s.id === l.type)?.label || 'Highlight'}
                                  </span>
                                  {selectedLayerId === l.id && (
                                      <button onClick={(e) => {e.stopPropagation(); deleteSelectedLayer()}} className="text-gray-400 hover:text-red-400">
                                          <Trash2 size={12} />
                                      </button>
                                  )}
                              </div>
                          ))}
                      </div>
                  </div>
              )}

              {/* Global Config */}
              <div className="space-y-4 pt-4 border-t border-[#27272a]">
                  <p className="text-xs font-semibold text-gray-500 uppercase">Global Scene</p>

                  <div className="space-y-1">
                      <div className="flex justify-between text-xs text-gray-400">
                          <span>Loop Duration</span>
                          <span>{config.duration}s</span>
                      </div>
                      <input 
                        type="range" min="1" max="10" step="0.5" 
                        value={config.duration}
                        onChange={e => setConfig({...config, duration: parseFloat(e.target.value)})}
                        className="w-full accent-indigo-500 h-1 bg-[#27272a] rounded-full appearance-none"
                      />
                  </div>

                  <div className="space-y-1">
                      <div className="flex justify-between text-xs text-gray-400">
                          <span>BG Dimming</span>
                          <span>{(config.bgDimming * 100).toFixed(0)}%</span>
                      </div>
                      <input 
                        type="range" min="0" max="0.9" step="0.1" 
                        value={config.bgDimming}
                        onChange={e => setConfig({...config, bgDimming: parseFloat(e.target.value)})}
