import { Layer, GlobalConfig } from '../types';

// Helper for easing
const easeInOutQuad = (t: number) => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;

// Centralized Layout Logic
export const getRenderLayout = (
    canvasW: number, 
    canvasH: number, 
    imgW: number, 
    imgH: number
) => {
    const imgRatio = imgW / imgH;
    const canvasRatio = canvasW / canvasH;

    let drawW, drawH, drawX, drawY;

    if (imgRatio > canvasRatio) {
        drawW = canvasW;
        drawH = canvasW / imgRatio;
        drawX = 0;
        drawY = (canvasH - drawH) / 2;
    } else {
        drawH = canvasH;
        drawW = canvasH * imgRatio;
        drawY = 0;
        drawX = (canvasW - drawW) / 2;
    }

    return { x: drawX, y: drawY, w: drawW, h: drawH };
};

export const renderFrame = (
    ctx: CanvasRenderingContext2D,
    image: HTMLImageElement,
    layers: Layer[],
    config: GlobalConfig,
    canvasWidth: number,
    canvasHeight: number,
    time: number // Current playback time in seconds
) => {
    // 1. Calculate Layout
    const layout = getRenderLayout(canvasWidth, canvasHeight, image.naturalWidth, image.naturalHeight);
    const { x: drawX, y: drawY, w: drawW, h: drawH } = layout;

    // 2. Draw Background
    ctx.fillStyle = '#09090b';
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);

    // Draw base image
    ctx.drawImage(image, drawX, drawY, drawW, drawH);

    // 3. Global Dimming / Vignette
    if (config.bgDimming > 0) {
        ctx.fillStyle = `rgba(0, 0, 0, ${config.bgDimming * 0.9})`; 
        ctx.fillRect(0, 0, canvasWidth, canvasHeight);
    }

    if (config.vignette > 0) {
        const grad = ctx.createRadialGradient(
            canvasWidth/2, canvasHeight/2, Math.max(canvasWidth, canvasHeight) * 0.4,
            canvasWidth/2, canvasHeight/2, Math.max(canvasWidth, canvasHeight) * 0.9
        );
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(1, `rgba(0,0,0,${config.vignette})`);
        ctx.fillStyle = grad;
        ctx.fillRect(0,0, canvasWidth, canvasHeight);
    }

    // 4. Render Layers
    layers.forEach(layer => {
        // Calculate Layer Position in Canvas Pixels
        const lx = drawX + (layer.x * drawW);
        const ly = drawY + (layer.y * drawH);
        const lw = layer.w * drawW;
        const lh = layer.h * drawH;

        // Skip if invalid
        if (lw <= 0 || lh <= 0) return;

        // Animation Timing
        const loopDuration = config.duration; 
        const activeTime = Math.max(0, time - layer.delay);
        const progress = (activeTime % loopDuration) / loopDuration; // 0 to 1

        // Effects usually loop faster than the total duration or strictly follow duration
        const tick = activeTime * (layer.speed || 1.0); 

        // --- PRE-RENDER: Spotlight/Magnify (Draw clean image over dimmed BG) ---
        if (layer.type === 'spotlight' || layer.type === 'magnify') {
            ctx.save();
            ctx.beginPath();
            ctx.rect(lx, ly, lw, lh);
            ctx.clip();

            // Draw clean image content again inside this rect
            if (layer.type === 'magnify') {
                const scale = 1.0 + (0.15 * layer.intensity); // Up to 15% zoom
                // We need to scale around the center of the highlight box
                const cx = lx + lw/2;
                const cy = ly + lh/2;

                ctx.translate(cx, cy);
                ctx.scale(scale, scale);
                ctx.translate(-cx, -cy);
            }

            ctx.drawImage(image, drawX, drawY, drawW, drawH);
            ctx.restore();
        }

        // --- RENDER STYLE OVERLAYS ---
        ctx.save();
        ctx.strokeStyle = layer.color;
        ctx.fillStyle = layer.color;
        ctx.lineWidth = Math.max(1, 2 + (3 * layer.intensity)); 
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (layer.type) {
            case 'reading': {
                // Karaoke style fill
                const fillWidth = Math.min(lw, easeInOutQuad((progress * 2) % 1.2) * lw); 
                ctx.globalAlpha = 0.3 * layer.intensity;
                ctx.fillRect(lx, ly, fillWidth, lh);
                // Bottom line
                ctx.globalAlpha = 1;
                ctx.beginPath();
                ctx.moveTo(lx, ly + lh);
                ctx.lineTo(lx + fillWidth, ly + lh);
                ctx.stroke();
                break;
            }
            case 'marker': {
                ctx.globalAlpha = 0.5 * layer.intensity;
                ctx.globalCompositeOperation = 'overlay'; 
                ctx.fillRect(lx, ly, lw, lh);
                break;
            }
            case 'underline': {
                // Animate line drawing
                const p = Math.min(1, (progress * 2)); // Draw in first half
                ctx.beginPath();
                ctx.moveTo(lx, ly + lh + 4);
                ctx.lineTo(lx + (lw * p), ly + lh + 4);
                ctx.stroke();
                break;
            }
            case 'strike': {
                const p = Math.min(1, (progress * 2));
                ctx.beginPath();
                ctx.moveTo(lx, ly + lh/2);
                ctx.lineTo(lx + (lw * p), ly + lh/2);
                ctx.stroke();
                break;
            }
            case 'box': {
                // Draw box border progressively
                const p = Math.min(1, progress * 1.5);
                const perimeter = 2*lw + 2*lh;
                const currentLen = perimeter * p;

                ctx.setLineDash([perimeter]);
                ctx.lineDashOffset = perimeter - currentLen;
                ctx.strokeRect(lx, ly, lw, lh);
                break;
            }
            case 'brackets': {
                const len = Math.min(lw, lh) * 0.25;
                // TL
                ctx.beginPath(); ctx.moveTo(lx + len, ly); ctx.lineTo(lx, ly); ctx.lineTo(lx, ly + len); ctx.stroke();
                // TR
                ctx.beginPath(); ctx.moveTo(lx + lw - len, ly); ctx.lineTo(lx + lw, ly); ctx.lineTo(lx + lw, ly + len); ctx.stroke();
                // BL
                ctx.beginPath(); ctx.moveTo(lx, ly + lh - len); ctx.lineTo(lx, ly + lh); ctx.lineTo(lx + len, ly + lh); ctx.stroke();
                // BR
                ctx.beginPath(); ctx.moveTo(lx + lw, ly + lh - len); ctx.lineTo(lx + lw, ly + lh); ctx.lineTo(lx + lw - len, ly + lh); ctx.stroke();
                break;
            }
            case 'circle': {
                 ctx.beginPath();
                 const cx = lx + lw/2;
                 const cy = ly + lh/2;
                 const rx = lw/2;
                 const ry = lh/2;
                 // Draw 95% of circle
                 ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2 * Math.min(1, progress * 1.2));
                 ctx.stroke();
                 break;
            }
            case 'wiggle': {
                 const offset = () => (Math.random() - 0.5) * 4 * layer.intensity;
                 ctx.beginPath();
                 ctx.moveTo(lx + offset(), ly + offset());
                 ctx.lineTo(lx + lw + offset(), ly + offset());
                 ctx.lineTo(lx + lw + offset(), ly + lh + offset());
                 ctx.lineTo(lx + offset(), ly + lh + offset());
                 ctx.closePath();
                 ctx.stroke();
                 break;
            }
            case 'neon': {
                 const glow = 10 + 5 * Math.sin(tick * 5);
                 ctx.shadowBlur = glow;
                 ctx.shadowColor = layer.color;
                 ctx.strokeRect(lx, ly, lw, lh);
                 // Double stroke for core
                 ctx.shadowBlur = 0;
                 ctx.lineWidth = 1;
                 ctx.strokeStyle = '#fff';
                 ctx.strokeRect(lx, ly, lw, lh);
                 break;
            }
            case 'scanner': {
                 const scanY = ly + ((activeTime * 0.5) % 1) * lh;
                 ctx.beginPath();
                 ctx.moveTo(lx, scanY);
                 ctx.lineTo(lx + lw, scanY);
                 ctx.shadowColor = layer.color;
                 ctx.shadowBlur = 10;
                 ctx.strokeStyle = layer.color;
                 ctx.stroke();
                 break;
            }
            case 'glitch': {
                 if (Math.random() > 0.92) {
                     const sliceY = ly + Math.random() * lh;
                     const sliceH = Math.random() * (lh/4);
                     const shift = (Math.random() - 0.5) * 20 * layer.intensity;
                     ctx.save();
                     ctx.beginPath(); ctx.rect(lx, sliceY, lw, sliceH); ctx.clip();
                     ctx.drawImage(image, drawX + shift, drawY, drawW, drawH);
                     ctx.fillStyle = `rgba(${Math.random()*255},0,0,0.3)`;
                     ctx.fillRect(lx, sliceY, lw, sliceH);
                     ctx.restore();
                 }
                 break;
            }
            case 'pulse': {
                 const alpha = 0.5 + 0.5 * Math.sin(tick * 3);
                 ctx.globalAlpha = alpha * 0.3;
                 ctx.fillRect(lx, ly, lw, lh);
                 ctx.globalAlpha = 1;
                 ctx.strokeRect(lx, ly, lw, lh);
                 break;
            }
            case 'invert': {
                ctx.save();
                ctx.beginPath(); ctx.rect(lx, ly, lw, lh); ctx.clip();
                ctx.filter = 'invert(1)';
                ctx.drawImage(image, drawX, drawY, drawW, drawH);
                ctx.restore();
                break;
            }
            case 'blur': {
                // Since canvas blur is heavy, we just fill with a pixelated or semi-opaque rect
                ctx.fillStyle = layer.color;
                ctx.globalAlpha = 0.95;
                // Draw a mosaic if possible, but simple rect is safer for perf
                ctx.fillRect(lx, ly, lw, lh);
                break;
            }
            default:
                ctx.strokeRect(lx, ly, lw, lh);
                break;
        }

        ctx.restore();
    });
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { 
  Upload, Pause, Play, Video, Trash2, 
  MonitorPlay, Square, MousePointer2, Layers, Image as ImageIcon
} from 'lucide-react';
import { Button } from './components/Button';
import { ANIMATION_STYLES, DEFAULT_COLORS } from './constants';
import { Layer, GlobalConfig } from './types';
import { renderFrame, getRenderLayout } from './services/motionService';
import * as Icons from 'lucide-react';

const App: React.FC = () => {
  // --- STATE ---
  // UI State (Trigger re-renders for sidebar/buttons)
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [layers, setLayers] = useState<Layer[]>([]);
  const [selectedLayerId, setSelectedLayerId] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [config, setConfig] = useState<GlobalConfig>({
    duration: 5.0,
    bgDimming: 0.3,
    vignette: 0.2,
  });

  // Tools & Interaction
  const [interactionMode, setInteractionMode] = useState<'draw' | 'select'>('draw');
  const [isDragging, setIsDragging] = useState<boolean>(false);
  const [tempBox, setTempBox] = useState<{x:number, y:number, w:number, h:number} | null>(null);

  // --- REFS (Source of Truth for Animation Loop) ---
  // We use refs to avoid stale closures in the requestAnimationFrame loop
  const layersRef = useRef(layers);
  const configRef = useRef(config);
  const imageElementRef = useRef<HTMLImageElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Animation Loop Refs
  const requestRef = useRef<number | null>(null);
  const timeRef = useRef<number>(0);
  const lastTimeRef = useRef<number>(performance.now());
  const isPlayingRef = useRef(isPlaying);

  // Dragging Refs (avoid re-renders during 60fps drag)
  const dragStartRef = useRef<{x:number, y:number} | null>(null); // Normalized coords
  const dragHandleRef = useRef<'nw'|'ne'|'sw'|'se'|'move' | null>(null);
  const activeLayerIdRef = useRef<string | null>(null); // Layer being dragged
  const initialLayerStateRef = useRef<Layer | null>(null); // Snapshot before drag

  // Sync State to Refs
  useEffect(() => { layersRef.current = layers; }, [layers]);
  useEffect(() => { configRef.current = config; }, [config]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);

  // Load Image
  const handleImageLoad = (url: string) => {
    const img = new Image();
    img.src = url;
    img.onload = () => {
        imageElementRef.current = img;
        setSelectedImage(url);
        setLayers([]);
        setConfig(prev => ({...prev, duration: 5.0}));
        setIsPlaying(true);
    };
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => handleImageLoad(ev.target?.result as string);
      reader.readAsDataURL(file);
    }
  };

  // --- ANIMATION LOOP ---
  const animate = useCallback((time: number) => {
    const deltaTime = (time - lastTimeRef.current) / 1000;
    lastTimeRef.current = time;

    // 1. Update Time
    if (isPlayingRef.current && configRef.current) {
        timeRef.current = (timeRef.current + deltaTime) % configRef.current.duration;
    }

    // 2. Render
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    const img = imageElementRef.current;

    if (canvas && ctx && img && containerRef.current) {
        // Handle Canvas Size (Responsive)
        const containerW = containerRef.current.clientWidth;
        const containerH = containerRef.current.clientHeight;
        const dpr = window.devicePixelRatio || 1;

        if (canvas.width !== containerW * dpr || canvas.height !== containerH * dpr) {
            canvas.width = containerW * dpr;
            canvas.height = containerH * dpr;
            canvas.style.width = `${containerW}px`;
            canvas.style.height = `${containerH}px`;
            ctx.scale(dpr, dpr);
        }

        // Render Game Loop
        renderFrame(
            ctx,
            img,
            layersRef.current,
            configRef.current,
            containerW,
            containerH,
            timeRef.current
        );

        // --- DRAW UI OVERLAYS (Handles & Ghosts) ---
        // Calculate Layout again to map normalized -> screen
        const layout = getRenderLayout(containerW, containerH, img.naturalWidth, img.naturalHeight);

        // Helper to project normalized -> screen
        const toScreen = (nx: number, ny: number) => ({
            x: layout.x + (nx * layout.w),
            y: layout.y + (ny * layout.h)
        });
        // Helper to scale dim -> screen
        const scaleDim = (nw: number, nh: number) => ({
            w: nw * layout.w,
            h: nh * layout.h
        });

        // Draw Temp Box (Drawing Mode)
        // Access state directly here works because this is a ref closure, wait... 
        // We need to access the LATEST tempBox. State inside callback is stale if not careful.
        // Actually, we should use a ref for tempBox if we want to render it here without dependency.
        // But let's just use the fact that setTempBox triggers re-render which triggers new animate closure?
        // NO, the animate loop is only created once. We need a ref for tempBox visualization.
        // HOWEVER, standard React rendering overlays on top of canvas is easier for UI?
        // No, let's draw on canvas for performance.

        // For this specific value (tempBox), let's cheat and look at a Ref we create just now
        // Or better, simply pass tempBox to a ref in the component body
    }

    requestRef.current = requestAnimationFrame(animate);
  }, []); // Empty dependency array = stable loop

  // We need a way to pass "TempBox" to the loop without re-creating loop.
  const tempBoxRef = useRef(tempBox);
  useEffect(() => { tempBoxRef.current = tempBox; }, [tempBox]);

  // Also need selected ID ref
  const selectedLayerIdRef = useRef(selectedLayerId);
  useEffect(() => { selectedLayerIdRef.current = selectedLayerId; }, [selectedLayerId]);

  // Extend Render Loop for UI
  const renderUI = useCallback(() => {
     const canvas = canvasRef.current;
     const ctx = canvas?.getContext('2d');
     const img = imageElementRef.current;

     if (canvas && ctx && img) {
         // This runs immediately after renderFrame in the loop
         const w = canvas.width / (window.devicePixelRatio||1);
         const h = canvas.height / (window.devicePixelRatio||1);
         const layout = getRenderLayout(w, h, img.naturalWidth, img.naturalHeight);

         // 1. Draw Selection Handles
         const selId = selectedLayerIdRef.current;
         if (selId) {
             const layer = layersRef.current.find(l => l.id === selId);
             if (layer) {
                 const lx = layout.x + (layer.x * layout.w);
                 const ly = layout.y + (layer.y * layout.h);
                 const lw = layer.w * layout.w;
                 const lh = layer.h * layout.h;

                 ctx.strokeStyle = '#3b82f6';
                 ctx.lineWidth = 1;
                 ctx.setLineDash([4, 4]);
                 ctx.strokeRect(lx, ly, lw, lh);
                 ctx.setLineDash([]);

                 // Handles
                 ctx.fillStyle = '#3b82f6';
                 const hs = 8; // handle size
                 const drawH = (x:number, y:number) => ctx.fillRect(x - hs/2, y - hs/2, hs, hs);

                 drawH(lx, ly); // NW
                 drawH(lx + lw, ly); // NE
                 drawH(lx, ly + lh); // SW
                 drawH(lx + lw, ly + lh); // SE
             }
         }

         // 2. Draw Temp Box (Ghost)
         const tb = tempBoxRef.current;
         if (tb) {
             const lx = layout.x + (tb.x * layout.w);
             const ly = layout.y + (tb.y * layout.h);
             const lw = tb.w * layout.w;
             const lh = tb.h * layout.h;

             ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
             ctx.lineWidth = 1;
             ctx.setLineDash([2, 2]);
             ctx.strokeRect(lx, ly, lw, lh);
             ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
             ctx.fillRect(lx, ly, lw, lh);
         }
     }
  }, []);

  // Update animate to call renderUI
  useEffect(() => {
     const loop = (time: number) => {
         animate(time);
         renderUI();
         requestRef.current = requestAnimationFrame(loop);
     };
     requestRef.current = requestAnimationFrame(loop);
     return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [animate, renderUI]);


  // --- INTERACTION HANDLERS ---
  const getNormCoords = (e: React.MouseEvent) => {
      if (!canvasRef.current || !imageElementRef.current) return null;
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const w = rect.width;
      const h = rect.height;

      const img = imageElementRef.current;
      const layout = getRenderLayout(w, h, img.naturalWidth, img.naturalHeight);

      // Check containment
      if (x < layout.x || x > layout.x + layout.w || y < layout.y || y > layout.y + layout.h) {
          // Allow slightly outside for handles, clamp strictly for drawing
          // For now, clamp to 0-1 relative to image
      }

      const nx = (x - layout.x) / layout.w;
      const ny = (y - layout.y) / layout.h;

      return { x: nx, y: ny };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (!imageElementRef.current) return;
      const coords = getNormCoords(e);
      if (!coords) return;

      // Clamp for interaction
      const cx = Math.max(0, Math.min(1, coords.x));
      const cy = Math.max(0, Math.min(1, coords.y));

      // HIT TESTING
      // Logic: Check selected layer handles first, then check all layers for body click
      let hitLayerId: string | null = null;
      let handle: any = null;

      // Handle Tolerance (normalized)
      // We need screen pixel tolerance convert to norm
      const pixelTol = 10;
      const canvas = canvasRef.current!;
      const layout = getRenderLayout(canvas.width/window.devicePixelRatio, canvas.height/window.devicePixelRatio, imageElementRef.current.naturalWidth, imageElementRef.current.naturalHeight);
      const tolX = pixelTol / layout.w;
      const tolY = pixelTol / layout.h;

      // 1. Check handles of currently selected layer
      if (selectedLayerId) {
          const l = layers.find(l => l.id === selectedLayerId);
          if (l) {
              const check = (tx: number, ty: number) => Math.abs(coords.x - tx) < tolX && Math.abs(coords.y - ty) < tolY;
              if (check(l.x, l.y)) handle = 'nw';
              else if (check(l.x + l.w, l.y)) handle = 'ne';
              else if (check(l.x, l.y + l.h)) handle = 'sw';
              else if (check(l.x + l.w, l.y + l.h)) handle = 'se';

              if (handle) hitLayerId = l.id;
          }
      }

      // 2. If no handle, check layer bodies (Top to Bottom visual order = reverse array)
      if (!handle) {
          for (let i = layers.length - 1; i >= 0; i--) {
              const l = layers[i];
              if (coords.x >= l.x && coords.x <= l.x + l.w && coords.y >= l.y && coords.y <= l.y + l.h) {
                  hitLayerId = l.id;
                  handle = 'move';
                  break;
              }
          }
      }

      if (hitLayerId && interactionMode === 'select') {
          // Start Drag
          setSelectedLayerId(hitLayerId);
          dragStartRef.current = { x: coords.x, y: coords.y }; // Use raw coords for delta
          dragHandleRef.current = handle;
          activeLayerIdRef.current = hitLayerId;
          const l = layers.find(x => x.id === hitLayerId);
          initialLayerStateRef.current = l ? {...l} : null;
          setIsDragging(true);
      } else {
          // Start Draw
          if (interactionMode === 'draw') {
              setSelectedLayerId(null);
              dragStartRef.current = { x: cx, y: cy }; // Clamp start
              setTempBox({ x: cx, y: cy, w: 0, h: 0 });
              setIsDragging(true);
          }
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
      if (!isDragging || !dragStartRef.current) return;
      const coords = getNormCoords(e);
      if (!coords) return; // Should handle out of bounds better but ok for now

      if (activeLayerIdRef.current && initialLayerStateRef.current) {
          // DRAGGING / RESIZING
          const start = dragStartRef.current;
          const init = initialLayerStateRef.current;
          const dx = coords.x - start.x;
          const dy = coords.y - start.y;
          const handle = dragHandleRef.current;

          let nx = init.x, ny = init.y, nw = init.w, nh = init.h;

          if (handle === 'move') {
              nx = init.x + dx;
              ny = init.y + dy;
          } else {
              // Resizing
              if (handle === 'se' || handle === 'ne') nw = init.w + dx;
              if (handle === 'sw' || handle === 'nw') { nx = init.x + dx; nw = init.w - dx; }

              if (handle === 'se' || handle === 'sw') nh = init.h + dy;
              if (handle === 'ne' || handle === 'nw') { ny = init.y + dy; nh = init.h - dy; }
          }

          // Normalize negative width/height (flipping)
          if (nw < 0) { nx += nw; nw = Math.abs(nw); }
          if (nh < 0) { ny += nh; nh = Math.abs(nh); }

          setLayers(prev => prev.map(l => l.id === activeLayerIdRef.current ? { ...l, x: nx, y: ny, w: nw, h: nh } : l));

      } else {
          // DRAWING
          const start = dragStartRef.current;
          const cx = Math.max(0, Math.min(1, coords.x));
          const cy = Math.max(0, Math.min(1, coords.y));

          const x = Math.min(start.x, cx);
          const y = Math.min(start.y, cy);
          const w = Math.abs(cx - start.x);
          const h = Math.abs(cy - start.y);

          setTempBox({ x, y, w, h });
      }
  };

  const handleMouseUp = () => {
      if (!isDragging) return;

      if (tempBox && !activeLayerIdRef.current) {
          // Finish Drawing
          if (tempBox.w > 0.01 && tempBox.h > 0.01) {
              const newLayer: Layer = {
                  id: Math.random().toString(36).substr(2, 9),
                  x: tempBox.x, y: tempBox.y, w: tempBox.w, h: tempBox.h,
                  type: 'box', color: '#ef4444', speed: 1, intensity: 0.5, delay: 0,
              };
              setLayers(prev => [...prev, newLayer]);
              setSelectedLayerId(newLayer.id);
              // Switch to select mode for ease of editing
              setInteractionMode('select');
          }
      }

      setIsDragging(false);
      setTempBox(null);
      activeLayerIdRef.current = null;
      initialLayerStateRef.current = null;
      dragStartRef.current = null;
  };

  const handleExport = () => {
      if (!canvasRef.current) return;
      setIsRecording(true);

      // Stop loop to control it manually
      const prevPlaying = isPlaying;
      setIsPlaying(false);

      const stream = canvasRef.current.captureStream(60);
      const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9', videoBitsPerSecond: 8000000 });
      const chunks: Blob[] = [];

      recorder.ondataavailable = e => { if (e.data.size > 0) chunks.push(e.data); };
      recorder.onstop = () => {
          const blob = new Blob(chunks, { type: 'video/webm' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `motion-export-${Date.now()}.webm`;
          a.click();

          setIsRecording(false);
          setIsPlaying(prevPlaying);
          timeRef.current = 0; // Reset
      };

      recorder.start();

      // Precise Rendering Loop for Export
      const duration = config.duration;
      const fps = 60;
      const totalFrames = duration * fps;
      let frame = 0;

      const renderExportFrame = () => {
          if (frame > totalFrames) {
              recorder.stop();
              return;
          }

          const t = (frame / fps); // exact time

          // Manually invoke renderFrame
          const canvas = canvasRef.current;
          const ctx = canvas?.getContext('2d');
          const img = imageElementRef.current;

          if (canvas && ctx && img) {
               // Ensure correct size just in case
               const layout = getRenderLayout(canvas.width/window.devicePixelRatio, canvas.height/window.devicePixelRatio, img.naturalWidth, img.naturalHeight);
               renderFrame(
                   ctx,
                   img,
                   layersRef.current,
                   configRef.current,
                   canvas.width/window.devicePixelRatio,
                   canvas.height/window.devicePixelRatio,
                   t
               );
          }

          frame++;
          requestAnimationFrame(renderExportFrame);
      };

      renderExportFrame();
  };

  const updateSelected = (u: Partial<Layer>) => {
      setLayers(prev => prev.map(l => l.id === selectedLayerId ? {...l, ...u} : l));
  };

  const activeLayer = layers.find(l => l.id === selectedLayerId);

  return (
    <div className="flex h-screen w-full bg-[#09090b] text-gray-200 font-sans overflow-hidden select-none">

      {/* LEFT SIDEBAR */}
      <aside className="w-64 bg-[#121214] border-r border-[#27272a] flex flex-col z-20">
          <div className="p-4 border-b border-[#27272a] flex items-center gap-2">
              <div className="w-8 h-8 bg-indigo-600 rounded-md flex items-center justify-center">
                  <MonitorPlay size={18} className="text-white"/>
              </div>
              <h1 className="font-bold text-lg tracking-tight">MotionCraft</h1>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-6">
              {/* ASSET */}
              <div>
                  <p className="text-xs font-semibold text-gray-500 uppercase mb-2">Source</p>
                  {!selectedImage ? (
                      <div onClick={() => document.getElementById('file-upload')?.click()} className="h-32 border border-dashed border-[#3f3f46] rounded-lg flex flex-col items-center justify-center hover:bg-[#27272a] cursor-pointer transition-colors">
                          <Upload size={20} className="mb-2 text-gray-400"/>
                          <span className="text-xs text-gray-400">Upload Image</span>
                      </div>
                  ) : (
                      <div className="relative group rounded-md overflow-hidden border border-[#3f3f46] bg-black">
                          <img src={selectedImage} className="h-32 w-full object-contain" alt="Source"/>
                          <button onClick={() => {setSelectedImage(null); setLayers([]);}} className="absolute top-2 right-2 p-1 bg-black/60 rounded hover:bg-red-500/80 text-white"><Trash2 size={12}/></button>
                      </div>
                  )}
                  <input id="file-upload" type="file" className="hidden" accept="image/*" onChange={handleFileUpload} />
              </div>

              {/* LAYERS */}
              {selectedImage && (
                  <div>
                      <div className="flex items-center justify-between mb-2">
                          <p className="text-xs font-semibold text-gray-500 uppercase">Layers</p>
                          <span className="text-xs text-gray-600">{layers.length}</span>
                      </div>
                      <div className="space-y-1 max-h-48 overflow-y-auto pr-1">
                          {layers.length === 0 && <div className="text-xs text-gray-500 italic p-2 border border-dashed border-[#27272a] rounded">Drag to create highlights</div>}
                          {layers.map((l, i) => (
                              <div 
                                key={l.id} 
                                onClick={() => setSelectedLayerId(l.id)}
                                className={`flex items-center gap-2 px-2 py-1.5 rounded text-sm cursor-pointer border ${selectedLayerId === l.id ? 'bg-[#27272a] border-indigo-500/50' : 'border-transparent hover:bg-[#18181b]'}`}
                              >
                                  <div className="w-3 h-3 rounded-full" style={{background: l.color}}></div>
                                  <span className="truncate flex-1 text-xs">{ANIMATION_STYLES.find(s=>s.id===l.type)?.label || 'Box'}</span>
                                  {selectedLayerId === l.id && <Trash2 size={12} className="text-gray-500 hover:text-red-400" onClick={(e) => {e.stopPropagation(); setLayers(prev=>prev.filter(x=>x.id!==l.id)); setSelectedLayerId(null);}} />}
                              </div>
                          ))}
                      </div>
                  </div>
              )}

              {/* GLOBAL */}
              <div className="pt-4 border-t border-[#27272a] space-y-4">
                  <p className="text-xs font-semibold text-gray-500 uppercase">Global</p>
                  <div>
                      <div className="flex justify-between text-xs text-gray-400 mb-1"><span>Duration</span><span>{config.duration}s</span></div>
                      <input type="range" min="1" max="10" step="0.5" value={config.duration} onChange={e=>setConfig({...config, duration: parseFloat(e.target.value)})} className="w-full accent-indigo-500 h-1 bg-[#27272a] rounded-full appearance-none"/>
                  </div>
                  <div>
                      <div className="flex justify-between text-xs text-gray-400 mb-1"><span>Dimming</span><span>{(config.bgDimming*100).toFixed(0)}%</span></div>
                      <input type="range" min="0" max="0.9" step="0.1" value={config.bgDimming} onChange={e=>setConfig({...config, bgDimming: parseFloat(e.target.value)})} className="w-full accent-indigo-500 h-1 bg-[#27272a] rounded-full appearance-none"/>
                  </div>
                  <div>
                      <div className="flex justify-between text-xs text-gray-400 mb-1"><span>Vignette</span><span>{(config.vignette*100).toFixed(0)}%</span></div>
                      <input type="range" min="0" max="1" step="0.1" value={config.vignette} onChange={e=>setConfig({...config, vignette: parseFloat(e.target.value)})} className="w-full accent-indigo-500 h-1 bg-[#27272a] rounded-full appearance-none"/>
                  </div>
              </div>
          </div>
      </aside>

      {/* CENTER CANVAS */}
      <main className="flex-1 bg-[#09090b] relative flex flex-col">
          <header className="h-14 border-b border-[#27272a] flex items-center justify-between px-6 bg-[#09090b] z-20">
              <div className="flex items-center gap-2 bg-[#18181b] p-1 rounded-lg border border-[#27272a]">
                  <button onClick={()=>setInteractionMode('draw')} className={`p-1.5 rounded ${interactionMode==='draw'?'bg-[#27272a] text-white':'text-gray-500'}`} title="Draw"><Square size={16}/></button>
                  <button onClick={()=>setInteractionMode('select')} className={`p-1.5 rounded ${interactionMode==='select'?'bg-[#27272a] text-white':'text-gray-500'}`} title="Select"><MousePointer2 size={16}/></button>
              </div>
              <div className="flex items-center gap-3">
                  <button onClick={()=>setIsPlaying(!isPlaying)} className="p-2 hover:bg-[#27272a] rounded-full text-white">{isPlaying?<Pause size={20}/>:<Play size={20}/>}</button>
                  <Button onClick={handleExport} isLoading={isRecording} icon={<Video size={16}/>} className="bg-white text-black hover:bg-gray-200">{isRecording?'Rendering...':'Export'}</Button>
              </div>
          </header>

          <div ref={containerRef} className="flex-1 relative overflow-hidden flex items-center justify-center p-8 bg-[#09090b]">
              {!selectedImage ? (
                  <div className="text-center opacity-40">
                      <ImageIcon size={48} className="mx-auto mb-2"/>
                      <p>No Image Loaded</p>
                  </div>
              ) : (
                  <canvas 
                    ref={canvasRef}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                    className={`shadow-2xl shadow-black border border-[#27272a] ${interactionMode === 'draw' ? 'cursor-crosshair' : 'cursor-default'}`}
                  />
              )}
          </div>
      </main>

      {/* RIGHT PROPERTIES */}
      <aside className="w-80 bg-[#121214] border-l border-[#27272a] flex flex-col z-20">
           <div className="p-4 border-b border-[#27272a] h-14 flex items-center"><span className="font-semibold text-sm">Properties</span></div>
           {!activeLayer ? (
               <div className="flex-1 flex flex-col items-center justify-center text-gray-500 p-8 text-center opacity-50">
                   <Layers size={32} className="mb-2"/>
                   <p className="text-sm">Select a layer to edit</p>
               </div>
           ) : (
               <div className="flex-1 overflow-y-auto p-5 space-y-6">
                   {/* Styles */}
                   <div>
                       <p className="text-xs font-semibold text-gray-500 uppercase mb-2">Style</p>
                       <div className="grid grid-cols-5 gap-2">
                           {ANIMATION_STYLES.map(s => {
                               const Icon = (Icons as any)[s.icon] || Icons.Box;
                               return (
                                   <button key={s.id} onClick={()=>updateSelected({type:s.id})} className={`aspect-square flex items-center justify-center rounded border ${activeLayer.type===s.id?'bg-indigo-600 border-indigo-500 text-white':'bg-[#18181b] border-[#27272a] text-gray-500 hover:border-gray-500'}`} title={s.label}>
                                       <Icon size={16}/>
                                   </button>
                               )
                           })}
                       </div>
                       <p className="text-[10px] text-gray-500 mt-2 h-4">{ANIMATION_STYLES.find(s=>s.id===activeLayer.type)?.description}</p>
                   </div>

                   {/* Color */}
                   <div>
                       <p className="text-xs font-semibold text-gray-500 uppercase mb-2">Color</p>
                       <div className="flex flex-wrap gap-2">
                           {DEFAULT_COLORS.map(c => (
                               <button key={c} onClick={()=>updateSelected({color:c})} className={`w-6 h-6 rounded-full border border-white/10 ${activeLayer.color===c?'ring-2 ring-white':''}`} style={{background:c}}/>
                           ))}
                           <input type="color" value={activeLayer.color} onChange={e=>updateSelected({color:e.target.value})} className="w-6 h-6 rounded-full overflow-hidden border-0 p-0"/>
                       </div>
                   </div>

                   {/* Sliders */}
                   <div className="space-y-4">
                       <div>
                           <div className="flex justify-between text-xs text-gray-400 mb-1"><span>Speed</span><span>{activeLayer.speed}x</span></div>
                           <input type="range" min="0.1" max="3" step="0.1" value={activeLayer.speed} onChange={e=>updateSelected({speed:parseFloat(e.target.value)})} className="w-full accent-indigo-500 h-1 bg-[#27272a] rounded-full appearance-none"/>
                       </div>
                       <div>
                           <div className="flex justify-between text-xs text-gray-400 mb-1"><span>Intensity</span><span>{(activeLayer.intensity*100).toFixed(0)}%</span></div>
                           <input type="range" min="0.1" max="1" step="0.1" value={activeLayer.intensity} onChange={e=>updateSelected({intensity:parseFloat(e.target.value)})} className="w-full accent-indigo-500 h-1 bg-[#27272a] rounded-full appearance-none"/>
                       </div>
                       <div>
                           <div className="flex justify-between text-xs text-gray-400 mb-1"><span>Delay</span><span>{activeLayer.delay}s</span></div>
                           <input type="range" min="0" max="5" step="0.1" value={activeLayer.delay} onChange={e=>updateSelected({delay:parseFloat(e.target.value)})} className="w-full accent-indigo-500 h-1 bg-[#27272a] rounded-full appearance-none"/>
                       </div>
                   </div>
               </div>
           )}
      </aside>

    </div>
  );
};

export default App;

